            data = [{'series_id': 'UNRATE', 'series_title': 'Unemployment Rate', 'survey_name': 'Current Population Survey'}, {'series_id': 'PAYEMS', 'series_title': 'All Employees: Total Nonfarm Payrolls', 'survey_name': 'Current Employment Statistics survey (National)'}, {'series_id': 'LNS14000000', 'series_title': 'Unemployment Rate', 'survey_name': 'Labor Force Statistics from the Current Population Survey'}]
