def _parse_xml_to_dataframe(self, xml_string: str) -> pd.DataFrame:
    """Parse the OECD XML and return a dataframe."""
    try:
        root = fromstring(xml_string)
        namespaces = {'message': 'http://www.sdmx.org/resources/sdmxml/schemas/v2_1/message', 'generic': 'http://www.sdmx.org/resources/sdmxml/schemas/v2_1/data/generic'}
        data = []
        for series in root.findall('.//generic:Series', namespaces=namespaces):
            series_data = {}
            for value in series.findall('.//generic:Value', namespaces=namespaces):
                series_data[value.get('id')] = value.get('value')
            for obs in series.findall('./generic:Obs', namespaces=namespaces):
                obs_data = series_data.copy()
                obs_data['TIME_PERIOD'] = obs.find('./generic:ObsDimension', namespaces=namespaces).get('value')
                obs_data['VALUE'] = obs.find('./generic:ObsValue', namespaces=namespaces).get('value')
                data.append(obs_data)
        return pd.DataFrame(data)
    except Exception as e:
        raise ValueError(f'Failed to parse XML: {str(e)}')

class CongressGovWrapper:
    """Modular Congress.gov API wrapper with fault tolerance"""

    def __init__(self, api_key: Optional[str]=None):
        self.api_key = api_key or os.environ.get('CONGRESS_GOV_API_KEY', '')
        self.session = requests.Session()
        self.session.headers.update({'User-Agent': 'Fincept-Terminal/1.0', 'Accept': 'application/json'})

    def _make_request(self, url: str, method: str='GET', params: Optional[Dict]=None) -> Dict[str, Any]:
        """Make HTTP request with comprehensive error handling"""
        try:
            if not self.api_key:
                return {'error': 'Congress.gov API key not configured. Please set CONGRESS_GOV_API_KEY environment variable.', 'api_key_required': True}
            if '?' in url:
                url += f'&api_key={self.api_key}'
            else:
                url += f'?api_key={self.api_key}'
            response = self.session.request(method=method, url=url, params=params, timeout=30)
            response.raise_for_status()
            try:
                data = response.json()
                return {'success': True, 'data': data}
            except json.JSONDecodeError:
                return {'error': 'Invalid JSON response', 'json_error': True}
        except requests.exceptions.Timeout:
            return {'error': 'Request timeout', 'timeout': True, 'status_code': None}
        except requests.exceptions.ConnectionError:
            return {'error': 'Connection error', 'connection_error': True, 'status_code': None}
        except requests.exceptions.HTTPError as e:
            if response.status_code == 401:
                return {'error': 'Invalid API key', 'auth_error': True, 'status_code': response.status_code}
            elif response.status_code == 403:
                return {'error': 'Rate limit exceeded', 'rate_limit_error': True, 'status_code': response.status_code}
            elif response.status_code == 404:
                return {'error': 'Resource not found', 'not_found': True, 'status_code': response.status_code}
            else:
                return {'error': f'HTTP error: {e}', 'http_error': True, 'status_code': response.status_code}
        except requests.exceptions.RequestException as e:
            return {'error': f'Request error: {e}', 'request_error': True, 'status_code': None}
        except Exception as e:
            return {'error': f'Unexpected error: {e}', 'general_error': True, 'status_code': None}

    def _year_to_congress(self, year: int) -> int:
        """Map a year (1935-present) to the corresponding U.S. Congress number."""
        if year < 1935:
            raise ValueError('Year must be 1935 or later.')
        congress_number = 74 + (year - 1935) // 2
        return congress_number

    def _get_congress_from_params(self, start_date: Optional[str]=None, end_date: Optional[str]=None, congress: Optional[int]=None) -> int:
        """Determine congress number from various parameters"""
        if congress:
            return congress
        current_year = datetime.now().year
        current_congress = self._year_to_congress(current_year)
        if start_date and (not end_date):
            try:
                start_year = datetime.fromisoformat(start_date).year
                return self._year_to_congress(start_year)
            except:
                return current_congress
        elif end_date and (not start_date):
            try:
                end_year = datetime.fromisoformat(end_date).year
                return self._year_to_congress(end_year)
            except:
                return current_congress
        else:
            return current_congress

    def get_congress_bills(self, congress: Optional[int]=None, bill_type: Optional[str]=None, start_date: Optional[str]=None, end_date: Optional[str]=None, limit: Optional[int]=None, offset: Optional[int]=0, sort_by: str='desc', get_all: bool=False) -> Dict[str, Any]:
        """
        Get US Congressional bills

        Args:
            congress: Congress number (e.g., 118 for 118th Congress)
            bill_type: Bill type (hr, s, hjres, sjres, hconres, sconres, hres, sres)
            start_date: Start date in ISO format (YYYY-MM-DD)
            end_date: End date in ISO format (YYYY-MM-DD)
            limit: Maximum number of bills to return (default 100, max 250)
            offset: Number of results to skip
            sort_by: Sort order (asc/desc)
            get_all: If True, fetch all bills (ignores limit)
        """
        try:
            if bill_type and bill_type not in BILL_TYPES:
                return CongressGovError('congress_bills', f'Invalid bill_type: {bill_type}. Must be one of: {', '.join(BILL_TYPES)}').to_dict()
            congress_num = self._get_congress_from_params(start_date, end_date, congress)
            if bill_type:
                url = f'{BASE_URL}bill/{congress_num}/{bill_type}'
            else:
                url = f'{BASE_URL}bill/{congress_num}'
            params = []
            if start_date:
                params.append(f'fromDateTime={start_date}T00:00:00Z')
            if end_date:
                params.append(f'toDateTime={end_date}T23:59:59Z')
            if get_all and bill_type and congress_num:
                return self._get_all_bills_by_type(congress_num, bill_type, start_date, end_date)
            limit_value = limit if limit is not None else 100
            if limit_value > 250:
                limit_value = 250
            params.append(f'limit={limit_value}')
            params.append(f'offset={offset}')
            params.append(f'sort=updateDate+{sort_by}')
            params.append('format=json')
            if params:
                url += '?' + '&'.join(params)
            result = self._make_request(url)
            if 'error' in result:
                return CongressGovError('congress_bills', result['error'], result.get('status_code')).to_dict()
            data = result.get('data', {})
            bills = data.get('bills', [])
            transformed_bills = []
            for bill in bills:
                latest_action = bill.get('latestAction', {})
                transformed_bill = {'congress': bill.get('congress'), 'bill_type': bill.get('type'), 'bill_number': bill.get('number'), 'bill_url': bill.get('url'), 'title': bill.get('title'), 'origin_chamber': bill.get('originChamber'), 'origin_chamber_code': bill.get('originChamberCode'), 'update_date': bill.get('updateDate'), 'update_date_including_text': bill.get('updateDateIncludingText'), 'latest_action_date': latest_action.get('actionDate'), 'latest_action': latest_action.get('text')}
                transformed_bills.append(transformed_bill)
            pagination = data.get('pagination', {})
            return {'success': True, 'endpoint': 'congress_bills', 'congress': congress_num, 'filters': {'bill_type': bill_type, 'start_date': start_date, 'end_date': end_date, 'limit': limit_value, 'offset': offset, 'sort_by': sort_by, 'get_all': get_all}, 'total_bills': len(transformed_bills), 'pagination': pagination, 'bills': transformed_bills, 'timestamp': int(datetime.now().timestamp())}
        except Exception as e:
            return CongressGovError('congress_bills', str(e)).to_dict()

    def _get_all_bills_by_type(self, congress: int, bill_type: str, start_date: Optional[str]=None, end_date: Optional[str]=None) -> Dict[str, Any]:
        """Fetch all bills of a specific type for a given congress"""
        try:
            all_bills = []
            limit = 250
            offset = 0
            total_fetched = 0
            while True:
                url = f'{BASE_URL}bill/{congress}/{bill_type}'
                params = []
                if start_date:
                    params.append(f'fromDateTime={start_date}T00:00:00Z')
                if end_date:
                    params.append(f'toDateTime={end_date}T23:59:59Z')
                params.append(f'limit={limit}')
                params.append(f'offset={offset}')
                params.append('sort=updateDate+desc')
                params.append('format=json')
                if params:
                    url += '?' + '&'.join(params)
                result = self._make_request(url)
                if 'error' in result:
                    if total_fetched == 0:
                        return CongressGovError('congress_bills', result['error'], result.get('status_code')).to_dict()
                    break
                data = result.get('data', {})
                bills = data.get('bills', [])
                if not bills:
                    break
                for bill in bills:
                    latest_action = bill.get('latestAction', {})
                    transformed_bill = {'congress': bill.get('congress'), 'bill_type': bill.get('type'), 'bill_number': bill.get('number'), 'bill_url': bill.get('url'), 'title': bill.get('title'), 'origin_chamber': bill.get('originChamber'), 'origin_chamber_code': bill.get('originChamberCode'), 'update_date': bill.get('updateDate'), 'update_date_including_text': bill.get('updateDateIncludingText'), 'latest_action_date': latest_action.get('actionDate'), 'latest_action': latest_action.get('text')}
                    all_bills.append(transformed_bill)
                total_fetched += len(bills)
                pagination = data.get('pagination', {})
                count = pagination.get('count', 0)
                if total_fetched >= count or len(bills) < limit:
                    break
                offset += limit
            return {'success': True, 'endpoint': 'congress_bills', 'congress': congress, 'bill_type': bill_type, 'total_bills': len(all_bills), 'bills': all_bills, 'timestamp': int(datetime.now().timestamp())}
        except Exception as e:
            return CongressGovError('congress_bills', str(e)).to_dict()

    def get_bill_info(self, bill_url: str) -> Dict[str, Any]:
        """
        Get detailed information about a specific bill

        Args:
            bill_url: Bill URL or bill identifier (e.g., "119/s/1947" or full URL)
        """
        try:
            if bill_url[0].isdigit() or (bill_url[0] == '/' and len(bill_url) > 1 and bill_url[1].isdigit()):
                clean_identifier = bill_url[1:] if bill_url[0] == '/' else bill_url
                url = f'{BASE_URL}bill/{clean_identifier}?format=json'
            elif not bill_url.startswith(BASE_URL):
                url = f'{BASE_URL}bill/{bill_url}?format=json'
            else:
                url = bill_url if '?' in bill_url else f'{bill_url}?format=json'
            result = self._make_request(url)
            if 'error' in result:
                return CongressGovError('bill_info', result['error'], result.get('status_code')).to_dict()
            data = result.get('data', {})
            bill_data = data.get('bill', {})
            if not bill_data:
                return CongressGovError('bill_info', 'Bill not found', 404).to_dict()
            additional_data = {}
            cosponsors_data = bill_data.get('cosponsors', {})
            if cosponsors_data.get('count', 0) > 0:
                cosponsors_url = cosponsors_data.get('url', '').replace('?format=json', f'?format=json&api_key={self.api_key}')
                cosponsors_result = self._make_request(cosponsors_url)
                if cosponsors_result.get('success'):
                    additional_data['cosponsors'] = cosponsors_result['data'].get('cosponsors', [])
            subjects_data = bill_data.get('subjects', {})
            if subjects_data.get('count', 0) > 0:
                subjects_url = subjects_data.get('url', '').replace('?format=json', f'?format=json&api_key={self.api_key}')
                subjects_result = self._make_request(subjects_url)
                if subjects_result.get('success'):
                    additional_data['subjects'] = subjects_result['data'].get('subjects', {}).get('legislativeSubjects', [])
            summaries_data = bill_data.get('summaries', {})
            if summaries_data.get('count', 0) > 0:
                summaries_url = summaries_data.get('url', '').replace('?format=json', f'?format=json&api_key={self.api_key}')
                summaries_result = self._make_request(summaries_url)
                if summaries_result.get('success'):
                    additional_data['summaries'] = summaries_result['data'].get('summaries', [])
            committees_data = bill_data.get('committees', {})
            if committees_data.get('count', 0) > 0:
                committees_url = committees_data.get('url', '').replace('?format=json', f'?format=json&api_key={self.api_key}')
                committees_result = self._make_request(committees_url)
                if committees_result.get('success'):
                    additional_data['committees'] = committees_result['data'].get('committees', [])
            actions_data = bill_data.get('actions', {})
            if actions_data.get('count', 0) > 0:
                actions_url = actions_data.get('url', '').replace('?format=json', f'?format=json&api_key={self.api_key}')
                actions_result = self._make_request(actions_url)
                if actions_result.get('success'):
                    additional_data['actions'] = actions_result['data'].get('actions', [])
            titles_data = bill_data.get('titles', {})
            if titles_data.get('count', 0) > 0:
                titles_url = titles_data.get('url', '').replace('?format=json', f'?format=json&api_key={self.api_key}')
                titles_result = self._make_request(titles_url)
                if titles_result.get('success'):
                    additional_data['titles'] = titles_result['data'].get('titles', [])
            bill_data.update(additional_data)
            markdown_content = self._generate_bill_markdown(bill_data)
            return {'success': True, 'endpoint': 'bill_info', 'bill_url': url, 'bill_data': bill_data, 'markdown_content': markdown_content, 'timestamp': int(datetime.now().timestamp())}
        except Exception as e:
            return CongressGovError('bill_info', str(e)).to_dict()

    def _generate_bill_markdown(self, bill_data: Dict[str, Any]) -> str:
        """Generate markdown content for bill info"""
        try:
            title = bill_data.get('title', 'Unknown Title')
            congress = bill_data.get('congress', 'Unknown')
            number = bill_data.get('number', 'Unknown')
            bill_type = bill_data.get('type', 'Unknown')
            chamber = bill_data.get('originChamber', 'Unknown')
            introduced_date = bill_data.get('introducedDate', 'Unknown')
            update_date = bill_data.get('updateDate', 'Unknown')
            latest_action = bill_data.get('latestAction', {})
            latest_action_date = latest_action.get('actionDate', 'Unknown')
            latest_action_text = latest_action.get('text', 'No action taken')
            markdown = f'# {title}\n\n## Basic Information\n- **Congress**: {congress}\n- **Bill Number**: {number}\n- **Type**: {bill_type}\n- **Chamber**: {chamber}\n- **Introduced**: {introduced_date}\n- **Last Updated**: {update_date}\n- **Latest Action**: {latest_action_date} - {latest_action_text}\n'
            policy_area = bill_data.get('policyArea', {}).get('name', '')
            if policy_area:
                markdown += f'- **Policy Area**: {policy_area}\n'
            sponsors = bill_data.get('sponsors', [])
            if sponsors:
                markdown += '\n## Sponsors\n\n'
                for sponsor in sponsors:
                    sponsor_name = sponsor.get('fullName', 'Unknown')
                    markdown += f'- **{sponsor_name}**\n'
            cosponsors = bill_data.get('cosponsors', [])
            if cosponsors:
                markdown += '\n## Cosponsors\n\n'
                for cosponsor in cosponsors:
                    cosponsor_name = cosponsor.get('fullName', 'Unknown')
                    is_original = cosponsor.get('isOriginalCosponsor', False)
                    sponsorship_date = cosponsor.get('sponsorshipDate', 'Unknown')
                    if is_original:
                        cosponsor_name += ' (Original Cosponsor)'
                    markdown += f'- **{cosponsor_name}** ({sponsorship_date})\n'
            summaries = bill_data.get('summaries', [])
            if summaries:
                markdown += '\n## Summaries\n\n'
                for summary in summaries:
                    summary_text = self._html_to_markdown(summary.get('text', ''))
                    markdown += f'{summary_text}\n\n'
            actions = bill_data.get('actions', [])
            if actions:
                markdown += '\n## Actions\n\n'
                for action in actions:
                    action_date = action.get('actionDate', 'Unknown')
                    action_text = action.get('text', 'Unknown')
                    action_type = action.get('type', 'Unknown')
                    markdown += f'- **{action_date}**: ({action_type})\n  - {action_text}\n'
            return markdown
        except Exception as e:
            return f'Error generating markdown: {str(e)}'

    def _html_to_markdown(self, html_text: str) -> str:
        """Convert HTML to Markdown"""
        if not html_text:
            return ''
        try:
            text = re.sub('<[^>]+>', '', html_text)
            text = re.sub('\\s+', ' ', text).strip()
            return text
        except:
            return html_text

    def get_bill_text(self, bill_url: str) -> Dict[str, Any]:
        """
        Get available text versions for a bill

        Args:
            bill_url: Bill URL
        """
        try:
            if '?' in bill_url:
                text_url = bill_url.replace('?', '/text?')
            else:
                text_url = f'{bill_url.rstrip('/')}/text?format=json'
            result = self._make_request(text_url)
            if 'error' in result:
                return CongressGovError('bill_text', result['error'], result.get('status_code')).to_dict()
            data = result.get('data', {})
            text_versions = data.get('textVersions', [])
            if not text_versions:
                return {'success': True, 'endpoint': 'bill_text', 'bill_url': bill_url, 'message': 'No text available for this bill currently.', 'text_versions': [], 'timestamp': int(datetime.now().timestamp())}
            processed_versions = []
            for version in text_versions:
                processed_version = {'version_type': version.get('type', ''), 'version_date': version.get('date', ''), 'formats': {}}
                formats = version.get('formats', [])
                for fmt in formats:
                    doc_type = fmt.get('type', '').replace('Formatted ', '').lower()
                    doc_url = fmt.get('url', '')
                    processed_version['formats'][doc_type] = doc_url
                processed_versions.append(processed_version)
            return {'success': True, 'endpoint': 'bill_text', 'bill_url': bill_url, 'text_versions': processed_versions, 'timestamp': int(datetime.now().timestamp())}
        except Exception as e:
            return CongressGovError('bill_text', str(e)).to_dict()

    def download_bill_text(self, text_url: str) -> Dict[str, Any]:
        """
        Download bill text document

        Args:
            text_url: Direct URL to bill text document
        """
        try:
            if 'congress.gov' not in text_url:
                return CongressGovError('download_bill_text', f'Invalid URL: {text_url}. Must be a valid Congress.gov URL.').to_dict()
            response = self.session.get(text_url, timeout=30)
            response.raise_for_status()
            filename = text_url.split('/')[-1]
            content_type = response.headers.get('content-type', '')
            if 'pdf' in content_type.lower() or filename.lower().endswith('.pdf'):
                pdf_content = base64.b64encode(response.content).decode('utf-8')
                return {'success': True, 'endpoint': 'download_bill_text', 'content': pdf_content, 'filename': filename, 'data_format': {'data_type': 'pdf', 'filename': filename}, 'timestamp': int(datetime.now().timestamp())}
            else:
                text_content = response.text
                return {'success': True, 'endpoint': 'download_bill_text', 'content': text_content, 'filename': filename, 'data_format': {'data_type': 'text', 'filename': filename}, 'timestamp': int(datetime.now().timestamp())}
        except Exception as e:
            return CongressGovError('download_bill_text', str(e)).to_dict()

    def get_comprehensive_bill_data(self, bill_url: str) -> Dict[str, Any]:
        """Get comprehensive data for a bill from multiple endpoints"""
        result = {'success': True, 'bill_url': bill_url, 'timestamp': int(datetime.now().timestamp()), 'endpoints': {}, 'failed_endpoints': []}
        endpoints = [('bill_info', lambda: self.get_bill_info(bill_url)), ('bill_text', lambda: self.get_bill_text(bill_url))]
        overall_success = False
        for endpoint_name, endpoint_func in endpoints:
            try:
                endpoint_result = endpoint_func()
                result['endpoints'][endpoint_name] = endpoint_result
                if endpoint_result.get('success'):
                    overall_success = True
                else:
                    result['failed_endpoints'].append({'endpoint': endpoint_name, 'error': endpoint_result.get('error', 'Unknown error')})
            except Exception as e:
                result['failed_endpoints'].append({'endpoint': endpoint_name, 'error': str(e)})
        result['success'] = overall_success
        return result

    def get_bill_summary_by_congress(self, congress: Optional[int]=None, limit: int=50) -> Dict[str, Any]:
        """Get a summary of bills by type for a given congress"""
        try:
            if not congress:
                congress = self._year_to_congress(datetime.now().year)
            result = {'success': True, 'endpoint': 'bill_summary', 'congress': congress, 'bill_types': {}, 'timestamp': int(datetime.now().timestamp())}
            total_bills = 0
            for bill_type in BILL_TYPES:
                try:
                    bills_result = self.get_congress_bills(congress=congress, bill_type=bill_type, limit=limit, sort_by='desc')
                    if bills_result.get('success'):
                        bills_count = bills_result.get('total_bills', 0)
                        result['bill_types'][bill_type] = {'count': bills_count, 'latest_bills': bills_result.get('bills', [])[:5]}
                        total_bills += bills_count
                    else:
                        result['bill_types'][bill_type] = {'error': bills_result.get('error', 'Unknown error'), 'count': 0}
                except Exception as e:
                    result['bill_types'][bill_type] = {'error': str(e), 'count': 0}
            result['total_bills'] = total_bills
            return result
        except Exception as e:
            return CongressGovError('bill_summary', str(e)).to_dict()

def _year_to_congress(self, year: int) -> int:
    """Map a year (1935-present) to the corresponding U.S. Congress number."""
    if year < 1935:
        raise ValueError('Year must be 1935 or later.')
    congress_number = 74 + (year - 1935) // 2
    return congress_number

class SECDataWrapper:
    """Modular SEC data wrapper with fault-tolerant endpoints"""

    def __init__(self):
        self.base_url = 'https://www.sec.gov'
        self.data_url = 'https://data.sec.gov'
        self.session = requests.Session()
        self.session.headers.update({'User-Agent': 'Fincept Terminal - financial analysis tool (contact@fincept.com)', 'Accept-Encoding': 'gzip, deflate', 'Accept': 'application/json'})
        self.common_form_types = ['10-K', '10-Q', '8-K', '10-D', '20-F', '40-F', '6-K', '8-A', 'S-1', 'S-3', 'S-4', 'S-8', 'F-1', 'F-3', 'F-4', '424A', '424B', 'SC 13D', 'SC 13G', '13F-HR', '13F-NT', '3', '4', '5', '144', 'N-1A', 'N-2', 'N-CSR', 'N-PX', 'N-PORT', '485BPOS']
        self.taxonomy_facts = ['Revenues', 'RevenueFromContractWithCustomerExcludingAssessedTax', 'NetIncomeLoss', 'Assets', 'Liabilities', 'StockholdersEquity', 'CashAndCashEquivalentsAtCarryingValue', 'AccountsReceivableNetCurrent', 'InventoryNet', 'PropertyPlantAndEquipmentNet', 'Goodwill', 'LongTermDebt', 'OperatingIncomeLoss', 'EarningsPerShareBasic', 'EarningsPerShareDiluted', 'CostOfGoodsAndServicesSold', 'SellingGeneralAndAdministrativeExpense', 'ResearchAndDevelopmentExpense', 'InterestExpenseDebt', 'IncomeTaxExpenseBenefit']
        self.transaction_codes = {'A': 'Grant, award or other acquisition', 'C': 'Conversion of derivative security', 'D': 'Disposition to the issuer', 'E': 'Expiration of short derivative position', 'F': 'Payment of exercise price or tax liability', 'G': 'Bona fide gift', 'H': 'Expiration of long derivative position', 'I': 'Discretionary transaction', 'J': 'Other acquisition or disposition', 'L': 'Small acquisition under Rule 16a-6', 'M': 'Exercise or conversion of derivative security', 'O': 'Exercise of out-of-the-money derivative security', 'P': 'Open market or private purchase', 'S': 'Open market or private sale', 'U': 'Disposition pursuant to a tender of shares', 'W': 'Acquisition or disposition by will or the laws of descent and distribution', 'X': 'Exercise of in-the-money or at-the-money derivative security', 'Z': 'Deposit into or withdrawal from voting trust'}

    def _make_request(self, url: str, use_cache: bool=True) -> Dict[str, Any]:
        """Make HTTP request with proper headers and error handling"""
        try:
            time.sleep(0.1)
            response = self.session.get(url, timeout=30)
            response.raise_for_status()
            data = response.json()
            if isinstance(data, dict) and 'error' in data:
                raise Exception(f'SEC API error: {data['error']}')
            return data
        except requests.exceptions.RequestException as e:
            raise Exception(f'HTTP request failed: {str(e)}')
        except json.JSONDecodeError as e:
            raise Exception(f'JSON decode error: {str(e)}')

    def _normalize_cik(self, cik: Union[str, int]) -> str:
        """Normalize CIK to 10-digit format with leading zeros"""
        cik_str = str(cik).strip()
        cik_str = cik_str.lstrip('0')
        return cik_str.zfill(10)

    def _format_date(self, date_str: str) -> str:
        """Format date string to SEC format (YYYYMMDD)"""
        try:
            if not date_str:
                return ''
            if '-' in date_str:
                return date_str.replace('-', '')
            elif len(date_str) == 8 and date_str.isdigit():
                return date_str
            else:
                date_obj = pd.to_datetime(date_str)
                return date_obj.strftime('%Y%m%d')
        except:
            return date_str

    def get_company_filings(self, symbol: Optional[str]=None, cik: Optional[Union[str, int]]=None, form_type: Optional[str]=None, start_date: Optional[str]=None, end_date: Optional[str]=None, limit: Optional[int]=100) -> Dict[str, Any]:
        """Get company filings from SEC database"""
        try:
            if not symbol and (not cik):
                return {'error': SECError('company_filings', 'Either symbol or CIK must be provided').to_dict()}
            if symbol and (not cik):
                cik_result = self.get_cik_map(symbol)
                if not cik_result.get('success'):
                    return cik_result
                cik = cik_result['data'].get('cik')
            if not cik:
                return {'error': SECError('company_filings', 'CIK not found for the provided symbol').to_dict()}
            normalized_cik = self._normalize_cik(cik)
            url = f'{self.data_url}/submissions/CIK{normalized_cik}.json'
            data = self._make_request(url)
            if not data or 'filings' not in data:
                return {'error': SECError('company_filings', f'No filings found for CIK: {cik}').to_dict()}
            filings_data = data['filings']['recent']
            filings_df = pd.DataFrame(filings_data)
            if form_type:
                form_types = [ft.upper().strip() for ft in form_type.split(',')]
                filings_df = filings_df[filings_df['form'].isin(form_types)]
            if start_date:
                start_formatted = self._format_date(start_date)
                filings_df = filings_df[filings_df['filingDate'] >= start_formatted]
            if end_date:
                end_formatted = self._format_date(end_date)
                filings_df = filings_df[filings_df['filingDate'] <= end_formatted]
            filings_df = filings_df.sort_values('filingDate', ascending=False)
            if limit and limit > 0:
                filings_df = filings_df.head(limit)
            base_url = f'{self.base_url}/Archives/edgar/data/{str(int(normalized_cik))}/'

            def format_urls(row):
                accession = row['accessionNumber']
                accession_clean = accession.replace('-', '')
                primary_doc = row['primaryDocument']
                return {'filing_url': f'{base_url}{accession_clean}/{primary_doc}', 'complete_submission_url': f'{base_url}{accession}.txt', 'filing_detail_url': f'{base_url}{accession}-index.htm'}
            url_data = filings_df.apply(format_urls, axis=1)
            url_df = pd.DataFrame(list(url_data))
            filings_df = pd.concat([filings_df.reset_index(drop=True), url_df], axis=1)
            filings_list = filings_df.to_dict('records')
            return {'success': True, 'data': filings_list, 'parameters': {'symbol': symbol, 'cik': str(cik), 'form_type': form_type, 'start_date': start_date, 'end_date': end_date, 'limit': limit}}
        except Exception as e:
            return {'error': SECError('company_filings', str(e)).to_dict()}

