def find_next_available_position(occupied_grid, col_span, row_span, start_row=0):
    """Find the next available position in the grid that can fit the item"""
    row = start_row
    while True:
        for col in range(COLS - col_span + 1):
            can_place = True
            for r in range(row, row + row_span):
                for c in range(col, col + col_span):
                    if occupied_grid.get((r, c), False):
                        can_place = False
                        break
                if not can_place:
                    break
            if can_place:
                return (row, col)
        row += 1

def mark_cells_occupied(occupied_grid, row, col, row_span, col_span):
    """Mark cells as occupied in the grid"""
    for r in range(row, row + row_span):
        for c in range(col, col + col_span):
            occupied_grid[r, c] = True

class TechnicalIndicators:
    """
    A comprehensive collection of technical analysis indicators.
    
    This class provides static methods for calculating various technical indicators
    used in financial market analysis.
    """

    @staticmethod
    def sma(data: Union[pd.Series, np.ndarray], period: int=20) -> pd.Series:
        """
        Simple Moving Average (SMA)
        
        Args:
            data: Price data (typically closing prices)
            period: Number of periods for the moving average
            
        Returns:
            pd.Series: Simple moving average values
        """
        try:
            if isinstance(data, np.ndarray):
                data = pd.Series(data)
            return data.rolling(window=period, min_periods=period).mean()
        except Exception as e:
            print(f'Error calculating SMA: {e}')
            return pd.Series(dtype=float)

    @staticmethod
    def ema(data: Union[pd.Series, np.ndarray], period: int=20) -> pd.Series:
        """
        Exponential Moving Average (EMA)
        
        Args:
            data: Price data (typically closing prices)
            period: Number of periods for the exponential moving average
            
        Returns:
            pd.Series: Exponential moving average values
        """
        try:
            if isinstance(data, np.ndarray):
                data = pd.Series(data)
            return data.ewm(span=period, adjust=False).mean()
        except Exception as e:
            print(f'Error calculating EMA: {e}')
            return pd.Series(dtype=float)

    @staticmethod
    def rsi(data: Union[pd.Series, np.ndarray], period: int=14) -> pd.Series:
        """
        Relative Strength Index (RSI)
        
        Args:
            data: Price data (typically closing prices)
            period: Number of periods for RSI calculation
            
        Returns:
            pd.Series: RSI values (0-100)
        """
        try:
            if isinstance(data, np.ndarray):
                data = pd.Series(data)
            delta = data.diff()
            gain = delta.where(delta > 0, 0).rolling(window=period).mean()
            loss = (-delta.where(delta < 0, 0)).rolling(window=period).mean()
            rs = gain / loss
            rsi = 100 - 100 / (1 + rs)
            return rsi
        except Exception as e:
            print(f'Error calculating RSI: {e}')
            return pd.Series(dtype=float)

    @staticmethod
    def macd(data: Union[pd.Series, np.ndarray], fast: int=12, slow: int=26, signal: int=9) -> Tuple[pd.Series, pd.Series, pd.Series]:
        """
        Moving Average Convergence Divergence (MACD)
        
        Args:
            data: Price data (typically closing prices)
            fast: Fast EMA period
            slow: Slow EMA period
            signal: Signal line EMA period
            
        Returns:
            Tuple[pd.Series, pd.Series, pd.Series]: (MACD line, Signal line, Histogram)
        """
        try:
            if isinstance(data, np.ndarray):
                data = pd.Series(data)
            ema_fast = data.ewm(span=fast).mean()
            ema_slow = data.ewm(span=slow).mean()
            macd_line = ema_fast - ema_slow
            signal_line = macd_line.ewm(span=signal).mean()
            histogram = macd_line - signal_line
            return (macd_line, signal_line, histogram)
        except Exception as e:
            print(f'Error calculating MACD: {e}')
            return (pd.Series(dtype=float), pd.Series(dtype=float), pd.Series(dtype=float))

    @staticmethod
    def bollinger_bands(data: Union[pd.Series, np.ndarray], period: int=20, std_dev: float=2) -> Tuple[pd.Series, pd.Series, pd.Series]:
        """
        Bollinger Bands
        
        Args:
            data: Price data (typically closing prices)
            period: Number of periods for moving average
            std_dev: Number of standard deviations for bands
            
        Returns:
            Tuple[pd.Series, pd.Series, pd.Series]: (Upper band, Middle band, Lower band)
        """
        try:
            if isinstance(data, np.ndarray):
                data = pd.Series(data)
            middle_band = data.rolling(window=period).mean()
            std = data.rolling(window=period).std()
            upper_band = middle_band + std * std_dev
            lower_band = middle_band - std * std_dev
            return (upper_band, middle_band, lower_band)
        except Exception as e:
            print(f'Error calculating Bollinger Bands: {e}')
            return (pd.Series(dtype=float), pd.Series(dtype=float), pd.Series(dtype=float))

    @staticmethod
    def stochastic_oscillator(high: Union[pd.Series, np.ndarray], low: Union[pd.Series, np.ndarray], close: Union[pd.Series, np.ndarray], k_period: int=14, d_period: int=3) -> Tuple[pd.Series, pd.Series]:
        """
        Stochastic Oscillator
        
        Args:
            high: High prices
            low: Low prices
            close: Closing prices
            k_period: %K period
            d_period: %D period (smoothing)
            
        Returns:
            Tuple[pd.Series, pd.Series]: (%K, %D)
        """
        try:
            if isinstance(high, np.ndarray):
                high = pd.Series(high)
            if isinstance(low, np.ndarray):
                low = pd.Series(low)
            if isinstance(close, np.ndarray):
                close = pd.Series(close)
            lowest_low = low.rolling(window=k_period).min()
            highest_high = high.rolling(window=k_period).max()
            k_percent = 100 * ((close - lowest_low) / (highest_high - lowest_low))
            d_percent = k_percent.rolling(window=d_period).mean()
            return (k_percent, d_percent)
        except Exception as e:
            print(f'Error calculating Stochastic Oscillator: {e}')
            return (pd.Series(dtype=float), pd.Series(dtype=float))

    @staticmethod
    def williams_r(high: Union[pd.Series, np.ndarray], low: Union[pd.Series, np.ndarray], close: Union[pd.Series, np.ndarray], period: int=14) -> pd.Series:
        """
        Williams %R
        
        Args:
            high: High prices
            low: Low prices
            close: Closing prices
            period: Number of periods
            
        Returns:
            pd.Series: Williams %R values (-100 to 0)
        """
        try:
            if isinstance(high, np.ndarray):
                high = pd.Series(high)
            if isinstance(low, np.ndarray):
                low = pd.Series(low)
            if isinstance(close, np.ndarray):
                close = pd.Series(close)
            highest_high = high.rolling(window=period).max()
            lowest_low = low.rolling(window=period).min()
            williams_r = -100 * ((highest_high - close) / (highest_high - lowest_low))
            return williams_r
        except Exception as e:
            print(f'Error calculating Williams %R: {e}')
            return pd.Series(dtype=float)

    @staticmethod
    def atr(high: Union[pd.Series, np.ndarray], low: Union[pd.Series, np.ndarray], close: Union[pd.Series, np.ndarray], period: int=14) -> pd.Series:
        """
        Average True Range (ATR)
        
        Args:
            high: High prices
            low: Low prices
            close: Closing prices
            period: Number of periods
            
        Returns:
            pd.Series: ATR values
        """
        try:
            if isinstance(high, np.ndarray):
                high = pd.Series(high)
            if isinstance(low, np.ndarray):
                low = pd.Series(low)
            if isinstance(close, np.ndarray):
                close = pd.Series(close)
            tr1 = high - low
            tr2 = abs(high - close.shift())
            tr3 = abs(low - close.shift())
            true_range = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
            atr = true_range.rolling(window=period).mean()
            return atr
        except Exception as e:
            print(f'Error calculating ATR: {e}')
            return pd.Series(dtype=float)

    @staticmethod
    def cci(high: Union[pd.Series, np.ndarray], low: Union[pd.Series, np.ndarray], close: Union[pd.Series, np.ndarray], period: int=20) -> pd.Series:
        """
        Commodity Channel Index (CCI)
        
        Args:
            high: High prices
            low: Low prices
            close: Closing prices
            period: Number of periods
            
        Returns:
            pd.Series: CCI values
        """
        try:
            if isinstance(high, np.ndarray):
                high = pd.Series(high)
            if isinstance(low, np.ndarray):
                low = pd.Series(low)
            if isinstance(close, np.ndarray):
                close = pd.Series(close)
            typical_price = (high + low + close) / 3
            sma_tp = typical_price.rolling(window=period).mean()
            mean_deviation = typical_price.rolling(window=period).apply(lambda x: np.mean(np.abs(x - np.mean(x))))
            cci = (typical_price - sma_tp) / (0.015 * mean_deviation)
            return cci
        except Exception as e:
            print(f'Error calculating CCI: {e}')
            return pd.Series(dtype=float)

    @staticmethod
    def adx(high: Union[pd.Series, np.ndarray], low: Union[pd.Series, np.ndarray], close: Union[pd.Series, np.ndarray], period: int=14) -> Tuple[pd.Series, pd.Series, pd.Series]:
        """
        Average Directional Index (ADX) with +DI and -DI
        
        Args:
            high: High prices
            low: Low prices
            close: Closing prices
            period: Number of periods
            
        Returns:
            Tuple[pd.Series, pd.Series, pd.Series]: (ADX, +DI, -DI)
        """
        try:
            if isinstance(high, np.ndarray):
                high = pd.Series(high)
            if isinstance(low, np.ndarray):
                low = pd.Series(low)
            if isinstance(close, np.ndarray):
                close = pd.Series(close)
            tr1 = high - low
            tr2 = abs(high - close.shift())
            tr3 = abs(low - close.shift())
            tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
            up_move = high - high.shift()
            down_move = low.shift() - low
            plus_dm = np.where((up_move > down_move) & (up_move > 0), up_move, 0)
            minus_dm = np.where((down_move > up_move) & (down_move > 0), down_move, 0)
            plus_dm = pd.Series(plus_dm, index=high.index)
            minus_dm = pd.Series(minus_dm, index=high.index)
            atr = tr.ewm(span=period).mean()
            plus_di = 100 * (plus_dm.ewm(span=period).mean() / atr)
            minus_di = 100 * (minus_dm.ewm(span=period).mean() / atr)
            dx = 100 * abs(plus_di - minus_di) / (plus_di + minus_di)
            adx = dx.ewm(span=period).mean()
            return (adx, plus_di, minus_di)
        except Exception as e:
            print(f'Error calculating ADX: {e}')
            return (pd.Series(dtype=float), pd.Series(dtype=float), pd.Series(dtype=float))

@staticmethod
def sma(data: Union[pd.Series, np.ndarray], period: int=20) -> pd.Series:
    """
        Simple Moving Average (SMA)
        
        Args:
            data: Price data (typically closing prices)
            period: Number of periods for the moving average
            
        Returns:
            pd.Series: Simple moving average values
        """
    try:
        if isinstance(data, np.ndarray):
            data = pd.Series(data)
        return data.rolling(window=period, min_periods=period).mean()
    except Exception as e:
        print(f'Error calculating SMA: {e}')
        return pd.Series(dtype=float)

@staticmethod
def ema(data: Union[pd.Series, np.ndarray], period: int=20) -> pd.Series:
    """
        Exponential Moving Average (EMA)
        
        Args:
            data: Price data (typically closing prices)
            period: Number of periods for the exponential moving average
            
        Returns:
            pd.Series: Exponential moving average values
        """
    try:
        if isinstance(data, np.ndarray):
            data = pd.Series(data)
        return data.ewm(span=period, adjust=False).mean()
    except Exception as e:
        print(f'Error calculating EMA: {e}')
        return pd.Series(dtype=float)

@staticmethod
def rsi(data: Union[pd.Series, np.ndarray], period: int=14) -> pd.Series:
    """
        Relative Strength Index (RSI)
        
        Args:
            data: Price data (typically closing prices)
            period: Number of periods for RSI calculation
            
        Returns:
            pd.Series: RSI values (0-100)
        """
    try:
        if isinstance(data, np.ndarray):
            data = pd.Series(data)
        delta = data.diff()
        gain = delta.where(delta > 0, 0).rolling(window=period).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(window=period).mean()
        rs = gain / loss
        rsi = 100 - 100 / (1 + rs)
        return rsi
    except Exception as e:
        print(f'Error calculating RSI: {e}')
        return pd.Series(dtype=float)

@staticmethod
def macd(data: Union[pd.Series, np.ndarray], fast: int=12, slow: int=26, signal: int=9) -> Tuple[pd.Series, pd.Series, pd.Series]:
    """
        Moving Average Convergence Divergence (MACD)
        
        Args:
            data: Price data (typically closing prices)
            fast: Fast EMA period
            slow: Slow EMA period
            signal: Signal line EMA period
            
        Returns:
            Tuple[pd.Series, pd.Series, pd.Series]: (MACD line, Signal line, Histogram)
        """
    try:
        if isinstance(data, np.ndarray):
            data = pd.Series(data)
        ema_fast = data.ewm(span=fast).mean()
        ema_slow = data.ewm(span=slow).mean()
        macd_line = ema_fast - ema_slow
        signal_line = macd_line.ewm(span=signal).mean()
        histogram = macd_line - signal_line
        return (macd_line, signal_line, histogram)
    except Exception as e:
        print(f'Error calculating MACD: {e}')
        return (pd.Series(dtype=float), pd.Series(dtype=float), pd.Series(dtype=float))

