def standard_normal_cdf(x: Decimal) -> Decimal:
    """Approximate standard normal cumulative distribution function"""
    x_float = float(x)
    if x_float < 0:
        return Decimal('1') - standard_normal_cdf(-x)
    a1 = Decimal('0.254829592')
    a2 = Decimal('-0.284496736')
    a3 = Decimal('1.421413741')
    a4 = Decimal('-1.453152027')
    a5 = Decimal('1.061405429')
    p = Decimal('0.3275911')
    t = Decimal('1') / (Decimal('1') + p * x)
    y = Decimal('1') - ((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t * Decimal(str(math.exp(-float(x * x / Decimal('2')))))
    return y

def black_scholes_call_price(S: Decimal, K: Decimal, T: Decimal, r: Decimal, sigma: Decimal) -> Decimal:
    """Black-Scholes call option price (simplified implementation)"""
    if T <= 0 or sigma <= 0:
        return max(S - K, Decimal('0'))
    d1 = (Decimal(str(math.log(float(S / K)))) + (r + sigma * sigma / Decimal('2')) * T) / (sigma * Decimal(str(math.sqrt(float(T)))))
    d2 = d1 - sigma * Decimal(str(math.sqrt(float(T))))
    call_price = S * standard_normal_cdf(d1) - K * Decimal(str(math.exp(-float(r * T)))) * standard_normal_cdf(d2)
    return call_price

class VolatilityStructure:
    """Term structure of volatility analysis"""

    @staticmethod
    def yield_volatility_structure(historical_yields: Dict[Decimal, List[Decimal]], window_size: int=252) -> Dict[Decimal, Dict[str, Decimal]]:
        """Calculate volatility structure across maturities"""
        volatility_structure = {}
        for maturity, yield_series in historical_yields.items():
            if len(yield_series) < window_size:
                continue
            returns = []
            for i in range(1, len(yield_series)):
                return_val = yield_series[i] - yield_series[i - 1]
                returns.append(return_val)
            volatilities = VolatilityStructure._calculate_rolling_volatility(returns, window_size)
            if volatilities:
                avg_volatility = sum(volatilities) / Decimal(str(len(volatilities)))
                max_volatility = max(volatilities)
                min_volatility = min(volatilities)
                volatility_structure[maturity] = {'average_volatility': avg_volatility, 'maximum_volatility': max_volatility, 'minimum_volatility': min_volatility, 'current_volatility': volatilities[-1] if volatilities else Decimal('0')}
        return volatility_structure

    @staticmethod
    def _calculate_rolling_volatility(returns: List[Decimal], window: int) -> List[Decimal]:
        """Calculate rolling volatility"""
        volatilities = []
        for i in range(window, len(returns) + 1):
            window_returns = returns[i - window:i]
            mean_return = sum(window_returns) / Decimal(str(len(window_returns)))
            variance = sum(((r - mean_return) ** 2 for r in window_returns)) / Decimal(str(len(window_returns) - 1))
            volatility = variance ** Decimal('0.5') * Decimal('252') ** Decimal('0.5')
            volatilities.append(volatility)
        return volatilities

    @staticmethod
    def volatility_smile_analysis(option_data: Dict[Decimal, Decimal]) -> Dict[str, Decimal]:
        """Analyze volatility smile/skew patterns"""
        if len(option_data) < 3:
            return {'error': 'Insufficient data for smile analysis'}
        strikes = sorted(option_data.keys())
        volatilities = [option_data[strike] for strike in strikes]
        atm_index = len(strikes) // 2
        atm_vol = volatilities[atm_index]
        if len(strikes) >= 3:
            low_strike_idx = len(strikes) // 4
            high_strike_idx = 3 * len(strikes) // 4
            skew_25d = volatilities[low_strike_idx] - volatilities[high_strike_idx]
        else:
            skew_25d = Decimal('0')
        if len(strikes) >= 3:
            butterfly = (volatilities[0] + volatilities[-1]) / Decimal('2') - atm_vol
        else:
            butterfly = Decimal('0')
        return {'atm_volatility': atm_vol, 'volatility_skew_25d': skew_25d, 'volatility_butterfly': butterfly, 'min_volatility': min(volatilities), 'max_volatility': max(volatilities), 'volatility_range': max(volatilities) - min(volatilities)}

    @staticmethod
    def term_structure_volatility_models(forward_rates: List[Decimal], volatilities: List[Decimal], model_type: str='ho_lee') -> Dict[str, any]:
        """Implement term structure volatility models"""
        if len(forward_rates) != len(volatilities):
            raise ValueError('Forward rates and volatilities must have same length')
        if model_type == 'ho_lee':
            return VolatilityStructure._ho_lee_model(forward_rates, volatilities)
        elif model_type == 'hull_white':
            return VolatilityStructure._hull_white_model(forward_rates, volatilities)
        elif model_type == 'black_karasinski':
            return VolatilityStructure._black_karasinski_model(forward_rates, volatilities)
        else:
            raise ValueError(f'Unknown model type: {model_type}')

    @staticmethod
    def _ho_lee_model(forward_rates: List[Decimal], volatilities: List[Decimal]) -> Dict[str, any]:
        """Ho-Lee model: dr = θ(t)dt + σdW"""
        avg_volatility = sum(volatilities) / Decimal(str(len(volatilities)))
        drift_function = []
        for i, rate in enumerate(forward_rates):
            if i == 0:
                drift = rate
            else:
                drift = forward_rates[i] - forward_rates[i - 1]
            drift_function.append(drift)
        return {'model': 'Ho-Lee', 'constant_volatility': avg_volatility, 'drift_function': drift_function, 'mean_reversion': Decimal('0'), 'characteristics': 'Normal rates, constant volatility'}

    @staticmethod
    def _hull_white_model(forward_rates: List[Decimal], volatilities: List[Decimal]) -> Dict[str, any]:
        """Hull-White model: dr = [θ(t) - ar]dt + σdW"""
        avg_volatility = sum(volatilities) / Decimal(str(len(volatilities)))
        mean_reversion = Decimal('0.1')
        long_term_mean = sum(forward_rates) / Decimal(str(len(forward_rates)))
        return {'model': 'Hull-White', 'volatility': avg_volatility, 'mean_reversion_speed': mean_reversion, 'long_term_mean': long_term_mean, 'characteristics': 'Normal rates, mean-reverting'}

    @staticmethod
    def _black_karasinski_model(forward_rates: List[Decimal], volatilities: List[Decimal]) -> Dict[str, any]:
        """Black-Karasinski model: d(ln r) = [θ(t) - a ln r]dt + σdW"""
        avg_volatility = sum(volatilities) / Decimal(str(len(volatilities)))
        log_rates = [Decimal(str(math.log(float(rate)))) for rate in forward_rates if rate > 0]
        if log_rates:
            avg_log_rate = sum(log_rates) / Decimal(str(len(log_rates)))
            mean_reversion = Decimal('0.15')
        else:
            avg_log_rate = Decimal('0')
            mean_reversion = Decimal('0')
        return {'model': 'Black-Karasinski', 'volatility': avg_volatility, 'mean_reversion_speed': mean_reversion, 'mean_log_rate': avg_log_rate, 'characteristics': 'Log-normal rates, mean-reverting'}

@staticmethod
def _calculate_rolling_volatility(returns: List[Decimal], window: int) -> List[Decimal]:
    """Calculate rolling volatility"""
    volatilities = []
    for i in range(window, len(returns) + 1):
        window_returns = returns[i - window:i]
        mean_return = sum(window_returns) / Decimal(str(len(window_returns)))
        variance = sum(((r - mean_return) ** 2 for r in window_returns)) / Decimal(str(len(window_returns) - 1))
        volatility = variance ** Decimal('0.5') * Decimal('252') ** Decimal('0.5')
        volatilities.append(volatility)
    return volatilities

class BaseCalculator(ABC):
    """
    Abstract base class for all quantitative calculations.

    Provides common functionality, validation, and standardized interfaces
    for all quantitative analysis modules in Fincept Terminal.
    """

    def __init__(self, precision: int=6, risk_free_rate: float=0.0):
        """
        Initialize base calculator with common parameters.

        Args:
            precision: Number of decimal places for calculations
            risk_free_rate: Default risk-free rate for calculations
        """
        self.precision = precision
        self.risk_free_rate = risk_free_rate
        self.logger = self._setup_logger()
        self.calculation_metadata = {}

    def _setup_logger(self) -> logging.Logger:
        """Setup logger for the calculator."""
        logger = logging.getLogger(f'{self.__class__.__name__}')
        logger.setLevel(logging.INFO)
        return logger

    def _validate_numeric_input(self, data: Any, name: str='data') -> Union[float, np.ndarray, pd.Series]:
        """
        Validate and convert input to appropriate numeric type.

        Args:
            data: Input data to validate
            name: Name of the parameter for error messages

        Returns:
            Validated numeric data

        Raises:
            ValueError: If data cannot be converted to numeric
        """
        if data is None:
            raise ValueError(f'{name} cannot be None')
        if isinstance(data, (int, float)):
            if np.isnan(data) or np.isinf(data):
                raise ValueError(f'{name} contains invalid values (NaN or Inf)')
            return float(data)
        elif isinstance(data, (list, tuple)):
            try:
                arr = np.array(data, dtype=float)
                if np.any(np.isnan(arr)) or np.any(np.isinf(arr)):
                    raise ValueError(f'{name} contains invalid values (NaN or Inf)')
                return arr
            except (ValueError, TypeError):
                raise ValueError(f'{name} cannot be converted to numeric array')
        elif isinstance(data, np.ndarray):
            if not np.issubdtype(data.dtype, np.number):
                raise ValueError(f'{name} must be numeric')
            if np.any(np.isnan(data)) or np.any(np.isinf(data)):
                raise ValueError(f'{name} contains invalid values (NaN or Inf)')
            return data.astype(float)
        elif isinstance(data, pd.Series):
            if not pd.api.types.is_numeric_dtype(data):
                raise ValueError(f'{name} must be numeric')
            if data.isna().any():
                warnings.warn(f'{name} contains NaN values, they will be dropped')
                data = data.dropna()
            return data.astype(float)
        elif isinstance(data, pd.DataFrame):
            if data.empty:
                raise ValueError(f'{name} DataFrame is empty')
            try:
                numeric_data = data.select_dtypes(include=[np.number])
                if numeric_data.empty:
                    raise ValueError(f'{name} DataFrame has no numeric columns')
                return numeric_data.astype(float)
            except Exception:
                raise ValueError(f'{name} DataFrame cannot be converted to numeric')
        else:
            raise ValueError(f'{name} must be numeric (int, float, list, array, or pandas Series/DataFrame)')

    def _validate_positive(self, value: Union[float, np.ndarray], name: str='value') -> Union[float, np.ndarray]:
        """
        Validate that value(s) are positive.

        Args:
            value: Value(s) to validate
            name: Name of the parameter for error messages

        Returns:
            Validated positive value(s)
        """
        validated = self._validate_numeric_input(value, name)
        if isinstance(validated, (int, float)):
            if validated <= 0:
                raise ValueError(f'{name} must be positive, got {validated}')
        elif np.any(validated <= 0):
            raise ValueError(f'{name} must be positive for all values')
        return validated

    def _validate_probability(self, prob: Union[float, np.ndarray], name: str='probability') -> Union[float, np.ndarray]:
        """
        Validate that probability value(s) are between 0 and 1.

        Args:
            prob: Probability value(s) to validate
            name: Name of the parameter for error messages

        Returns:
            Validated probability value(s)
        """
        validated = self._validate_numeric_input(prob, name)
        if isinstance(validated, (int, float)):
            if not 0 <= validated <= 1:
                raise ValueError(f'{name} must be between 0 and 1, got {validated}')
        elif np.any((validated < 0) | (validated > 1)):
            raise ValueError(f'{name} must be between 0 and 1 for all values')
        return validated

    def _validate_returns(self, returns: Union[List, np.ndarray, pd.Series], name: str='returns') -> np.ndarray:
        """
        Validate return data and convert to numpy array.

        Args:
            returns: Return data to validate
            name: Name of the parameter for error messages

        Returns:
            Validated returns as numpy array
        """
        validated = self._validate_numeric_input(returns, name)
        if isinstance(validated, (int, float)):
            raise ValueError(f'{name} must be a sequence of returns, not a single value')
        if isinstance(validated, pd.Series):
            return validated.values
        elif isinstance(validated, pd.DataFrame):
            if validated.shape[1] == 1:
                return validated.iloc[:, 0].values
            else:
                raise ValueError(f'{name} DataFrame must have exactly one column for return calculations')
        return np.array(validated)

    def _round_result(self, result: Union[float, np.ndarray, Dict]) -> Union[float, np.ndarray, Dict]:
        """
        Round result to specified precision.

        Args:
            result: Result to round

        Returns:
            Rounded result
        """
        if isinstance(result, (int, float)):
            return round(result, self.precision)
        elif isinstance(result, np.ndarray):
            return np.round(result, self.precision)
        elif isinstance(result, dict):
            return {k: self._round_result(v) if isinstance(v, (int, float, np.ndarray)) else v for k, v in result.items()}
        else:
            return result

    def _create_result_dict(self, value: Union[float, np.ndarray], method: str, parameters: Dict[str, Any]=None, metadata: Dict[str, Any]=None) -> Dict[str, Any]:
        """
        Create standardized result dictionary.

        Args:
            value: Calculated value
            method: Method used for calculation
            parameters: Parameters used in calculation
            metadata: Additional metadata

        Returns:
            Standardized result dictionary
        """
        result = {'value': self._round_result(value), 'method': method, 'timestamp': datetime.now().isoformat(), 'calculator': self.__class__.__name__}
        if parameters:
            result['parameters'] = parameters
        if metadata:
            result['metadata'] = metadata
        return result

    def _check_data_length(self, data: Union[np.ndarray, pd.Series], min_length: int=2) -> None:
        """
        Check if data has sufficient length for calculations.

        Args:
            data: Data to check
            min_length: Minimum required length

        Raises:
            ValueError: If data length is insufficient
        """
        if len(data) < min_length:
            raise ValueError(f'Insufficient data: need at least {min_length} observations, got {len(data)}')

    def _handle_missing_data(self, data: Union[np.ndarray, pd.Series], method: str='drop') -> Union[np.ndarray, pd.Series]:
        """
        Handle missing data in input.

        Args:
            data: Input data
            method: Method to handle missing data ('drop', 'interpolate', 'forward_fill')

        Returns:
            Data with missing values handled
        """
        if isinstance(data, pd.Series):
            if method == 'drop':
                return data.dropna()
            elif method == 'interpolate':
                return data.interpolate()
            elif method == 'forward_fill':
                return data.fillna(method='ffill')
            else:
                raise ValueError(f'Unknown missing data method: {method}')
        elif isinstance(data, np.ndarray):
            if method == 'drop':
                return data[~np.isnan(data)]
            else:
                series = pd.Series(data)
                return self._handle_missing_data(series, method).values
        return data

    def set_precision(self, precision: int) -> None:
        """Set calculation precision."""
        if precision < 0:
            raise ValueError('Precision must be non-negative')
        self.precision = precision

    def set_risk_free_rate(self, rate: float) -> None:
        """Set default risk-free rate."""
        self.risk_free_rate = self._validate_numeric_input(rate, 'risk_free_rate')

    @abstractmethod
    def calculate(self, *args, **kwargs) -> Dict[str, Any]:
        """
        Abstract method for main calculation.
        Must be implemented by all subclasses.
        """
        pass

    def get_supported_methods(self) -> List[str]:
        """
        Get list of supported calculation methods.
        Should be overridden by subclasses.
        """
        return ['default']

    def validate_method(self, method: str) -> str:
        """
        Validate that the specified method is supported.

        Args:
            method: Method to validate

        Returns:
            Validated method name

        Raises:
            ValueError: If method is not supported
        """
        supported = self.get_supported_methods()
        if method not in supported:
            raise ValueError(f"Method '{method}' not supported. Available methods: {supported}")
        return method

