class CalculatorFactory:
    """
    Factory class for creating calculator instances.
    Provides a centralized way to instantiate different calculators.
    """
    _calculators = {}

    @classmethod
    def register_calculator(cls, name: str, calculator_class: type) -> None:
        """Register a calculator class."""
        cls._calculators[name] = calculator_class

    @classmethod
    def create_calculator(cls, name: str, **kwargs) -> BaseCalculator:
        """Create a calculator instance."""
        if name not in cls._calculators:
            raise ValueError(f"Calculator '{name}' not registered")
        return cls._calculators[name](**kwargs)

    @classmethod
    def list_calculators(cls) -> List[str]:
        """List all registered calculators."""
        return list(cls._calculators.keys())

@classmethod
def create_calculator(cls, name: str, **kwargs) -> BaseCalculator:
    """Create a calculator instance."""
    if name not in cls._calculators:
        raise ValueError(f"Calculator '{name}' not registered")
    return cls._calculators[name](**kwargs)

class CalculationResult:
    """
    Wrapper class for calculation results with additional functionality.
    """

    def __init__(self, result_dict: Dict[str, Any]):
        """Initialize with result dictionary."""
        self._data = result_dict
        self.value = result_dict.get('value')
        self.method = result_dict.get('method')
        self.timestamp = result_dict.get('timestamp')
        self.calculator = result_dict.get('calculator')

    def __repr__(self) -> str:
        return f"CalculationResult(value={self.value}, method='{self.method}')"

    def __float__(self) -> float:
        """Allow conversion to float."""
        if isinstance(self.value, (int, float)):
            return float(self.value)
        raise TypeError('Cannot convert array result to float')

    def to_dict(self) -> Dict[str, Any]:
        """Return result as dictionary."""
        return self._data.copy()

    def to_dataframe(self) -> pd.DataFrame:
        """Convert result to DataFrame if applicable."""
        if isinstance(self.value, np.ndarray):
            return pd.DataFrame({'value': self.value})
        else:
            return pd.DataFrame([self._data])

    def export_json(self, filepath: str) -> None:
        """Export result to JSON file."""
        import json
        with open(filepath, 'w') as f:

            def convert_numpy(obj):
                if isinstance(obj, np.ndarray):
                    return obj.tolist()
                elif isinstance(obj, np.integer):
                    return int(obj)
                elif isinstance(obj, np.floating):
                    return float(obj)
                raise TypeError(f'Object of type {type(obj)} is not JSON serializable')
            json.dump(self._data, f, default=convert_numpy, indent=2)

def __float__(self) -> float:
    """Allow conversion to float."""
    if isinstance(self.value, (int, float)):
        return float(self.value)
    raise TypeError('Cannot convert array result to float')

def to_dict(self) -> Dict[str, Any]:
    """Return result as dictionary."""
    return self._data.copy()

def to_dataframe(self) -> pd.DataFrame:
    """Convert result to DataFrame if applicable."""
    if isinstance(self.value, np.ndarray):
        return pd.DataFrame({'value': self.value})
    else:
        return pd.DataFrame([self._data])

def convert_numpy(obj):
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    elif isinstance(obj, np.integer):
        return int(obj)
    elif isinstance(obj, np.floating):
        return float(obj)
    raise TypeError(f'Object of type {type(obj)} is not JSON serializable')

class AdvancedQuantAnalyzer(BaseCalculator):
    """Comprehensive analyzer for advanced quantitative methods."""

    def __init__(self, precision: int=6, random_seed: Optional[int]=42):
        super().__init__(precision)
        self.random_seed = random_seed
        if random_seed is not None:
            np.random.seed(random_seed)

    def get_supported_methods(self) -> List[str]:
        return ['trend_analysis', 'stationarity_test', 'arima_model', 'forecasting', 'supervised_learning', 'unsupervised_learning', 'model_evaluation', 'feature_engineering', 'sampling_techniques', 'central_limit_theorem', 'resampling_methods', 'sampling_error_analysis']

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def analyze_trend(self, data: Union[List, np.ndarray, pd.Series], trend_type: str='linear', dates: Optional[pd.DatetimeIndex]=None) -> Dict[str, Any]:
        """Analyze linear and log-linear trends in time series data."""
        data = self._validate_returns(data, 'data')
        self._check_data_length(data, min_length=10)
        if trend_type not in ['linear', 'log_linear']:
            raise DataValidationError(f'Invalid trend_type: {trend_type}', 'trend_type')
        if dates is not None:
            time_index = np.arange(len(dates))
        else:
            time_index = np.arange(len(data))
        if trend_type == 'log_linear':
            if np.any(data <= 0):
                raise DataValidationError('Log-linear trend requires positive data', 'data')
            y_data = np.log(data)
        else:
            y_data = data
        X = np.column_stack([np.ones(len(time_index)), time_index])
        coefficients = np.linalg.lstsq(X, y_data, rcond=None)[0]
        intercept, slope = coefficients
        fitted_values = intercept + slope * time_index
        residuals = y_data - fitted_values
        if trend_type == 'log_linear':
            fitted_values_original = np.exp(fitted_values)
            residuals_original = data - fitted_values_original
        else:
            fitted_values_original = fitted_values
            residuals_original = residuals
        ss_res = np.sum(residuals ** 2)
        ss_tot = np.sum((y_data - np.mean(y_data)) ** 2)
        r_squared = 1 - ss_res / ss_tot if ss_tot != 0 else 0
        n = len(data)
        mse = ss_res / (n - 2)
        var_slope = mse / np.sum((time_index - np.mean(time_index)) ** 2)
        t_stat = slope / np.sqrt(var_slope) if var_slope > 0 else np.inf
        p_value = 2 * (1 - stats.t.cdf(abs(t_stat), n - 2))
        return self._create_result_dict(value={'slope': slope, 'intercept': intercept}, method=f'{trend_type}_trend', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'trend_type': trend_type}, metadata={'fitted_values': fitted_values_original.tolist(), 'residuals': residuals_original.tolist(), 'r_squared': r_squared, 'slope_t_statistic': t_stat, 'slope_p_value': p_value, 'trend_significant': p_value < 0.05, 'trend_direction': 'upward' if slope > 0 else 'downward' if slope < 0 else 'flat'})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def test_stationarity(self, data: Union[List, np.ndarray, pd.Series], test_type: str='adf') -> Dict[str, Any]:
        """Test for stationarity using various unit root tests."""
        data = self._validate_returns(data, 'data')
        self._check_data_length(data, min_length=20)
        if test_type not in ['adf', 'kpss', 'pp']:
            raise DataValidationError(f'Invalid test_type: {test_type}', 'test_type')
        results = {}
        if test_type == 'adf':
            from statsmodels.tsa.stattools import adfuller
            adf_result = adfuller(data, autolag='AIC')
            results = {'test_statistic': adf_result[0], 'p_value': adf_result[1], 'critical_values': adf_result[4], 'is_stationary': adf_result[1] < 0.05, 'null_hypothesis': 'Unit root (non-stationary)'}
        elif test_type == 'kpss':
            from statsmodels.tsa.stattools import kpss
            kpss_result = kpss(data, regression='c')
            results = {'test_statistic': kpss_result[0], 'p_value': kpss_result[1], 'critical_values': kpss_result[3], 'is_stationary': kpss_result[1] > 0.05, 'null_hypothesis': 'Stationary'}
        rolling_mean = pd.Series(data).rolling(window=min(20, len(data) // 4)).mean()
        rolling_std = pd.Series(data).rolling(window=min(20, len(data) // 4)).std()
        return self._create_result_dict(value=results, method=f'{test_type}_stationarity_test', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'test_type': test_type}, metadata={'rolling_mean_stability': np.std(rolling_mean.dropna()), 'rolling_std_stability': np.std(rolling_std.dropna()), 'mean_reversion_strength': abs(np.corrcoef(data[:-1], np.diff(data))[0, 1]) if len(data) > 1 else 0})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def fit_arima_model(self, data: Union[List, np.ndarray, pd.Series], order: Tuple[int, int, int]=(1, 0, 1), seasonal_order: Optional[Tuple[int, int, int, int]]=None) -> Dict[str, Any]:
        """Fit ARIMA model to time series data."""
        data = self._validate_returns(data, 'data')
        self._check_data_length(data, min_length=max(20, sum(order) * 3))
        try:
            from statsmodels.tsa.arima.model import ARIMA
            model = ARIMA(data, order=order, seasonal_order=seasonal_order)
            fitted_model = model.fit()
            residuals = fitted_model.resid
            fitted_values = fitted_model.fittedvalues
            aic = fitted_model.aic
            bic = fitted_model.bic
            from statsmodels.stats.diagnostic import acorr_ljungbox
            ljung_box = acorr_ljungbox(residuals, lags=min(10, len(residuals) // 4), return_df=True)
            return self._create_result_dict(value={'parameters': fitted_model.params.to_dict(), 'fitted_values': fitted_values.tolist(), 'residuals': residuals.tolist()}, method='arima_model', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'order': order, 'seasonal_order': seasonal_order}, metadata={'aic': aic, 'bic': bic, 'log_likelihood': fitted_model.llf, 'ljung_box_p_value': ljung_box['lb_pvalue'].iloc[-1], 'residuals_autocorrelated': ljung_box['lb_pvalue'].iloc[-1] < 0.05, 'model_summary': str(fitted_model.summary())})
        except ImportError:
            if order[0] == 1 and order[1] == 0 and (order[2] == 0):
                return self._fit_simple_ar1(data)
            else:
                raise DataValidationError('statsmodels required for ARIMA modeling', 'dependencies')

    def _fit_simple_ar1(self, data: np.ndarray) -> Dict[str, Any]:
        """Fallback AR(1) implementation."""
        y = data[1:]
        x = data[:-1]
        X = np.column_stack([np.ones(len(x)), x])
        coefficients = np.linalg.lstsq(X, y, rcond=None)[0]
        intercept, phi = coefficients
        fitted_values = intercept + phi * data[:-1]
        residuals = y - fitted_values
        return self._create_result_dict(value={'parameters': {'const': intercept, 'ar.L1': phi}, 'fitted_values': np.concatenate([[data[0]], fitted_values]).tolist(), 'residuals': np.concatenate([[0], residuals]).tolist()}, method='ar1_model', parameters={'data': data.tolist()}, metadata={'r_squared': 1 - np.var(residuals) / np.var(y), 'is_stationary': abs(phi) < 1})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def generate_forecasts(self, data: Union[List, np.ndarray, pd.Series], horizon: int=5, method: str='simple_exponential', train_size: float=0.8) -> Dict[str, Any]:
        """Generate forecasts using various methods."""
        data = self._validate_returns(data, 'data')
        self._check_data_length(data, min_length=20)
        horizon = int(self._validate_positive(horizon, 'horizon'))
        train_size = self._validate_probability(train_size, 'train_size')
        split_point = int(len(data) * train_size)
        train_data = data[:split_point]
        test_data = data[split_point:]
        forecasts = {}
        if method == 'simple_exponential':
            alpha = 0.3
            smoothed = [train_data[0]]
            for i in range(1, len(train_data)):
                smoothed.append(alpha * train_data[i] + (1 - alpha) * smoothed[-1])
            forecast_values = [smoothed[-1]] * horizon
        elif method == 'linear_trend':
            time_index = np.arange(len(train_data))
            X = np.column_stack([np.ones(len(time_index)), time_index])
            coefficients = np.linalg.lstsq(X, train_data, rcond=None)[0]
            intercept, slope = coefficients
            future_time = np.arange(len(train_data), len(train_data) + horizon)
            forecast_values = intercept + slope * future_time
        elif method == 'moving_average':
            window = min(5, len(train_data) // 4)
            last_values = train_data[-window:]
            forecast_values = [np.mean(last_values)] * horizon
        else:
            raise DataValidationError(f'Unknown forecasting method: {method}', 'method')
        if len(test_data) > 0:
            n_compare = min(len(test_data), horizon)
            mae = np.mean(np.abs(test_data[:n_compare] - forecast_values[:n_compare]))
            rmse = np.sqrt(np.mean((test_data[:n_compare] - forecast_values[:n_compare]) ** 2))
            mape = np.mean(np.abs((test_data[:n_compare] - forecast_values[:n_compare]) / test_data[:n_compare])) * 100
        else:
            mae = rmse = mape = None
        return self._create_result_dict(value=forecast_values, method=f'forecast_{method}', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'horizon': horizon, 'method': method, 'train_size': train_size}, metadata={'train_data_size': len(train_data), 'test_data_size': len(test_data), 'mae': mae, 'rmse': rmse, 'mape': mape, 'forecast_horizon': horizon})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def supervised_learning_analysis(self, X: Union[np.ndarray, pd.DataFrame], y: Union[np.ndarray, pd.Series], problem_type: str='regression', algorithms: List[str]=['ridge', 'random_forest']) -> Dict[str, Any]:
        """Comprehensive supervised learning analysis."""
        if isinstance(X, pd.DataFrame):
            X = X.values
        if isinstance(y, pd.Series):
            y = y.values
        X = self._validate_numeric_input(X, 'X')
        y = self._validate_numeric_input(y, 'y')
        if len(X) != len(y):
            raise DataValidationError(f'Length mismatch: X({len(X)}) vs y({len(y)})', 'data')
        if problem_type not in ['regression', 'classification']:
            raise DataValidationError(f'Invalid problem_type: {problem_type}', 'problem_type')
        X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2, random_state=self.random_seed)
        scaler = StandardScaler()
        X_train_scaled = scaler.fit_transform(X_train)
        X_test_scaled = scaler.transform(X_test)
        results = {}
        for algorithm in algorithms:
            try:
                if problem_type == 'regression':
                    model = self._get_regression_model(algorithm)
                else:
                    model = self._get_classification_model(algorithm)
                if algorithm in ['svm', 'knn']:
                    model.fit(X_train_scaled, y_train)
                    y_pred = model.predict(X_test_scaled)
                else:
                    model.fit(X_train, y_train)
                    y_pred = model.predict(X_test)
                if problem_type == 'regression':
                    mse = mean_squared_error(y_test, y_pred)
                    r2 = r2_score(y_test, y_pred)
                    results[algorithm] = {'mse': mse, 'rmse': np.sqrt(mse), 'r2_score': r2, 'predictions': y_pred.tolist()}
                else:
                    from sklearn.metrics import accuracy_score, precision_score, recall_score
                    accuracy = accuracy_score(y_test, y_pred)
                    precision = precision_score(y_test, y_pred, average='weighted')
                    recall = recall_score(y_test, y_pred, average='weighted')
                    results[algorithm] = {'accuracy': accuracy, 'precision': precision, 'recall': recall, 'predictions': y_pred.tolist()}
            except Exception as e:
                results[algorithm] = {'error': str(e)}
        return self._create_result_dict(value=results, method=f'supervised_learning_{problem_type}', parameters={'X_shape': X.shape, 'y_shape': y.shape, 'problem_type': problem_type, 'algorithms': algorithms}, metadata={'train_size': len(X_train), 'test_size': len(X_test), 'n_features': X.shape[1], 'best_algorithm': max(results.keys(), key=lambda k: results[k].get('r2_score' if problem_type == 'regression' else 'accuracy', -np.inf)) if results else None})

    def _get_regression_model(self, algorithm: str):
        """Get regression model by algorithm name."""
        models = {'ridge': Ridge(alpha=1.0, random_state=self.random_seed), 'lasso': Lasso(alpha=1.0, random_state=self.random_seed), 'elastic_net': ElasticNet(alpha=1.0, random_state=self.random_seed), 'svm': SVR(kernel='rbf'), 'knn': KNeighborsRegressor(n_neighbors=5), 'decision_tree': DecisionTreeRegressor(random_state=self.random_seed), 'random_forest': RandomForestRegressor(n_estimators=100, random_state=self.random_seed)}
        return models.get(algorithm, Ridge(random_state=self.random_seed))

    def _get_classification_model(self, algorithm: str):
        """Get classification model by algorithm name."""
        models = {'svm': SVC(kernel='rbf', random_state=self.random_seed), 'knn': KNeighborsClassifier(n_neighbors=5), 'decision_tree': DecisionTreeClassifier(random_state=self.random_seed), 'random_forest': RandomForestClassifier(n_estimators=100, random_state=self.random_seed)}
        return models.get(algorithm, RandomForestClassifier(random_state=self.random_seed))

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def unsupervised_learning_analysis(self, X: Union[np.ndarray, pd.DataFrame], methods: List[str]=['pca', 'kmeans']) -> Dict[str, Any]:
        """Unsupervised learning analysis including PCA and clustering."""
        if isinstance(X, pd.DataFrame):
            X = X.values
        X = self._validate_numeric_input(X, 'X')
        scaler = StandardScaler()
        X_scaled = scaler.fit_transform(X)
        results = {}
        for method in methods:
            try:
                if method == 'pca':
                    pca = PCA()
                    X_pca = pca.fit_transform(X_scaled)
                    cumvar = np.cumsum(pca.explained_variance_ratio_)
                    n_components_95 = np.argmax(cumvar >= 0.95) + 1
                    results['pca'] = {'explained_variance_ratio': pca.explained_variance_ratio_.tolist(), 'cumulative_variance': cumvar.tolist(), 'components_for_95_variance': n_components_95, 'principal_components': X_pca.tolist()}
                elif method == 'kmeans':
                    inertias = []
                    silhouette_scores = []
                    k_range = range(2, min(11, len(X) // 2))
                    for k in k_range:
                        kmeans = KMeans(n_clusters=k, random_state=self.random_seed)
                        cluster_labels = kmeans.fit_predict(X_scaled)
                        inertias.append(kmeans.inertia_)
                        from sklearn.metrics import silhouette_score
                        sil_score = silhouette_score(X_scaled, cluster_labels)
                        silhouette_scores.append(sil_score)
                    optimal_k = k_range[np.argmax(silhouette_scores)]
                    final_kmeans = KMeans(n_clusters=optimal_k, random_state=self.random_seed)
                    final_labels = final_kmeans.fit_predict(X_scaled)
                    results['kmeans'] = {'optimal_k': optimal_k, 'cluster_labels': final_labels.tolist(), 'cluster_centers': final_kmeans.cluster_centers_.tolist(), 'inertia_by_k': list(zip(k_range, inertias)), 'silhouette_by_k': list(zip(k_range, silhouette_scores))}
                elif method == 'hierarchical':
                    hierarchical = AgglomerativeClustering(n_clusters=3)
                    cluster_labels = hierarchical.fit_predict(X_scaled)
                    results['hierarchical'] = {'cluster_labels': cluster_labels.tolist(), 'n_clusters': 3}
            except Exception as e:
                results[method] = {'error': str(e)}
        return self._create_result_dict(value=results, method='unsupervised_learning', parameters={'X_shape': X.shape, 'methods': methods}, metadata={'n_samples': X.shape[0], 'n_features': X.shape[1], 'data_scaled': True})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def evaluate_model_performance(self, X: Union[np.ndarray, pd.DataFrame], y: Union[np.ndarray, pd.Series], model_type: str='random_forest', cv_folds: int=5) -> Dict[str, Any]:
        """Comprehensive model evaluation with cross-validation."""
        if isinstance(X, pd.DataFrame):
            X = X.values
        if isinstance(y, pd.Series):
            y = y.values
        problem_type = 'classification' if len(np.unique(y)) < 10 else 'regression'
        if problem_type == 'regression':
            model = self._get_regression_model(model_type)
            scoring = 'r2'
        else:
            model = self._get_classification_model(model_type)
            scoring = 'accuracy'
        cv_scores = cross_val_score(model, X, y, cv=cv_folds, scoring=scoring)
        train_sizes = np.linspace(0.1, 1.0, 5)
        train_scores = []
        val_scores = []
        for train_size in train_sizes:
            n_samples = int(len(X) * train_size)
            X_subset = X[:n_samples]
            y_subset = y[:n_samples]
            model.fit(X_subset, y_subset)
            train_pred = model.predict(X_subset)
            if problem_type == 'regression':
                train_score = r2_score(y_subset, train_pred)
            else:
                from sklearn.metrics import accuracy_score
                train_score = accuracy_score(y_subset, train_pred)
            train_scores.append(train_score)
            if n_samples < len(X):
                X_val = X[n_samples:]
                y_val = y[n_samples:]
                val_pred = model.predict(X_val)
                if problem_type == 'regression':
                    val_score = r2_score(y_val, val_pred)
                else:
                    val_score = accuracy_score(y_val, val_pred)
            else:
                val_score = train_score
            val_scores.append(val_score)
        final_train_score = train_scores[-1]
        final_val_score = val_scores[-1]
        overfitting_score = final_train_score - final_val_score
        is_overfitting = overfitting_score > 0.1
        return self._create_result_dict(value={'cv_scores': cv_scores.tolist(), 'train_scores': train_scores, 'val_scores': val_scores}, method='model_evaluation', parameters={'model_type': model_type, 'cv_folds': cv_folds, 'problem_type': problem_type}, metadata={'mean_cv_score': np.mean(cv_scores), 'std_cv_score': np.std(cv_scores), 'overfitting_score': overfitting_score, 'is_overfitting': is_overfitting, 'final_train_score': final_train_score, 'final_val_score': final_val_score})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def feature_engineering_analysis(self, data: Union[pd.DataFrame, np.ndarray], target_column: Optional[str]=None, text_columns: Optional[List[str]]=None) -> Dict[str, Any]:
        """Feature engineering including selection and text processing."""
        if isinstance(data, np.ndarray):
            data = pd.DataFrame(data)
        results = {}
        if target_column and target_column in data.columns:
            from sklearn.feature_selection import SelectKBest, f_regression, mutual_info_regression
            X = data.drop(columns=[target_column]).select_dtypes(include=[np.number])
            y = data[target_column]
            selector = SelectKBest(score_func=f_regression, k=min(10, X.shape[1]))
            X_selected = selector.fit_transform(X, y)
            selected_features = X.columns[selector.get_support()].tolist()
            feature_scores = selector.scores_.tolist()
            results['feature_selection'] = {'selected_features': selected_features, 'feature_scores': feature_scores, 'n_features_selected': len(selected_features)}
        if text_columns:
            text_stats = {}
            for col in text_columns:
                if col in data.columns:
                    text_data = data[col].astype(str)
                    text_stats[col] = {'avg_length': text_data.str.len().mean(), 'total_unique': text_data.nunique(), 'most_common': text_data.value_counts().head().to_dict()}
            results['text_analysis'] = text_stats
        missing_stats = {'missing_by_column': data.isnull().sum().to_dict(), 'total_missing': data.isnull().sum().sum(), 'missing_percentage': (data.isnull().sum() / len(data) * 100).to_dict()}
        results['missing_value_analysis'] = missing_stats
        numeric_data = data.select_dtypes(include=[np.number])
        if not numeric_data.empty:
            correlation_matrix = numeric_data.corr()
            high_corr_pairs = []
            for i in range(len(correlation_matrix.columns)):
                for j in range(i + 1, len(correlation_matrix.columns)):
                    corr_val = correlation_matrix.iloc[i, j]
                    if abs(corr_val) > 0.8:
                        high_corr_pairs.append({'feature1': correlation_matrix.columns[i], 'feature2': correlation_matrix.columns[j], 'correlation': corr_val})
            results['correlation_analysis'] = {'correlation_matrix': correlation_matrix.to_dict(), 'high_correlation_pairs': high_corr_pairs}
        return self._create_result_dict(value=results, method='feature_engineering', parameters={'data_shape': data.shape, 'target_column': target_column, 'text_columns': text_columns}, metadata={'n_numeric_features': len(data.select_dtypes(include=[np.number]).columns), 'n_categorical_features': len(data.select_dtypes(include=['object']).columns), 'data_quality_score': max(0, 100 - missing_stats['total_missing'] / data.size * 100)})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def analyze_sampling_techniques(self, population: Union[List, np.ndarray, pd.DataFrame], sample_size: int, sampling_methods: List[str]=['simple', 'stratified', 'systematic']) -> Dict[str, Any]:
        """Demonstrate various sampling techniques."""
        if isinstance(population, pd.DataFrame):
            population_data = population
        else:
            population = self._validate_numeric_input(population, 'population')
            population_data = pd.DataFrame({'value': population})
        sample_size = int(self._validate_positive(sample_size, 'sample_size'))
        if sample_size >= len(population_data):
            raise DataValidationError('Sample size must be less than population size', 'sample_size')
        results = {}
        for method in sampling_methods:
            try:
                if method == 'simple':
                    sample_indices = np.random.choice(len(population_data), size=sample_size, replace=False)
                    sample = population_data.iloc[sample_indices]
                elif method == 'stratified':
                    if len(population_data.columns) > 1:
                        strata_col = population_data.columns[1]
                    else:
                        strata_col = 'artificial_strata'
                        population_data[strata_col] = pd.qcut(population_data.iloc[:, 0], q=3, labels=['low', 'medium', 'high'])
                    sample_list = []
                    strata_counts = population_data[strata_col].value_counts()
                    for stratum in strata_counts.index:
                        stratum_size = len(population_data[population_data[strata_col] == stratum])
                        stratum_sample_size = max(1, int(sample_size * stratum_size / len(population_data)))
                        stratum_data = population_data[population_data[strata_col] == stratum]
                        if len(stratum_data) >= stratum_sample_size:
                            stratum_sample = stratum_data.sample(n=stratum_sample_size, random_state=self.random_seed)
                            sample_list.append(stratum_sample)
                    sample = pd.concat(sample_list) if sample_list else population_data.sample(n=sample_size, random_state=self.random_seed)
                elif method == 'systematic':
                    k = len(population_data) // sample_size
                    start = np.random.randint(0, k)
                    indices = [start + i * k for i in range(sample_size) if start + i * k < len(population_data)]
                    sample = population_data.iloc[indices]
                elif method == 'cluster':
                    n_clusters = max(2, sample_size // 5)
                    cluster_size = len(population_data) // n_clusters
                    clusters = [population_data.iloc[i:i + cluster_size] for i in range(0, len(population_data), cluster_size)]
                    n_select_clusters = max(1, sample_size // cluster_size)
                    selected_clusters = np.random.choice(len(clusters), size=min(n_select_clusters, len(clusters)), replace=False)
                    sample_list = [clusters[i] for i in selected_clusters]
                    sample = pd.concat(sample_list)[:sample_size]
                else:
                    continue
                if len(sample) > 0:
                    numeric_cols = sample.select_dtypes(include=[np.number]).columns
                    if len(numeric_cols) > 0:
                        sample_mean = sample[numeric_cols].mean().to_dict()
                        sample_std = sample[numeric_cols].std().to_dict()
                        pop_mean = population_data[numeric_cols].mean().to_dict()
                        pop_std = population_data[numeric_cols].std().to_dict()
                        results[method] = {'sample_size': len(sample), 'sample_mean': sample_mean, 'sample_std': sample_std, 'population_mean': pop_mean, 'population_std': pop_std, 'bias': {col: sample_mean[col] - pop_mean[col] for col in sample_mean.keys()}}
                    else:
                        results[method] = {'sample_size': len(sample), 'note': 'No numeric columns for statistics'}
            except Exception as e:
                results[method] = {'error': str(e)}
        return self._create_result_dict(value=results, method='sampling_techniques', parameters={'population_size': len(population_data), 'sample_size': sample_size, 'sampling_methods': sampling_methods}, metadata={'population_shape': population_data.shape, 'sampling_fraction': sample_size / len(population_data)})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def demonstrate_central_limit_theorem(self, population_dist: str='exponential', population_params: Dict[str, float]=None, sample_sizes: List[int]=[5, 10, 30, 100], n_samples: int=1000) -> Dict[str, Any]:
        """Demonstrate Central Limit Theorem with various distributions."""
        if population_params is None:
            population_params = {'scale': 1.0}
        n_samples = int(self._validate_positive(n_samples, 'n_samples'))
        if population_dist == 'exponential':
            population = np.random.exponential(scale=population_params.get('scale', 1.0), size=10000)
        elif population_dist == 'uniform':
            low = population_params.get('low', 0)
            high = population_params.get('high', 1)
            population = np.random.uniform(low=low, high=high, size=10000)
        elif population_dist == 'binomial':
            n = population_params.get('n', 10)
            p = population_params.get('p', 0.5)
            population = np.random.binomial(n=n, p=p, size=10000)
        else:
            population = np.random.normal(loc=population_params.get('loc', 0), scale=population_params.get('scale', 1), size=10000)
        population_mean = np.mean(population)
        population_std = np.std(population)
        results = {}
        for sample_size in sample_sizes:
            sample_means = []
            for _ in range(n_samples):
                sample = np.random.choice(population, size=sample_size, replace=True)
                sample_means.append(np.mean(sample))
            sample_means = np.array(sample_means)
            _, shapiro_p = stats.shapiro(sample_means) if len(sample_means) <= 5000 else (None, None)
            theoretical_mean = population_mean
            theoretical_std = population_std / np.sqrt(sample_size)
            empirical_mean = np.mean(sample_means)
            empirical_std = np.std(sample_means)
            results[f'n_{sample_size}'] = {'sample_means': sample_means.tolist(), 'empirical_mean': empirical_mean, 'empirical_std': empirical_std, 'theoretical_mean': theoretical_mean, 'theoretical_std': theoretical_std, 'mean_bias': empirical_mean - theoretical_mean, 'std_bias': empirical_std - theoretical_std, 'shapiro_p_value': shapiro_p, 'appears_normal': shapiro_p > 0.05 if shapiro_p is not None else None}
        return self._create_result_dict(value=results, method='central_limit_theorem', parameters={'population_dist': population_dist, 'population_params': population_params, 'sample_sizes': sample_sizes, 'n_samples': n_samples}, metadata={'population_mean': population_mean, 'population_std': population_std, 'population_size': len(population), 'clt_convergence': {str(n): results[f'n_{n}']['appears_normal'] for n in sample_sizes if f'n_{n}' in results}})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def advanced_resampling_analysis(self, data: Union[List, np.ndarray, pd.Series], statistic_func: Callable=np.mean, methods: List[str]=['bootstrap', 'jackknife', 'permutation'], n_resamples: int=1000) -> Dict[str, Any]:
        """Advanced resampling methods for statistical inference."""
        data = self._validate_returns(data, 'data')
        self._check_data_length(data, min_length=5)
        n_resamples = int(self._validate_positive(n_resamples, 'n_resamples'))
        if not callable(statistic_func):
            raise DataValidationError('statistic_func must be callable', 'statistic_func')
        original_stat = statistic_func(data)
        results = {}
        for method in methods:
            try:
                if method == 'bootstrap':
                    bootstrap_stats = []
                    for _ in range(n_resamples):
                        bootstrap_sample = np.random.choice(data, size=len(data), replace=True)
                        bootstrap_stats.append(statistic_func(bootstrap_sample))
                    bootstrap_stats = np.array(bootstrap_stats)
                    ci_lower = np.percentile(bootstrap_stats, 2.5)
                    ci_upper = np.percentile(bootstrap_stats, 97.5)
                    results['bootstrap'] = {'resampled_statistics': bootstrap_stats.tolist(), 'mean': np.mean(bootstrap_stats), 'std': np.std(bootstrap_stats), 'bias': np.mean(bootstrap_stats) - original_stat, 'confidence_interval': [ci_lower, ci_upper]}
                elif method == 'jackknife':
                    n = len(data)
                    jackknife_stats = []
                    for i in range(n):
                        jackknife_sample = np.concatenate([data[:i], data[i + 1:]])
                        jackknife_stats.append(statistic_func(jackknife_sample))
                    jackknife_stats = np.array(jackknife_stats)
                    jackknife_mean = np.mean(jackknife_stats)
                    bias = (n - 1) * (jackknife_mean - original_stat)
                    bias_corrected = original_stat - bias
                    jackknife_var = (n - 1) / n * np.sum((jackknife_stats - jackknife_mean) ** 2)
                    results['jackknife'] = {'resampled_statistics': jackknife_stats.tolist(), 'bias': bias, 'bias_corrected_estimate': bias_corrected, 'variance_estimate': jackknife_var, 'std_error': np.sqrt(jackknife_var)}
                elif method == 'permutation':
                    permutation_stats = []
                    for _ in range(n_resamples):
                        signs = np.random.choice([-1, 1], size=len(data))
                        permuted_data = data * signs
                        permutation_stats.append(statistic_func(permuted_data))
                    permutation_stats = np.array(permutation_stats)
                    p_value = np.mean(np.abs(permutation_stats) >= np.abs(original_stat))
                    results['permutation'] = {'resampled_statistics': permutation_stats.tolist(), 'p_value': p_value, 'significant': p_value < 0.05}
            except Exception as e:
                results[method] = {'error': str(e)}
        return self._create_result_dict(value=results, method='advanced_resampling', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'methods': methods, 'n_resamples': n_resamples}, metadata={'original_statistic': original_stat, 'data_size': len(data), 'statistic_name': getattr(statistic_func, '__name__', 'custom_function')})

    @validate_inputs
    @timing_decorator
    @handle_calculation_error
    def calculate_sampling_error_analysis(self, population_mean: float, population_std: float, sample_sizes: List[int]=[10, 30, 50, 100, 500], confidence_level: float=0.95, n_simulations: int=1000) -> Dict[str, Any]:
        """Analyze sampling error and determine optimal sample sizes."""
        population_mean = self._validate_numeric_input(population_mean, 'population_mean')
        population_std = self._validate_positive(population_std, 'population_std')
        confidence_level = self._validate_probability(confidence_level, 'confidence_level')
        n_simulations = int(self._validate_positive(n_simulations, 'n_simulations'))
        alpha = 1 - confidence_level
        z_critical = stats.norm.ppf(1 - alpha / 2)
        results = {}
        for sample_size in sample_sizes:
            standard_error = population_std / np.sqrt(sample_size)
            margin_of_error = z_critical * standard_error
            sample_means = []
            for _ in range(n_simulations):
                sample = np.random.normal(population_mean, population_std, size=sample_size)
                sample_means.append(np.mean(sample))
            sample_means = np.array(sample_means)
            ci_lower = sample_means - margin_of_error
            ci_upper = sample_means + margin_of_error
            coverage = np.mean((ci_lower <= population_mean) & (population_mean <= ci_upper))
            mse = np.mean((sample_means - population_mean) ** 2)
            results[f'n_{sample_size}'] = {'sample_size': sample_size, 'theoretical_se': standard_error, 'empirical_se': np.std(sample_means), 'theoretical_moe': margin_of_error, 'empirical_moe': z_critical * np.std(sample_means), 'coverage_probability': coverage, 'mean_squared_error': mse, 'relative_error': standard_error / population_mean if population_mean != 0 else np.inf}
        target_moe = 0.1 * population_std
        recommended_n = int(np.ceil((z_critical * population_std / target_moe) ** 2))
        return self._create_result_dict(value=results, method='sampling_error_analysis', parameters={'population_mean': population_mean, 'population_std': population_std, 'sample_sizes': sample_sizes, 'confidence_level': confidence_level, 'n_simulations': n_simulations}, metadata={'recommended_sample_size': recommended_n, 'target_margin_of_error': target_moe, 'z_critical': z_critical, 'coverage_target': confidence_level})

    def calculate(self, calculation_type: str, **kwargs) -> Dict[str, Any]:
        """Main calculation dispatcher for all advanced methods."""
        methods = {'trend_analysis': self.analyze_trend, 'stationarity_test': self.test_stationarity, 'arima_model': self.fit_arima_model, 'forecasting': self.generate_forecasts, 'supervised_learning': self.supervised_learning_analysis, 'unsupervised_learning': self.unsupervised_learning_analysis, 'model_evaluation': self.evaluate_model_performance, 'feature_engineering': self.feature_engineering_analysis, 'sampling_techniques': self.analyze_sampling_techniques, 'central_limit_theorem': self.demonstrate_central_limit_theorem, 'resampling_methods': self.advanced_resampling_analysis, 'sampling_error_analysis': self.calculate_sampling_error_analysis}
        if calculation_type not in methods:
            raise DataValidationError(f'Unknown calculation type: {calculation_type}', 'calculation_type')
        return methods[calculation_type](**kwargs)

@validate_inputs
@timing_decorator
@handle_calculation_error
def analyze_trend(self, data: Union[List, np.ndarray, pd.Series], trend_type: str='linear', dates: Optional[pd.DatetimeIndex]=None) -> Dict[str, Any]:
    """Analyze linear and log-linear trends in time series data."""
    data = self._validate_returns(data, 'data')
    self._check_data_length(data, min_length=10)
    if trend_type not in ['linear', 'log_linear']:
        raise DataValidationError(f'Invalid trend_type: {trend_type}', 'trend_type')
    if dates is not None:
        time_index = np.arange(len(dates))
    else:
        time_index = np.arange(len(data))
    if trend_type == 'log_linear':
        if np.any(data <= 0):
            raise DataValidationError('Log-linear trend requires positive data', 'data')
        y_data = np.log(data)
    else:
        y_data = data
    X = np.column_stack([np.ones(len(time_index)), time_index])
    coefficients = np.linalg.lstsq(X, y_data, rcond=None)[0]
    intercept, slope = coefficients
    fitted_values = intercept + slope * time_index
    residuals = y_data - fitted_values
    if trend_type == 'log_linear':
        fitted_values_original = np.exp(fitted_values)
        residuals_original = data - fitted_values_original
    else:
        fitted_values_original = fitted_values
        residuals_original = residuals
    ss_res = np.sum(residuals ** 2)
    ss_tot = np.sum((y_data - np.mean(y_data)) ** 2)
    r_squared = 1 - ss_res / ss_tot if ss_tot != 0 else 0
    n = len(data)
    mse = ss_res / (n - 2)
    var_slope = mse / np.sum((time_index - np.mean(time_index)) ** 2)
    t_stat = slope / np.sqrt(var_slope) if var_slope > 0 else np.inf
    p_value = 2 * (1 - stats.t.cdf(abs(t_stat), n - 2))
    return self._create_result_dict(value={'slope': slope, 'intercept': intercept}, method=f'{trend_type}_trend', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'trend_type': trend_type}, metadata={'fitted_values': fitted_values_original.tolist(), 'residuals': residuals_original.tolist(), 'r_squared': r_squared, 'slope_t_statistic': t_stat, 'slope_p_value': p_value, 'trend_significant': p_value < 0.05, 'trend_direction': 'upward' if slope > 0 else 'downward' if slope < 0 else 'flat'})

@validate_inputs
@timing_decorator
@handle_calculation_error
def test_stationarity(self, data: Union[List, np.ndarray, pd.Series], test_type: str='adf') -> Dict[str, Any]:
    """Test for stationarity using various unit root tests."""
    data = self._validate_returns(data, 'data')
    self._check_data_length(data, min_length=20)
    if test_type not in ['adf', 'kpss', 'pp']:
        raise DataValidationError(f'Invalid test_type: {test_type}', 'test_type')
    results = {}
    if test_type == 'adf':
        from statsmodels.tsa.stattools import adfuller
        adf_result = adfuller(data, autolag='AIC')
        results = {'test_statistic': adf_result[0], 'p_value': adf_result[1], 'critical_values': adf_result[4], 'is_stationary': adf_result[1] < 0.05, 'null_hypothesis': 'Unit root (non-stationary)'}
    elif test_type == 'kpss':
        from statsmodels.tsa.stattools import kpss
        kpss_result = kpss(data, regression='c')
        results = {'test_statistic': kpss_result[0], 'p_value': kpss_result[1], 'critical_values': kpss_result[3], 'is_stationary': kpss_result[1] > 0.05, 'null_hypothesis': 'Stationary'}
    rolling_mean = pd.Series(data).rolling(window=min(20, len(data) // 4)).mean()
    rolling_std = pd.Series(data).rolling(window=min(20, len(data) // 4)).std()
    return self._create_result_dict(value=results, method=f'{test_type}_stationarity_test', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'test_type': test_type}, metadata={'rolling_mean_stability': np.std(rolling_mean.dropna()), 'rolling_std_stability': np.std(rolling_std.dropna()), 'mean_reversion_strength': abs(np.corrcoef(data[:-1], np.diff(data))[0, 1]) if len(data) > 1 else 0})

@validate_inputs
@timing_decorator
@handle_calculation_error
def fit_arima_model(self, data: Union[List, np.ndarray, pd.Series], order: Tuple[int, int, int]=(1, 0, 1), seasonal_order: Optional[Tuple[int, int, int, int]]=None) -> Dict[str, Any]:
    """Fit ARIMA model to time series data."""
    data = self._validate_returns(data, 'data')
    self._check_data_length(data, min_length=max(20, sum(order) * 3))
    try:
        from statsmodels.tsa.arima.model import ARIMA
        model = ARIMA(data, order=order, seasonal_order=seasonal_order)
        fitted_model = model.fit()
        residuals = fitted_model.resid
        fitted_values = fitted_model.fittedvalues
        aic = fitted_model.aic
        bic = fitted_model.bic
        from statsmodels.stats.diagnostic import acorr_ljungbox
        ljung_box = acorr_ljungbox(residuals, lags=min(10, len(residuals) // 4), return_df=True)
        return self._create_result_dict(value={'parameters': fitted_model.params.to_dict(), 'fitted_values': fitted_values.tolist(), 'residuals': residuals.tolist()}, method='arima_model', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'order': order, 'seasonal_order': seasonal_order}, metadata={'aic': aic, 'bic': bic, 'log_likelihood': fitted_model.llf, 'ljung_box_p_value': ljung_box['lb_pvalue'].iloc[-1], 'residuals_autocorrelated': ljung_box['lb_pvalue'].iloc[-1] < 0.05, 'model_summary': str(fitted_model.summary())})
    except ImportError:
        if order[0] == 1 and order[1] == 0 and (order[2] == 0):
            return self._fit_simple_ar1(data)
        else:
            raise DataValidationError('statsmodels required for ARIMA modeling', 'dependencies')

def _fit_simple_ar1(self, data: np.ndarray) -> Dict[str, Any]:
    """Fallback AR(1) implementation."""
    y = data[1:]
    x = data[:-1]
    X = np.column_stack([np.ones(len(x)), x])
    coefficients = np.linalg.lstsq(X, y, rcond=None)[0]
    intercept, phi = coefficients
    fitted_values = intercept + phi * data[:-1]
    residuals = y - fitted_values
    return self._create_result_dict(value={'parameters': {'const': intercept, 'ar.L1': phi}, 'fitted_values': np.concatenate([[data[0]], fitted_values]).tolist(), 'residuals': np.concatenate([[0], residuals]).tolist()}, method='ar1_model', parameters={'data': data.tolist()}, metadata={'r_squared': 1 - np.var(residuals) / np.var(y), 'is_stationary': abs(phi) < 1})

@validate_inputs
@timing_decorator
@handle_calculation_error
def generate_forecasts(self, data: Union[List, np.ndarray, pd.Series], horizon: int=5, method: str='simple_exponential', train_size: float=0.8) -> Dict[str, Any]:
    """Generate forecasts using various methods."""
    data = self._validate_returns(data, 'data')
    self._check_data_length(data, min_length=20)
    horizon = int(self._validate_positive(horizon, 'horizon'))
    train_size = self._validate_probability(train_size, 'train_size')
    split_point = int(len(data) * train_size)
    train_data = data[:split_point]
    test_data = data[split_point:]
    forecasts = {}
    if method == 'simple_exponential':
        alpha = 0.3
        smoothed = [train_data[0]]
        for i in range(1, len(train_data)):
            smoothed.append(alpha * train_data[i] + (1 - alpha) * smoothed[-1])
        forecast_values = [smoothed[-1]] * horizon
    elif method == 'linear_trend':
        time_index = np.arange(len(train_data))
        X = np.column_stack([np.ones(len(time_index)), time_index])
        coefficients = np.linalg.lstsq(X, train_data, rcond=None)[0]
        intercept, slope = coefficients
        future_time = np.arange(len(train_data), len(train_data) + horizon)
        forecast_values = intercept + slope * future_time
    elif method == 'moving_average':
        window = min(5, len(train_data) // 4)
        last_values = train_data[-window:]
        forecast_values = [np.mean(last_values)] * horizon
    else:
        raise DataValidationError(f'Unknown forecasting method: {method}', 'method')
    if len(test_data) > 0:
        n_compare = min(len(test_data), horizon)
        mae = np.mean(np.abs(test_data[:n_compare] - forecast_values[:n_compare]))
        rmse = np.sqrt(np.mean((test_data[:n_compare] - forecast_values[:n_compare]) ** 2))
        mape = np.mean(np.abs((test_data[:n_compare] - forecast_values[:n_compare]) / test_data[:n_compare])) * 100
    else:
        mae = rmse = mape = None
    return self._create_result_dict(value=forecast_values, method=f'forecast_{method}', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'horizon': horizon, 'method': method, 'train_size': train_size}, metadata={'train_data_size': len(train_data), 'test_data_size': len(test_data), 'mae': mae, 'rmse': rmse, 'mape': mape, 'forecast_horizon': horizon})

@validate_inputs
@timing_decorator
@handle_calculation_error
def supervised_learning_analysis(self, X: Union[np.ndarray, pd.DataFrame], y: Union[np.ndarray, pd.Series], problem_type: str='regression', algorithms: List[str]=['ridge', 'random_forest']) -> Dict[str, Any]:
    """Comprehensive supervised learning analysis."""
    if isinstance(X, pd.DataFrame):
        X = X.values
    if isinstance(y, pd.Series):
        y = y.values
    X = self._validate_numeric_input(X, 'X')
    y = self._validate_numeric_input(y, 'y')
    if len(X) != len(y):
        raise DataValidationError(f'Length mismatch: X({len(X)}) vs y({len(y)})', 'data')
    if problem_type not in ['regression', 'classification']:
        raise DataValidationError(f'Invalid problem_type: {problem_type}', 'problem_type')
    X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2, random_state=self.random_seed)
    scaler = StandardScaler()
    X_train_scaled = scaler.fit_transform(X_train)
    X_test_scaled = scaler.transform(X_test)
    results = {}
    for algorithm in algorithms:
        try:
            if problem_type == 'regression':
                model = self._get_regression_model(algorithm)
            else:
                model = self._get_classification_model(algorithm)
            if algorithm in ['svm', 'knn']:
                model.fit(X_train_scaled, y_train)
                y_pred = model.predict(X_test_scaled)
            else:
                model.fit(X_train, y_train)
                y_pred = model.predict(X_test)
            if problem_type == 'regression':
                mse = mean_squared_error(y_test, y_pred)
                r2 = r2_score(y_test, y_pred)
                results[algorithm] = {'mse': mse, 'rmse': np.sqrt(mse), 'r2_score': r2, 'predictions': y_pred.tolist()}
            else:
                from sklearn.metrics import accuracy_score, precision_score, recall_score
                accuracy = accuracy_score(y_test, y_pred)
                precision = precision_score(y_test, y_pred, average='weighted')
                recall = recall_score(y_test, y_pred, average='weighted')
                results[algorithm] = {'accuracy': accuracy, 'precision': precision, 'recall': recall, 'predictions': y_pred.tolist()}
        except Exception as e:
            results[algorithm] = {'error': str(e)}
    return self._create_result_dict(value=results, method=f'supervised_learning_{problem_type}', parameters={'X_shape': X.shape, 'y_shape': y.shape, 'problem_type': problem_type, 'algorithms': algorithms}, metadata={'train_size': len(X_train), 'test_size': len(X_test), 'n_features': X.shape[1], 'best_algorithm': max(results.keys(), key=lambda k: results[k].get('r2_score' if problem_type == 'regression' else 'accuracy', -np.inf)) if results else None})

@validate_inputs
@timing_decorator
@handle_calculation_error
def unsupervised_learning_analysis(self, X: Union[np.ndarray, pd.DataFrame], methods: List[str]=['pca', 'kmeans']) -> Dict[str, Any]:
    """Unsupervised learning analysis including PCA and clustering."""
    if isinstance(X, pd.DataFrame):
        X = X.values
    X = self._validate_numeric_input(X, 'X')
    scaler = StandardScaler()
    X_scaled = scaler.fit_transform(X)
    results = {}
    for method in methods:
        try:
            if method == 'pca':
                pca = PCA()
                X_pca = pca.fit_transform(X_scaled)
                cumvar = np.cumsum(pca.explained_variance_ratio_)
                n_components_95 = np.argmax(cumvar >= 0.95) + 1
                results['pca'] = {'explained_variance_ratio': pca.explained_variance_ratio_.tolist(), 'cumulative_variance': cumvar.tolist(), 'components_for_95_variance': n_components_95, 'principal_components': X_pca.tolist()}
            elif method == 'kmeans':
                inertias = []
                silhouette_scores = []
                k_range = range(2, min(11, len(X) // 2))
                for k in k_range:
                    kmeans = KMeans(n_clusters=k, random_state=self.random_seed)
                    cluster_labels = kmeans.fit_predict(X_scaled)
                    inertias.append(kmeans.inertia_)
                    from sklearn.metrics import silhouette_score
                    sil_score = silhouette_score(X_scaled, cluster_labels)
                    silhouette_scores.append(sil_score)
                optimal_k = k_range[np.argmax(silhouette_scores)]
                final_kmeans = KMeans(n_clusters=optimal_k, random_state=self.random_seed)
                final_labels = final_kmeans.fit_predict(X_scaled)
                results['kmeans'] = {'optimal_k': optimal_k, 'cluster_labels': final_labels.tolist(), 'cluster_centers': final_kmeans.cluster_centers_.tolist(), 'inertia_by_k': list(zip(k_range, inertias)), 'silhouette_by_k': list(zip(k_range, silhouette_scores))}
            elif method == 'hierarchical':
                hierarchical = AgglomerativeClustering(n_clusters=3)
                cluster_labels = hierarchical.fit_predict(X_scaled)
                results['hierarchical'] = {'cluster_labels': cluster_labels.tolist(), 'n_clusters': 3}
        except Exception as e:
            results[method] = {'error': str(e)}
    return self._create_result_dict(value=results, method='unsupervised_learning', parameters={'X_shape': X.shape, 'methods': methods}, metadata={'n_samples': X.shape[0], 'n_features': X.shape[1], 'data_scaled': True})

@validate_inputs
@timing_decorator
@handle_calculation_error
def evaluate_model_performance(self, X: Union[np.ndarray, pd.DataFrame], y: Union[np.ndarray, pd.Series], model_type: str='random_forest', cv_folds: int=5) -> Dict[str, Any]:
    """Comprehensive model evaluation with cross-validation."""
    if isinstance(X, pd.DataFrame):
        X = X.values
    if isinstance(y, pd.Series):
        y = y.values
    problem_type = 'classification' if len(np.unique(y)) < 10 else 'regression'
    if problem_type == 'regression':
        model = self._get_regression_model(model_type)
        scoring = 'r2'
    else:
        model = self._get_classification_model(model_type)
        scoring = 'accuracy'
    cv_scores = cross_val_score(model, X, y, cv=cv_folds, scoring=scoring)
    train_sizes = np.linspace(0.1, 1.0, 5)
    train_scores = []
    val_scores = []
    for train_size in train_sizes:
        n_samples = int(len(X) * train_size)
        X_subset = X[:n_samples]
        y_subset = y[:n_samples]
        model.fit(X_subset, y_subset)
        train_pred = model.predict(X_subset)
        if problem_type == 'regression':
            train_score = r2_score(y_subset, train_pred)
        else:
            from sklearn.metrics import accuracy_score
            train_score = accuracy_score(y_subset, train_pred)
        train_scores.append(train_score)
        if n_samples < len(X):
            X_val = X[n_samples:]
            y_val = y[n_samples:]
            val_pred = model.predict(X_val)
            if problem_type == 'regression':
                val_score = r2_score(y_val, val_pred)
            else:
                val_score = accuracy_score(y_val, val_pred)
        else:
            val_score = train_score
        val_scores.append(val_score)
    final_train_score = train_scores[-1]
    final_val_score = val_scores[-1]
    overfitting_score = final_train_score - final_val_score
    is_overfitting = overfitting_score > 0.1
    return self._create_result_dict(value={'cv_scores': cv_scores.tolist(), 'train_scores': train_scores, 'val_scores': val_scores}, method='model_evaluation', parameters={'model_type': model_type, 'cv_folds': cv_folds, 'problem_type': problem_type}, metadata={'mean_cv_score': np.mean(cv_scores), 'std_cv_score': np.std(cv_scores), 'overfitting_score': overfitting_score, 'is_overfitting': is_overfitting, 'final_train_score': final_train_score, 'final_val_score': final_val_score})

@validate_inputs
@timing_decorator
@handle_calculation_error
def feature_engineering_analysis(self, data: Union[pd.DataFrame, np.ndarray], target_column: Optional[str]=None, text_columns: Optional[List[str]]=None) -> Dict[str, Any]:
    """Feature engineering including selection and text processing."""
    if isinstance(data, np.ndarray):
        data = pd.DataFrame(data)
    results = {}
    if target_column and target_column in data.columns:
        from sklearn.feature_selection import SelectKBest, f_regression, mutual_info_regression
        X = data.drop(columns=[target_column]).select_dtypes(include=[np.number])
        y = data[target_column]
        selector = SelectKBest(score_func=f_regression, k=min(10, X.shape[1]))
        X_selected = selector.fit_transform(X, y)
        selected_features = X.columns[selector.get_support()].tolist()
        feature_scores = selector.scores_.tolist()
        results['feature_selection'] = {'selected_features': selected_features, 'feature_scores': feature_scores, 'n_features_selected': len(selected_features)}
    if text_columns:
        text_stats = {}
        for col in text_columns:
            if col in data.columns:
                text_data = data[col].astype(str)
                text_stats[col] = {'avg_length': text_data.str.len().mean(), 'total_unique': text_data.nunique(), 'most_common': text_data.value_counts().head().to_dict()}
        results['text_analysis'] = text_stats
    missing_stats = {'missing_by_column': data.isnull().sum().to_dict(), 'total_missing': data.isnull().sum().sum(), 'missing_percentage': (data.isnull().sum() / len(data) * 100).to_dict()}
    results['missing_value_analysis'] = missing_stats
    numeric_data = data.select_dtypes(include=[np.number])
    if not numeric_data.empty:
        correlation_matrix = numeric_data.corr()
        high_corr_pairs = []
        for i in range(len(correlation_matrix.columns)):
            for j in range(i + 1, len(correlation_matrix.columns)):
                corr_val = correlation_matrix.iloc[i, j]
                if abs(corr_val) > 0.8:
                    high_corr_pairs.append({'feature1': correlation_matrix.columns[i], 'feature2': correlation_matrix.columns[j], 'correlation': corr_val})
        results['correlation_analysis'] = {'correlation_matrix': correlation_matrix.to_dict(), 'high_correlation_pairs': high_corr_pairs}
    return self._create_result_dict(value=results, method='feature_engineering', parameters={'data_shape': data.shape, 'target_column': target_column, 'text_columns': text_columns}, metadata={'n_numeric_features': len(data.select_dtypes(include=[np.number]).columns), 'n_categorical_features': len(data.select_dtypes(include=['object']).columns), 'data_quality_score': max(0, 100 - missing_stats['total_missing'] / data.size * 100)})

@validate_inputs
@timing_decorator
@handle_calculation_error
def analyze_sampling_techniques(self, population: Union[List, np.ndarray, pd.DataFrame], sample_size: int, sampling_methods: List[str]=['simple', 'stratified', 'systematic']) -> Dict[str, Any]:
    """Demonstrate various sampling techniques."""
    if isinstance(population, pd.DataFrame):
        population_data = population
    else:
        population = self._validate_numeric_input(population, 'population')
        population_data = pd.DataFrame({'value': population})
    sample_size = int(self._validate_positive(sample_size, 'sample_size'))
    if sample_size >= len(population_data):
        raise DataValidationError('Sample size must be less than population size', 'sample_size')
    results = {}
    for method in sampling_methods:
        try:
            if method == 'simple':
                sample_indices = np.random.choice(len(population_data), size=sample_size, replace=False)
                sample = population_data.iloc[sample_indices]
            elif method == 'stratified':
                if len(population_data.columns) > 1:
                    strata_col = population_data.columns[1]
                else:
                    strata_col = 'artificial_strata'
                    population_data[strata_col] = pd.qcut(population_data.iloc[:, 0], q=3, labels=['low', 'medium', 'high'])
                sample_list = []
                strata_counts = population_data[strata_col].value_counts()
                for stratum in strata_counts.index:
                    stratum_size = len(population_data[population_data[strata_col] == stratum])
                    stratum_sample_size = max(1, int(sample_size * stratum_size / len(population_data)))
                    stratum_data = population_data[population_data[strata_col] == stratum]
                    if len(stratum_data) >= stratum_sample_size:
                        stratum_sample = stratum_data.sample(n=stratum_sample_size, random_state=self.random_seed)
                        sample_list.append(stratum_sample)
                sample = pd.concat(sample_list) if sample_list else population_data.sample(n=sample_size, random_state=self.random_seed)
            elif method == 'systematic':
                k = len(population_data) // sample_size
                start = np.random.randint(0, k)
                indices = [start + i * k for i in range(sample_size) if start + i * k < len(population_data)]
                sample = population_data.iloc[indices]
            elif method == 'cluster':
                n_clusters = max(2, sample_size // 5)
                cluster_size = len(population_data) // n_clusters
                clusters = [population_data.iloc[i:i + cluster_size] for i in range(0, len(population_data), cluster_size)]
                n_select_clusters = max(1, sample_size // cluster_size)
                selected_clusters = np.random.choice(len(clusters), size=min(n_select_clusters, len(clusters)), replace=False)
                sample_list = [clusters[i] for i in selected_clusters]
                sample = pd.concat(sample_list)[:sample_size]
            else:
                continue
            if len(sample) > 0:
                numeric_cols = sample.select_dtypes(include=[np.number]).columns
                if len(numeric_cols) > 0:
                    sample_mean = sample[numeric_cols].mean().to_dict()
                    sample_std = sample[numeric_cols].std().to_dict()
                    pop_mean = population_data[numeric_cols].mean().to_dict()
                    pop_std = population_data[numeric_cols].std().to_dict()
                    results[method] = {'sample_size': len(sample), 'sample_mean': sample_mean, 'sample_std': sample_std, 'population_mean': pop_mean, 'population_std': pop_std, 'bias': {col: sample_mean[col] - pop_mean[col] for col in sample_mean.keys()}}
                else:
                    results[method] = {'sample_size': len(sample), 'note': 'No numeric columns for statistics'}
        except Exception as e:
            results[method] = {'error': str(e)}
    return self._create_result_dict(value=results, method='sampling_techniques', parameters={'population_size': len(population_data), 'sample_size': sample_size, 'sampling_methods': sampling_methods}, metadata={'population_shape': population_data.shape, 'sampling_fraction': sample_size / len(population_data)})

@validate_inputs
@timing_decorator
@handle_calculation_error
def demonstrate_central_limit_theorem(self, population_dist: str='exponential', population_params: Dict[str, float]=None, sample_sizes: List[int]=[5, 10, 30, 100], n_samples: int=1000) -> Dict[str, Any]:
    """Demonstrate Central Limit Theorem with various distributions."""
    if population_params is None:
        population_params = {'scale': 1.0}
    n_samples = int(self._validate_positive(n_samples, 'n_samples'))
    if population_dist == 'exponential':
        population = np.random.exponential(scale=population_params.get('scale', 1.0), size=10000)
    elif population_dist == 'uniform':
        low = population_params.get('low', 0)
        high = population_params.get('high', 1)
        population = np.random.uniform(low=low, high=high, size=10000)
    elif population_dist == 'binomial':
        n = population_params.get('n', 10)
        p = population_params.get('p', 0.5)
        population = np.random.binomial(n=n, p=p, size=10000)
    else:
        population = np.random.normal(loc=population_params.get('loc', 0), scale=population_params.get('scale', 1), size=10000)
    population_mean = np.mean(population)
    population_std = np.std(population)
    results = {}
    for sample_size in sample_sizes:
        sample_means = []
        for _ in range(n_samples):
            sample = np.random.choice(population, size=sample_size, replace=True)
            sample_means.append(np.mean(sample))
        sample_means = np.array(sample_means)
        _, shapiro_p = stats.shapiro(sample_means) if len(sample_means) <= 5000 else (None, None)
        theoretical_mean = population_mean
        theoretical_std = population_std / np.sqrt(sample_size)
        empirical_mean = np.mean(sample_means)
        empirical_std = np.std(sample_means)
        results[f'n_{sample_size}'] = {'sample_means': sample_means.tolist(), 'empirical_mean': empirical_mean, 'empirical_std': empirical_std, 'theoretical_mean': theoretical_mean, 'theoretical_std': theoretical_std, 'mean_bias': empirical_mean - theoretical_mean, 'std_bias': empirical_std - theoretical_std, 'shapiro_p_value': shapiro_p, 'appears_normal': shapiro_p > 0.05 if shapiro_p is not None else None}
    return self._create_result_dict(value=results, method='central_limit_theorem', parameters={'population_dist': population_dist, 'population_params': population_params, 'sample_sizes': sample_sizes, 'n_samples': n_samples}, metadata={'population_mean': population_mean, 'population_std': population_std, 'population_size': len(population), 'clt_convergence': {str(n): results[f'n_{n}']['appears_normal'] for n in sample_sizes if f'n_{n}' in results}})

@validate_inputs
@timing_decorator
@handle_calculation_error
def advanced_resampling_analysis(self, data: Union[List, np.ndarray, pd.Series], statistic_func: Callable=np.mean, methods: List[str]=['bootstrap', 'jackknife', 'permutation'], n_resamples: int=1000) -> Dict[str, Any]:
    """Advanced resampling methods for statistical inference."""
    data = self._validate_returns(data, 'data')
    self._check_data_length(data, min_length=5)
    n_resamples = int(self._validate_positive(n_resamples, 'n_resamples'))
    if not callable(statistic_func):
        raise DataValidationError('statistic_func must be callable', 'statistic_func')
    original_stat = statistic_func(data)
    results = {}
    for method in methods:
        try:
            if method == 'bootstrap':
                bootstrap_stats = []
                for _ in range(n_resamples):
                    bootstrap_sample = np.random.choice(data, size=len(data), replace=True)
                    bootstrap_stats.append(statistic_func(bootstrap_sample))
                bootstrap_stats = np.array(bootstrap_stats)
                ci_lower = np.percentile(bootstrap_stats, 2.5)
                ci_upper = np.percentile(bootstrap_stats, 97.5)
                results['bootstrap'] = {'resampled_statistics': bootstrap_stats.tolist(), 'mean': np.mean(bootstrap_stats), 'std': np.std(bootstrap_stats), 'bias': np.mean(bootstrap_stats) - original_stat, 'confidence_interval': [ci_lower, ci_upper]}
            elif method == 'jackknife':
                n = len(data)
                jackknife_stats = []
                for i in range(n):
                    jackknife_sample = np.concatenate([data[:i], data[i + 1:]])
                    jackknife_stats.append(statistic_func(jackknife_sample))
                jackknife_stats = np.array(jackknife_stats)
                jackknife_mean = np.mean(jackknife_stats)
                bias = (n - 1) * (jackknife_mean - original_stat)
                bias_corrected = original_stat - bias
                jackknife_var = (n - 1) / n * np.sum((jackknife_stats - jackknife_mean) ** 2)
                results['jackknife'] = {'resampled_statistics': jackknife_stats.tolist(), 'bias': bias, 'bias_corrected_estimate': bias_corrected, 'variance_estimate': jackknife_var, 'std_error': np.sqrt(jackknife_var)}
            elif method == 'permutation':
                permutation_stats = []
                for _ in range(n_resamples):
                    signs = np.random.choice([-1, 1], size=len(data))
                    permuted_data = data * signs
                    permutation_stats.append(statistic_func(permuted_data))
                permutation_stats = np.array(permutation_stats)
                p_value = np.mean(np.abs(permutation_stats) >= np.abs(original_stat))
                results['permutation'] = {'resampled_statistics': permutation_stats.tolist(), 'p_value': p_value, 'significant': p_value < 0.05}
        except Exception as e:
            results[method] = {'error': str(e)}
    return self._create_result_dict(value=results, method='advanced_resampling', parameters={'data': data.tolist() if hasattr(data, 'tolist') else list(data), 'methods': methods, 'n_resamples': n_resamples}, metadata={'original_statistic': original_stat, 'data_size': len(data), 'statistic_name': getattr(statistic_func, '__name__', 'custom_function')})

@validate_inputs
@timing_decorator
@handle_calculation_error
def calculate_sampling_error_analysis(self, population_mean: float, population_std: float, sample_sizes: List[int]=[10, 30, 50, 100, 500], confidence_level: float=0.95, n_simulations: int=1000) -> Dict[str, Any]:
    """Analyze sampling error and determine optimal sample sizes."""
    population_mean = self._validate_numeric_input(population_mean, 'population_mean')
    population_std = self._validate_positive(population_std, 'population_std')
    confidence_level = self._validate_probability(confidence_level, 'confidence_level')
    n_simulations = int(self._validate_positive(n_simulations, 'n_simulations'))
    alpha = 1 - confidence_level
    z_critical = stats.norm.ppf(1 - alpha / 2)
    results = {}
    for sample_size in sample_sizes:
        standard_error = population_std / np.sqrt(sample_size)
        margin_of_error = z_critical * standard_error
        sample_means = []
        for _ in range(n_simulations):
            sample = np.random.normal(population_mean, population_std, size=sample_size)
            sample_means.append(np.mean(sample))
        sample_means = np.array(sample_means)
        ci_lower = sample_means - margin_of_error
        ci_upper = sample_means + margin_of_error
        coverage = np.mean((ci_lower <= population_mean) & (population_mean <= ci_upper))
        mse = np.mean((sample_means - population_mean) ** 2)
        results[f'n_{sample_size}'] = {'sample_size': sample_size, 'theoretical_se': standard_error, 'empirical_se': np.std(sample_means), 'theoretical_moe': margin_of_error, 'empirical_moe': z_critical * np.std(sample_means), 'coverage_probability': coverage, 'mean_squared_error': mse, 'relative_error': standard_error / population_mean if population_mean != 0 else np.inf}
    target_moe = 0.1 * population_std
    recommended_n = int(np.ceil((z_critical * population_std / target_moe) ** 2))
    return self._create_result_dict(value=results, method='sampling_error_analysis', parameters={'population_mean': population_mean, 'population_std': population_std, 'sample_sizes': sample_sizes, 'confidence_level': confidence_level, 'n_simulations': n_simulations}, metadata={'recommended_sample_size': recommended_n, 'target_margin_of_error': target_moe, 'z_critical': z_critical, 'coverage_target': confidence_level})

def calculate(self, calculation_type: str, **kwargs) -> Dict[str, Any]:
    """Main calculation dispatcher for all advanced methods."""
    methods = {'trend_analysis': self.analyze_trend, 'stationarity_test': self.test_stationarity, 'arima_model': self.fit_arima_model, 'forecasting': self.generate_forecasts, 'supervised_learning': self.supervised_learning_analysis, 'unsupervised_learning': self.unsupervised_learning_analysis, 'model_evaluation': self.evaluate_model_performance, 'feature_engineering': self.feature_engineering_analysis, 'sampling_techniques': self.analyze_sampling_techniques, 'central_limit_theorem': self.demonstrate_central_limit_theorem, 'resampling_methods': self.advanced_resampling_analysis, 'sampling_error_analysis': self.calculate_sampling_error_analysis}
    if calculation_type not in methods:
        raise DataValidationError(f'Unknown calculation type: {calculation_type}', 'calculation_type')
    return methods[calculation_type](**kwargs)

def required_sample_size(population_std: float, margin_of_error: float, confidence: float=0.95) -> int:
    """Calculate required sample size."""
    z_critical = stats.norm.ppf(1 - (1 - confidence) / 2)
    return int(np.ceil((z_critical * population_std / margin_of_error) ** 2))

class DataValidator:
    """
    Comprehensive data validation and quality control system.
    """

    def __init__(self, strict_mode: bool=False):
        """
        Initialize data validator.

        Args:
            strict_mode: If True, raises exceptions for quality issues
        """
        self.strict_mode = strict_mode
        self.validation_rules = {}
        self._setup_default_rules()

    def _setup_default_rules(self):
        """Setup default validation rules."""
        self.validation_rules = {'min_observations': 2, 'max_missing_ratio': 0.1, 'outlier_std_threshold': 3.0, 'min_numeric_ratio': 0.95, 'date_format_patterns': ['%Y-%m-%d', '%m/%d/%Y', '%d/%m/%Y', '%Y-%m-%d %H:%M:%S', '%m/%d/%Y %H:%M:%S']}

    def validate_financial_data(self, data: Union[pd.DataFrame, pd.Series, np.ndarray, List], data_type: str='general', data_name: str='data') -> Tuple[Any, DataQualityReport]:
        """
        Comprehensive validation of financial data.

        Args:
            data: Input data to validate
            data_type: Type of financial data ('returns', 'prices', 'rates', 'general')
            data_name: Name for reporting purposes

        Returns:
            Tuple of (cleaned_data, quality_report)
        """
        report = DataQualityReport(data_name)
        try:
            if isinstance(data, (list, tuple)):
                data = pd.Series(data)
            elif isinstance(data, np.ndarray):
                if data.ndim == 1:
                    data = pd.Series(data)
                else:
                    data = pd.DataFrame(data)
            cleaned_data = self._validate_structure(data, report)
            if data_type == 'returns':
                cleaned_data = self._validate_returns(cleaned_data, report)
            elif data_type == 'prices':
                cleaned_data = self._validate_prices(cleaned_data, report)
            elif data_type == 'rates':
                cleaned_data = self._validate_rates(cleaned_data, report)
            self._check_data_quality(cleaned_data, report)
            self._generate_recommendations(cleaned_data, report)
            return (cleaned_data, report)
        except Exception as e:
            report.add_issue('validation_error', f'Validation failed: {str(e)}', 'critical')
            if self.strict_mode:
                raise
            return (data, report)

    def _validate_structure(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport) -> Union[pd.DataFrame, pd.Series]:
        """Validate basic data structure."""
        if len(data) == 0:
            report.add_issue('empty_data', 'Dataset is empty', 'critical')
            if self.strict_mode:
                raise ValueError('Dataset is empty')
        if len(data) < self.validation_rules['min_observations']:
            report.add_issue('insufficient_data', f'Only {len(data)} observations, minimum {self.validation_rules['min_observations']} required', 'high')
        if isinstance(data, (pd.DataFrame, pd.Series)):
            if data.index.duplicated().any():
                report.add_warning('duplicate_index', 'Duplicate index values found')
                data = data.loc[~data.index.duplicated(keep='first')]
        report.statistics['total_observations'] = len(data)
        return data

    def _validate_returns(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport) -> Union[pd.DataFrame, pd.Series]:
        """Validate return data specifically."""
        if isinstance(data, pd.DataFrame):
            numeric_data = data.select_dtypes(include=[np.number])
        else:
            numeric_data = data
        if isinstance(numeric_data, pd.DataFrame):
            for col in numeric_data.columns:
                extreme_returns = numeric_data[col].abs() > 1.0
                if extreme_returns.any():
                    count = extreme_returns.sum()
                    report.add_warning('extreme_returns', f'Column {col}: {count} returns > 100% found')
        else:
            extreme_returns = numeric_data.abs() > 1.0
            if extreme_returns.any():
                count = extreme_returns.sum()
                report.add_warning('extreme_returns', f'{count} returns > 100% found')
        self._check_return_patterns(numeric_data, report)
        return data

    def _validate_prices(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport) -> Union[pd.DataFrame, pd.Series]:
        """Validate price data specifically."""
        if isinstance(data, pd.DataFrame):
            numeric_data = data.select_dtypes(include=[np.number])
        else:
            numeric_data = data
        if isinstance(numeric_data, pd.DataFrame):
            for col in numeric_data.columns:
                negative_prices = numeric_data[col] <= 0
                if negative_prices.any():
                    count = negative_prices.sum()
                    report.add_issue('negative_prices', f'Column {col}: {count} non-positive prices found', 'high')
        else:
            negative_prices = numeric_data <= 0
            if negative_prices.any():
                count = negative_prices.sum()
                report.add_issue('negative_prices', f'{count} non-positive prices found', 'high')
        self._check_price_jumps(numeric_data, report)
        return data

    def _validate_rates(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport) -> Union[pd.DataFrame, pd.Series]:
        """Validate interest rate data specifically."""
        if isinstance(data, pd.DataFrame):
            numeric_data = data.select_dtypes(include=[np.number])
        else:
            numeric_data = data
        if isinstance(numeric_data, pd.DataFrame):
            for col in numeric_data.columns:
                high_rates = numeric_data[col] > 1.0
                if high_rates.any():
                    count = high_rates.sum()
                    report.add_warning('high_rates', f'Column {col}: {count} rates > 100% found')
        else:
            high_rates = numeric_data > 1.0
            if high_rates.any():
                count = high_rates.sum()
                report.add_warning('high_rates', f'{count} rates > 100% found')
        return data

    def _check_data_quality(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
        """Perform general data quality checks."""
        self._analyze_missing_data(data, report)
        self._detect_outliers(data, report)
        self._check_data_types(data, report)
        self._generate_statistics(data, report)

    def _analyze_missing_data(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
        """Analyze missing data patterns."""
        if isinstance(data, pd.DataFrame):
            total_cells = data.size
            missing_cells = data.isna().sum().sum()
            missing_ratio = missing_cells / total_cells if total_cells > 0 else 0
            missing_by_column = data.isna().sum()
            for col, missing_count in missing_by_column.items():
                if missing_count > 0:
                    col_ratio = missing_count / len(data)
                    if col_ratio > self.validation_rules['max_missing_ratio']:
                        report.add_issue('high_missing_data', f'Column {col}: {col_ratio:.1%} missing data', 'medium')
        else:
            missing_count = data.isna().sum()
            missing_ratio = missing_count / len(data) if len(data) > 0 else 0
            if missing_ratio > self.validation_rules['max_missing_ratio']:
                report.add_issue('high_missing_data', f'{missing_ratio:.1%} missing data', 'medium')
        report.statistics['missing_data_ratio'] = round(missing_ratio, 4)

    def _detect_outliers(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
        """Detect statistical outliers."""

        def detect_outliers_series(series: pd.Series, name: str=''):
            if not pd.api.types.is_numeric_dtype(series):
                return
            clean_series = series.dropna()
            if len(clean_series) < 3:
                return
            z_scores = np.abs(stats.zscore(clean_series))
            outliers_zscore = z_scores > self.validation_rules['outlier_std_threshold']
            Q1 = clean_series.quantile(0.25)
            Q3 = clean_series.quantile(0.75)
            IQR = Q3 - Q1
            outliers_iqr = (clean_series < Q1 - 1.5 * IQR) | (clean_series > Q3 + 1.5 * IQR)
            outlier_count_z = outliers_zscore.sum()
            outlier_count_iqr = outliers_iqr.sum()
            if outlier_count_z > 0:
                report.add_warning('outliers_zscore', f'{name}Z-score outliers detected: {outlier_count_z}')
            if outlier_count_iqr > 0:
                report.add_warning('outliers_iqr', f'{name}IQR outliers detected: {outlier_count_iqr}')
        if isinstance(data, pd.DataFrame):
            numeric_cols = data.select_dtypes(include=[np.number]).columns
            for col in numeric_cols:
                detect_outliers_series(data[col], f'Column {col}: ')
        else:
            detect_outliers_series(data)

    def _check_data_types(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
        """Check data type consistency."""
        if isinstance(data, pd.DataFrame):
            numeric_cols = data.select_dtypes(include=[np.number]).columns
            total_cols = len(data.columns)
            numeric_ratio = len(numeric_cols) / total_cols if total_cols > 0 else 0
            if numeric_ratio < self.validation_rules['min_numeric_ratio']:
                report.add_warning('low_numeric_ratio', f'Only {numeric_ratio:.1%} of columns are numeric')
            for col in data.columns:
                if data[col].dtype == 'object':
                    sample = data[col].dropna().head(100)
                    if self._looks_like_numeric(sample):
                        report.add_issue('type_mismatch', f'Column {col} contains numeric data stored as text', 'medium')
                    elif self._looks_like_date(sample):
                        report.add_issue('type_mismatch', f'Column {col} contains date data stored as text', 'medium')
        report.statistics['data_types'] = data.dtypes.astype(str).to_dict() if isinstance(data, pd.DataFrame) else str(data.dtype)

    def _looks_like_numeric(self, sample: pd.Series) -> bool:
        """Check if text data looks like it should be numeric."""
        if len(sample) == 0:
            return False
        numeric_pattern = re.compile('^-?\\d*\\.?\\d+([eE][+-]?\\d+)?')
        numeric_count = sample.astype(str).str.match(numeric_pattern).sum()
        return numeric_count / len(sample) > 0.8

    def _looks_like_date(self, sample: pd.Series) -> bool:
        """Check if text data looks like it should be dates."""
        if len(sample) == 0:
            return False
        date_patterns = ['\\d{4}-\\d{2}-\\d{2}', '\\d{2}/\\d{2}/\\d{4}', '\\d{2}-\\d{2}-\\d{4}']
        for pattern in date_patterns:
            matches = sample.astype(str).str.match(pattern).sum()
            if matches / len(sample) > 0.8:
                return True
        return False

    def _generate_statistics(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
        """Generate comprehensive statistics for the data."""
        if isinstance(data, pd.DataFrame):
            numeric_data = data.select_dtypes(include=[np.number])
            if not numeric_data.empty:
                stats_dict = {'shape': data.shape, 'numeric_columns': len(numeric_data.columns), 'total_columns': len(data.columns), 'memory_usage_mb': round(data.memory_usage(deep=True).sum() / 1024 ** 2, 2)}
                desc_stats = numeric_data.describe()
                stats_dict['summary_statistics'] = desc_stats.to_dict()
        elif pd.api.types.is_numeric_dtype(data):
            clean_data = data.dropna()
            stats_dict = {'length': len(data), 'non_null_count': len(clean_data), 'mean': float(clean_data.mean()) if len(clean_data) > 0 else None, 'std': float(clean_data.std()) if len(clean_data) > 1 else None, 'min': float(clean_data.min()) if len(clean_data) > 0 else None, 'max': float(clean_data.max()) if len(clean_data) > 0 else None, 'skewness': float(clean_data.skew()) if len(clean_data) > 2 else None, 'kurtosis': float(clean_data.kurtosis()) if len(clean_data) > 3 else None}
        else:
            stats_dict = {'length': len(data), 'non_null_count': data.notna().sum(), 'unique_values': data.nunique(), 'data_type': str(data.dtype)}
        report.statistics.update(stats_dict)

    def _check_return_patterns(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
        """Check for suspicious patterns in return data."""

        def check_series_patterns(series: pd.Series, name: str=''):
            clean_series = series.dropna()
            if len(clean_series) < 10:
                return
            zero_count = (clean_series == 0).sum()
            zero_ratio = zero_count / len(clean_series)
            if zero_ratio > 0.1:
                report.add_warning('high_zero_returns', f'{name}High proportion of zero returns: {zero_ratio:.1%}')
            if len(clean_series) > 20:
                for window in [5, 10]:
                    if len(clean_series) >= window * 3:
                        rolling_std = clean_series.rolling(window).std()
                        low_variance_periods = (rolling_std < 0.001).sum()
                        if low_variance_periods > len(clean_series) * 0.1:
                            report.add_warning('low_variance_periods', f'{name}Detected periods with suspiciously low variance')
            if len(clean_series) > 30:
                try:
                    jb_stat, jb_pvalue = stats.jarque_bera(clean_series)
                    if jb_pvalue < 0.01:
                        report.add_warning('non_normal_returns', f'{name}Returns significantly deviate from normal distribution')
                except:
                    pass
        if isinstance(data, pd.DataFrame):
            for col in data.select_dtypes(include=[np.number]).columns:
                check_series_patterns(data[col], f'Column {col}: ')
        else:
            check_series_patterns(data)

    def _check_price_jumps(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
        """Check for suspicious price jumps."""

        def check_series_jumps(series: pd.Series, name: str=''):
            clean_series = series.dropna()
            if len(clean_series) < 2:
                return
            price_changes = clean_series.pct_change().dropna()
            large_jumps = price_changes.abs() > 0.5
            if large_jumps.any():
                jump_count = large_jumps.sum()
                report.add_warning('large_price_jumps', f'{name}{jump_count} large price jumps (>50%) detected')
            halving = (price_changes > -0.55) & (price_changes < -0.45)
            doubling = (price_changes > 0.95) & (price_changes < 1.05)
            if halving.any() or doubling.any():
                report.add_warning('potential_splits', f'{name}Potential stock splits/reverse splits detected')
        if isinstance(data, pd.DataFrame):
            for col in data.select_dtypes(include=[np.number]).columns:
                check_series_jumps(data[col], f'Column {col}: ')
        else:
            check_series_jumps(data)

    def _generate_recommendations(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
        """Generate data improvement recommendations."""
        issue_types = [issue['type'] for issue in report.issues]
        warning_types = [warning['type'] for warning in report.warnings]
        if 'high_missing_data' in issue_types:
            report.add_recommendation('Consider using interpolation or forward-fill for missing data')
            report.add_recommendation('Investigate the source of missing data - is it systematic?')
        if 'negative_prices' in issue_types:
            report.add_recommendation('Remove or correct negative price observations')
            report.add_recommendation('Verify data source and collection methodology')
        if 'extreme_returns' in warning_types:
            report.add_recommendation('Review extreme returns - may indicate data errors or corporate actions')
            report.add_recommendation('Consider winsorizing extreme values if confirmed as outliers')
        if 'outliers_zscore' in warning_types or 'outliers_iqr' in warning_types:
            report.add_recommendation('Investigate outliers - may be valid extreme events or data errors')
            report.add_recommendation('Consider robust statistical methods that are less sensitive to outliers')
        if 'type_mismatch' in issue_types:
            report.add_recommendation('Convert text columns to appropriate data types (numeric/datetime)')
            report.add_recommendation('Standardize data formats before importing')
        if 'insufficient_data' in issue_types:
            report.add_recommendation('Collect more historical data for reliable statistical analysis')
            report.add_recommendation('Consider using higher frequency data if available')
        if len(report.recommendations) == 0:
            report.add_recommendation('Data quality appears good - proceed with analysis')

    def clean_data(self, data: Union[pd.DataFrame, pd.Series], method: str='conservative', **kwargs) -> Union[pd.DataFrame, pd.Series]:
        """
        Clean data based on validation results.

        Args:
            data: Data to clean
            method: Cleaning method ('conservative', 'aggressive', 'custom')
            **kwargs: Additional parameters for cleaning

        Returns:
            Cleaned data
        """
        cleaned_data = data.copy()
        if method == 'conservative':
            if isinstance(cleaned_data, pd.DataFrame):
                cleaned_data = cleaned_data.dropna(how='all')
                numeric_cols = cleaned_data.select_dtypes(include=[np.number]).columns
                for col in numeric_cols:
                    if 'price' in col.lower():
                        cleaned_data = cleaned_data[cleaned_data[col] > 0]
            else:
                cleaned_data = cleaned_data.dropna()
        elif method == 'aggressive':
            if isinstance(cleaned_data, pd.DataFrame):
                missing_ratio = cleaned_data.isna().mean()
                cols_to_keep = missing_ratio[missing_ratio <= 0.5].index
                cleaned_data = cleaned_data[cols_to_keep]
                numeric_cols = cleaned_data.select_dtypes(include=[np.number]).columns
                for col in numeric_cols:
                    Q1 = cleaned_data[col].quantile(0.25)
                    Q3 = cleaned_data[col].quantile(0.75)
                    IQR = Q3 - Q1
                    lower_bound = Q1 - 1.5 * IQR
                    upper_bound = Q3 + 1.5 * IQR
                    cleaned_data = cleaned_data[(cleaned_data[col] >= lower_bound) & (cleaned_data[col] <= upper_bound)]
            else:
                Q1 = cleaned_data.quantile(0.25)
                Q3 = cleaned_data.quantile(0.75)
                IQR = Q3 - Q1
                lower_bound = Q1 - 1.5 * IQR
                upper_bound = Q3 + 1.5 * IQR
                cleaned_data = cleaned_data[(cleaned_data >= lower_bound) & (cleaned_data <= upper_bound)]
        return cleaned_data

    def validate_date_range(self, dates: Union[pd.DatetimeIndex, pd.Series, List], start_date: Optional[datetime]=None, end_date: Optional[datetime]=None) -> Tuple[bool, List[str]]:
        """
        Validate date range and continuity.

        Args:
            dates: Date data to validate
            start_date: Expected start date
            end_date: Expected end date

        Returns:
            Tuple of (is_valid, list_of_issues)
        """
        issues = []
        try:
            if isinstance(dates, list):
                dates = pd.to_datetime(dates)
            elif isinstance(dates, pd.Series):
                dates = pd.to_datetime(dates)
            if dates.duplicated().any():
                issues.append('Duplicate dates found')
            if not dates.is_monotonic_increasing:
                issues.append('Dates are not in chronological order')
            if start_date and dates.min() < start_date:
                issues.append(f'Data starts before expected date: {start_date}')
            if end_date and dates.max() > end_date:
                issues.append(f'Data ends after expected date: {end_date}')
            if len(dates) > 1:
                date_diffs = dates.to_series().diff().dropna()
                median_diff = date_diffs.median()
                large_gaps = date_diffs > median_diff * 5
                if large_gaps.any():
                    gap_count = large_gaps.sum()
                    issues.append(f'Found {gap_count} large gaps in date sequence')
            return (len(issues) == 0, issues)
        except Exception as e:
            issues.append(f'Date validation error: {str(e)}')
            return (False, issues)

    def validate_correlation_matrix(self, corr_matrix: pd.DataFrame, tolerance: float=1e-06) -> Tuple[bool, List[str]]:
        """
        Validate correlation matrix properties.

        Args:
            corr_matrix: Correlation matrix to validate
            tolerance: Numerical tolerance for validation

        Returns:
            Tuple of (is_valid, list_of_issues)
        """
        issues = []
        try:
            if corr_matrix.shape[0] != corr_matrix.shape[1]:
                issues.append('Correlation matrix is not square')
                return (False, issues)
            if not np.allclose(corr_matrix.values, corr_matrix.values.T, atol=tolerance):
                issues.append('Correlation matrix is not symmetric')
            diagonal = np.diag(corr_matrix.values)
            if not np.allclose(diagonal, 1.0, atol=tolerance):
                issues.append('Diagonal elements are not equal to 1')
            if (corr_matrix.values < -1 - tolerance).any() or (corr_matrix.values > 1 + tolerance).any():
                issues.append('Correlation values outside [-1, 1] range')
            off_diagonal = corr_matrix.values[~np.eye(corr_matrix.shape[0], dtype=bool)]
            perfect_corrs = np.abs(off_diagonal) > 1 - tolerance
            if perfect_corrs.any():
                issues.append('Perfect correlations detected (may indicate data issues)')
            eigenvals = np.linalg.eigvals(corr_matrix.values)
            if (eigenvals < -tolerance).any():
                issues.append('Correlation matrix is not positive semi-definite')
            return (len(issues) == 0, issues)
        except Exception as e:
            issues.append(f'Correlation matrix validation error: {str(e)}')
            return (False, issues)

    def validate_portfolio_weights(self, weights: Union[List, np.ndarray, pd.Series], tolerance: float=1e-06) -> Tuple[bool, List[str]]:
        """
        Validate portfolio weights.

        Args:
            weights: Portfolio weights to validate
            tolerance: Numerical tolerance

        Returns:
            Tuple of (is_valid, list_of_issues)
        """
        issues = []
        try:
            weights = np.array(weights)
            weights_sum = np.sum(weights)
            if not np.isclose(weights_sum, 1.0, atol=tolerance):
                issues.append(f'Weights sum to {weights_sum:.6f}, not 1.0')
            if (weights < -tolerance).any():
                negative_count = (weights < -tolerance).sum()
                issues.append(f'Found {negative_count} negative weights (short positions)')
            very_small = np.abs(weights) < tolerance
            if very_small.any():
                small_count = very_small.sum()
                issues.append(f'Found {small_count} very small weights (< {tolerance})')
            return (len(issues) == 0, issues)
        except Exception as e:
            issues.append(f'Portfolio weights validation error: {str(e)}')
            return (False, issues)

def validate_financial_data(self, data: Union[pd.DataFrame, pd.Series, np.ndarray, List], data_type: str='general', data_name: str='data') -> Tuple[Any, DataQualityReport]:
    """
        Comprehensive validation of financial data.

        Args:
            data: Input data to validate
            data_type: Type of financial data ('returns', 'prices', 'rates', 'general')
            data_name: Name for reporting purposes

        Returns:
            Tuple of (cleaned_data, quality_report)
        """
    report = DataQualityReport(data_name)
    try:
        if isinstance(data, (list, tuple)):
            data = pd.Series(data)
        elif isinstance(data, np.ndarray):
            if data.ndim == 1:
                data = pd.Series(data)
            else:
                data = pd.DataFrame(data)
        cleaned_data = self._validate_structure(data, report)
        if data_type == 'returns':
            cleaned_data = self._validate_returns(cleaned_data, report)
        elif data_type == 'prices':
            cleaned_data = self._validate_prices(cleaned_data, report)
        elif data_type == 'rates':
            cleaned_data = self._validate_rates(cleaned_data, report)
        self._check_data_quality(cleaned_data, report)
        self._generate_recommendations(cleaned_data, report)
        return (cleaned_data, report)
    except Exception as e:
        report.add_issue('validation_error', f'Validation failed: {str(e)}', 'critical')
        if self.strict_mode:
            raise
        return (data, report)

def _validate_structure(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport) -> Union[pd.DataFrame, pd.Series]:
    """Validate basic data structure."""
    if len(data) == 0:
        report.add_issue('empty_data', 'Dataset is empty', 'critical')
        if self.strict_mode:
            raise ValueError('Dataset is empty')
    if len(data) < self.validation_rules['min_observations']:
        report.add_issue('insufficient_data', f'Only {len(data)} observations, minimum {self.validation_rules['min_observations']} required', 'high')
    if isinstance(data, (pd.DataFrame, pd.Series)):
        if data.index.duplicated().any():
            report.add_warning('duplicate_index', 'Duplicate index values found')
            data = data.loc[~data.index.duplicated(keep='first')]
    report.statistics['total_observations'] = len(data)
    return data

def _validate_returns(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport) -> Union[pd.DataFrame, pd.Series]:
    """Validate return data specifically."""
    if isinstance(data, pd.DataFrame):
        numeric_data = data.select_dtypes(include=[np.number])
    else:
        numeric_data = data
    if isinstance(numeric_data, pd.DataFrame):
        for col in numeric_data.columns:
            extreme_returns = numeric_data[col].abs() > 1.0
            if extreme_returns.any():
                count = extreme_returns.sum()
                report.add_warning('extreme_returns', f'Column {col}: {count} returns > 100% found')
    else:
        extreme_returns = numeric_data.abs() > 1.0
        if extreme_returns.any():
            count = extreme_returns.sum()
            report.add_warning('extreme_returns', f'{count} returns > 100% found')
    self._check_return_patterns(numeric_data, report)
    return data

def _validate_prices(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport) -> Union[pd.DataFrame, pd.Series]:
    """Validate price data specifically."""
    if isinstance(data, pd.DataFrame):
        numeric_data = data.select_dtypes(include=[np.number])
    else:
        numeric_data = data
    if isinstance(numeric_data, pd.DataFrame):
        for col in numeric_data.columns:
            negative_prices = numeric_data[col] <= 0
            if negative_prices.any():
                count = negative_prices.sum()
                report.add_issue('negative_prices', f'Column {col}: {count} non-positive prices found', 'high')
    else:
        negative_prices = numeric_data <= 0
        if negative_prices.any():
            count = negative_prices.sum()
            report.add_issue('negative_prices', f'{count} non-positive prices found', 'high')
    self._check_price_jumps(numeric_data, report)
    return data

def _validate_rates(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport) -> Union[pd.DataFrame, pd.Series]:
    """Validate interest rate data specifically."""
    if isinstance(data, pd.DataFrame):
        numeric_data = data.select_dtypes(include=[np.number])
    else:
        numeric_data = data
    if isinstance(numeric_data, pd.DataFrame):
        for col in numeric_data.columns:
            high_rates = numeric_data[col] > 1.0
            if high_rates.any():
                count = high_rates.sum()
                report.add_warning('high_rates', f'Column {col}: {count} rates > 100% found')
    else:
        high_rates = numeric_data > 1.0
        if high_rates.any():
            count = high_rates.sum()
            report.add_warning('high_rates', f'{count} rates > 100% found')
    return data

def _analyze_missing_data(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
    """Analyze missing data patterns."""
    if isinstance(data, pd.DataFrame):
        total_cells = data.size
        missing_cells = data.isna().sum().sum()
        missing_ratio = missing_cells / total_cells if total_cells > 0 else 0
        missing_by_column = data.isna().sum()
        for col, missing_count in missing_by_column.items():
            if missing_count > 0:
                col_ratio = missing_count / len(data)
                if col_ratio > self.validation_rules['max_missing_ratio']:
                    report.add_issue('high_missing_data', f'Column {col}: {col_ratio:.1%} missing data', 'medium')
    else:
        missing_count = data.isna().sum()
        missing_ratio = missing_count / len(data) if len(data) > 0 else 0
        if missing_ratio > self.validation_rules['max_missing_ratio']:
            report.add_issue('high_missing_data', f'{missing_ratio:.1%} missing data', 'medium')
    report.statistics['missing_data_ratio'] = round(missing_ratio, 4)

def detect_outliers_series(series: pd.Series, name: str=''):
    if not pd.api.types.is_numeric_dtype(series):
        return
    clean_series = series.dropna()
    if len(clean_series) < 3:
        return
    z_scores = np.abs(stats.zscore(clean_series))
    outliers_zscore = z_scores > self.validation_rules['outlier_std_threshold']
    Q1 = clean_series.quantile(0.25)
    Q3 = clean_series.quantile(0.75)
    IQR = Q3 - Q1
    outliers_iqr = (clean_series < Q1 - 1.5 * IQR) | (clean_series > Q3 + 1.5 * IQR)
    outlier_count_z = outliers_zscore.sum()
    outlier_count_iqr = outliers_iqr.sum()
    if outlier_count_z > 0:
        report.add_warning('outliers_zscore', f'{name}Z-score outliers detected: {outlier_count_z}')
    if outlier_count_iqr > 0:
        report.add_warning('outliers_iqr', f'{name}IQR outliers detected: {outlier_count_iqr}')

def _detect_outliers(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
    """Detect statistical outliers."""

    def detect_outliers_series(series: pd.Series, name: str=''):
        if not pd.api.types.is_numeric_dtype(series):
            return
        clean_series = series.dropna()
        if len(clean_series) < 3:
            return
        z_scores = np.abs(stats.zscore(clean_series))
        outliers_zscore = z_scores > self.validation_rules['outlier_std_threshold']
        Q1 = clean_series.quantile(0.25)
        Q3 = clean_series.quantile(0.75)
        IQR = Q3 - Q1
        outliers_iqr = (clean_series < Q1 - 1.5 * IQR) | (clean_series > Q3 + 1.5 * IQR)
        outlier_count_z = outliers_zscore.sum()
        outlier_count_iqr = outliers_iqr.sum()
        if outlier_count_z > 0:
            report.add_warning('outliers_zscore', f'{name}Z-score outliers detected: {outlier_count_z}')
        if outlier_count_iqr > 0:
            report.add_warning('outliers_iqr', f'{name}IQR outliers detected: {outlier_count_iqr}')
    if isinstance(data, pd.DataFrame):
        numeric_cols = data.select_dtypes(include=[np.number]).columns
        for col in numeric_cols:
            detect_outliers_series(data[col], f'Column {col}: ')
    else:
        detect_outliers_series(data)

def _check_data_types(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
    """Check data type consistency."""
    if isinstance(data, pd.DataFrame):
        numeric_cols = data.select_dtypes(include=[np.number]).columns
        total_cols = len(data.columns)
        numeric_ratio = len(numeric_cols) / total_cols if total_cols > 0 else 0
        if numeric_ratio < self.validation_rules['min_numeric_ratio']:
            report.add_warning('low_numeric_ratio', f'Only {numeric_ratio:.1%} of columns are numeric')
        for col in data.columns:
            if data[col].dtype == 'object':
                sample = data[col].dropna().head(100)
                if self._looks_like_numeric(sample):
                    report.add_issue('type_mismatch', f'Column {col} contains numeric data stored as text', 'medium')
                elif self._looks_like_date(sample):
                    report.add_issue('type_mismatch', f'Column {col} contains date data stored as text', 'medium')
    report.statistics['data_types'] = data.dtypes.astype(str).to_dict() if isinstance(data, pd.DataFrame) else str(data.dtype)

def _generate_statistics(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
    """Generate comprehensive statistics for the data."""
    if isinstance(data, pd.DataFrame):
        numeric_data = data.select_dtypes(include=[np.number])
        if not numeric_data.empty:
            stats_dict = {'shape': data.shape, 'numeric_columns': len(numeric_data.columns), 'total_columns': len(data.columns), 'memory_usage_mb': round(data.memory_usage(deep=True).sum() / 1024 ** 2, 2)}
            desc_stats = numeric_data.describe()
            stats_dict['summary_statistics'] = desc_stats.to_dict()
    elif pd.api.types.is_numeric_dtype(data):
        clean_data = data.dropna()
        stats_dict = {'length': len(data), 'non_null_count': len(clean_data), 'mean': float(clean_data.mean()) if len(clean_data) > 0 else None, 'std': float(clean_data.std()) if len(clean_data) > 1 else None, 'min': float(clean_data.min()) if len(clean_data) > 0 else None, 'max': float(clean_data.max()) if len(clean_data) > 0 else None, 'skewness': float(clean_data.skew()) if len(clean_data) > 2 else None, 'kurtosis': float(clean_data.kurtosis()) if len(clean_data) > 3 else None}
    else:
        stats_dict = {'length': len(data), 'non_null_count': data.notna().sum(), 'unique_values': data.nunique(), 'data_type': str(data.dtype)}
    report.statistics.update(stats_dict)

def check_series_patterns(series: pd.Series, name: str=''):
    clean_series = series.dropna()
    if len(clean_series) < 10:
        return
    zero_count = (clean_series == 0).sum()
    zero_ratio = zero_count / len(clean_series)
    if zero_ratio > 0.1:
        report.add_warning('high_zero_returns', f'{name}High proportion of zero returns: {zero_ratio:.1%}')
    if len(clean_series) > 20:
        for window in [5, 10]:
            if len(clean_series) >= window * 3:
                rolling_std = clean_series.rolling(window).std()
                low_variance_periods = (rolling_std < 0.001).sum()
                if low_variance_periods > len(clean_series) * 0.1:
                    report.add_warning('low_variance_periods', f'{name}Detected periods with suspiciously low variance')
    if len(clean_series) > 30:
        try:
            jb_stat, jb_pvalue = stats.jarque_bera(clean_series)
            if jb_pvalue < 0.01:
                report.add_warning('non_normal_returns', f'{name}Returns significantly deviate from normal distribution')
        except:
            pass

def _check_return_patterns(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
    """Check for suspicious patterns in return data."""

    def check_series_patterns(series: pd.Series, name: str=''):
        clean_series = series.dropna()
        if len(clean_series) < 10:
            return
        zero_count = (clean_series == 0).sum()
        zero_ratio = zero_count / len(clean_series)
        if zero_ratio > 0.1:
            report.add_warning('high_zero_returns', f'{name}High proportion of zero returns: {zero_ratio:.1%}')
        if len(clean_series) > 20:
            for window in [5, 10]:
                if len(clean_series) >= window * 3:
                    rolling_std = clean_series.rolling(window).std()
                    low_variance_periods = (rolling_std < 0.001).sum()
                    if low_variance_periods > len(clean_series) * 0.1:
                        report.add_warning('low_variance_periods', f'{name}Detected periods with suspiciously low variance')
        if len(clean_series) > 30:
            try:
                jb_stat, jb_pvalue = stats.jarque_bera(clean_series)
                if jb_pvalue < 0.01:
                    report.add_warning('non_normal_returns', f'{name}Returns significantly deviate from normal distribution')
            except:
                pass
    if isinstance(data, pd.DataFrame):
        for col in data.select_dtypes(include=[np.number]).columns:
            check_series_patterns(data[col], f'Column {col}: ')
    else:
        check_series_patterns(data)

def check_series_jumps(series: pd.Series, name: str=''):
    clean_series = series.dropna()
    if len(clean_series) < 2:
        return
    price_changes = clean_series.pct_change().dropna()
    large_jumps = price_changes.abs() > 0.5
    if large_jumps.any():
        jump_count = large_jumps.sum()
        report.add_warning('large_price_jumps', f'{name}{jump_count} large price jumps (>50%) detected')
    halving = (price_changes > -0.55) & (price_changes < -0.45)
    doubling = (price_changes > 0.95) & (price_changes < 1.05)
    if halving.any() or doubling.any():
        report.add_warning('potential_splits', f'{name}Potential stock splits/reverse splits detected')

def _check_price_jumps(self, data: Union[pd.DataFrame, pd.Series], report: DataQualityReport):
    """Check for suspicious price jumps."""

    def check_series_jumps(series: pd.Series, name: str=''):
        clean_series = series.dropna()
        if len(clean_series) < 2:
            return
        price_changes = clean_series.pct_change().dropna()
        large_jumps = price_changes.abs() > 0.5
        if large_jumps.any():
            jump_count = large_jumps.sum()
            report.add_warning('large_price_jumps', f'{name}{jump_count} large price jumps (>50%) detected')
        halving = (price_changes > -0.55) & (price_changes < -0.45)
        doubling = (price_changes > 0.95) & (price_changes < 1.05)
        if halving.any() or doubling.any():
            report.add_warning('potential_splits', f'{name}Potential stock splits/reverse splits detected')
    if isinstance(data, pd.DataFrame):
        for col in data.select_dtypes(include=[np.number]).columns:
            check_series_jumps(data[col], f'Column {col}: ')
    else:
        check_series_jumps(data)

def clean_data(self, data: Union[pd.DataFrame, pd.Series], method: str='conservative', **kwargs) -> Union[pd.DataFrame, pd.Series]:
    """
        Clean data based on validation results.

        Args:
            data: Data to clean
            method: Cleaning method ('conservative', 'aggressive', 'custom')
            **kwargs: Additional parameters for cleaning

        Returns:
            Cleaned data
        """
    cleaned_data = data.copy()
    if method == 'conservative':
        if isinstance(cleaned_data, pd.DataFrame):
            cleaned_data = cleaned_data.dropna(how='all')
            numeric_cols = cleaned_data.select_dtypes(include=[np.number]).columns
            for col in numeric_cols:
                if 'price' in col.lower():
                    cleaned_data = cleaned_data[cleaned_data[col] > 0]
        else:
            cleaned_data = cleaned_data.dropna()
    elif method == 'aggressive':
        if isinstance(cleaned_data, pd.DataFrame):
            missing_ratio = cleaned_data.isna().mean()
            cols_to_keep = missing_ratio[missing_ratio <= 0.5].index
            cleaned_data = cleaned_data[cols_to_keep]
            numeric_cols = cleaned_data.select_dtypes(include=[np.number]).columns
            for col in numeric_cols:
                Q1 = cleaned_data[col].quantile(0.25)
                Q3 = cleaned_data[col].quantile(0.75)
                IQR = Q3 - Q1
                lower_bound = Q1 - 1.5 * IQR
                upper_bound = Q3 + 1.5 * IQR
                cleaned_data = cleaned_data[(cleaned_data[col] >= lower_bound) & (cleaned_data[col] <= upper_bound)]
        else:
            Q1 = cleaned_data.quantile(0.25)
            Q3 = cleaned_data.quantile(0.75)
            IQR = Q3 - Q1
            lower_bound = Q1 - 1.5 * IQR
            upper_bound = Q3 + 1.5 * IQR
            cleaned_data = cleaned_data[(cleaned_data >= lower_bound) & (cleaned_data <= upper_bound)]
    return cleaned_data

def validate_date_range(self, dates: Union[pd.DatetimeIndex, pd.Series, List], start_date: Optional[datetime]=None, end_date: Optional[datetime]=None) -> Tuple[bool, List[str]]:
    """
        Validate date range and continuity.

        Args:
            dates: Date data to validate
            start_date: Expected start date
            end_date: Expected end date

        Returns:
            Tuple of (is_valid, list_of_issues)
        """
    issues = []
    try:
        if isinstance(dates, list):
            dates = pd.to_datetime(dates)
        elif isinstance(dates, pd.Series):
            dates = pd.to_datetime(dates)
        if dates.duplicated().any():
            issues.append('Duplicate dates found')
        if not dates.is_monotonic_increasing:
            issues.append('Dates are not in chronological order')
        if start_date and dates.min() < start_date:
            issues.append(f'Data starts before expected date: {start_date}')
        if end_date and dates.max() > end_date:
            issues.append(f'Data ends after expected date: {end_date}')
        if len(dates) > 1:
            date_diffs = dates.to_series().diff().dropna()
            median_diff = date_diffs.median()
            large_gaps = date_diffs > median_diff * 5
            if large_gaps.any():
                gap_count = large_gaps.sum()
                issues.append(f'Found {gap_count} large gaps in date sequence')
        return (len(issues) == 0, issues)
    except Exception as e:
        issues.append(f'Date validation error: {str(e)}')
        return (False, issues)

def validate_correlation_matrix(self, corr_matrix: pd.DataFrame, tolerance: float=1e-06) -> Tuple[bool, List[str]]:
    """
        Validate correlation matrix properties.

        Args:
            corr_matrix: Correlation matrix to validate
            tolerance: Numerical tolerance for validation

        Returns:
            Tuple of (is_valid, list_of_issues)
        """
    issues = []
    try:
        if corr_matrix.shape[0] != corr_matrix.shape[1]:
            issues.append('Correlation matrix is not square')
            return (False, issues)
        if not np.allclose(corr_matrix.values, corr_matrix.values.T, atol=tolerance):
            issues.append('Correlation matrix is not symmetric')
        diagonal = np.diag(corr_matrix.values)
        if not np.allclose(diagonal, 1.0, atol=tolerance):
            issues.append('Diagonal elements are not equal to 1')
        if (corr_matrix.values < -1 - tolerance).any() or (corr_matrix.values > 1 + tolerance).any():
            issues.append('Correlation values outside [-1, 1] range')
        off_diagonal = corr_matrix.values[~np.eye(corr_matrix.shape[0], dtype=bool)]
        perfect_corrs = np.abs(off_diagonal) > 1 - tolerance
        if perfect_corrs.any():
            issues.append('Perfect correlations detected (may indicate data issues)')
        eigenvals = np.linalg.eigvals(corr_matrix.values)
        if (eigenvals < -tolerance).any():
            issues.append('Correlation matrix is not positive semi-definite')
        return (len(issues) == 0, issues)
    except Exception as e:
        issues.append(f'Correlation matrix validation error: {str(e)}')
        return (False, issues)

def validate_portfolio_weights(self, weights: Union[List, np.ndarray, pd.Series], tolerance: float=1e-06) -> Tuple[bool, List[str]]:
    """
        Validate portfolio weights.

        Args:
            weights: Portfolio weights to validate
            tolerance: Numerical tolerance

        Returns:
            Tuple of (is_valid, list_of_issues)
        """
    issues = []
    try:
        weights = np.array(weights)
        weights_sum = np.sum(weights)
        if not np.isclose(weights_sum, 1.0, atol=tolerance):
            issues.append(f'Weights sum to {weights_sum:.6f}, not 1.0')
        if (weights < -tolerance).any():
            negative_count = (weights < -tolerance).sum()
            issues.append(f'Found {negative_count} negative weights (short positions)')
        very_small = np.abs(weights) < tolerance
        if very_small.any():
            small_count = very_small.sum()
            issues.append(f'Found {small_count} very small weights (< {tolerance})')
        return (len(issues) == 0, issues)
    except Exception as e:
        issues.append(f'Portfolio weights validation error: {str(e)}')
        return (False, issues)

def validate_returns_series(returns: Union[List, np.ndarray, pd.Series], name: str='returns') -> np.ndarray:
    """Quick validation for return series."""
    validator = DataValidator()
    if isinstance(returns, (list, tuple)):
        returns = np.array(returns)
    elif isinstance(returns, pd.Series):
        returns = returns.values
    if len(returns) < 2:
        raise ValueError(f'{name} must have at least 2 observations')
    if np.any(np.isnan(returns)) or np.any(np.isinf(returns)):
        raise ValueError(f'{name} contains invalid values (NaN or Inf)')
    return returns.astype(float)

def validate_positive_number(value: Union[int, float], name: str='value') -> float:
    """Quick validation for positive numbers."""
    if not isinstance(value, (int, float)):
        raise TypeError(f'{name} must be a number')
    if np.isnan(value) or np.isinf(value):
        raise ValueError(f'{name} cannot be NaN or infinite')
    if value <= 0:
        raise ValueError(f'{name} must be positive')
    return float(value)

def validate_probability(prob: Union[int, float], name: str='probability') -> float:
    """Quick validation for probability values."""
    if not isinstance(prob, (int, float)):
        raise TypeError(f'{name} must be a number')
    if np.isnan(prob) or np.isinf(prob):
        raise ValueError(f'{name} cannot be NaN or infinite')
    if not 0 <= prob <= 1:
        raise ValueError(f'{name} must be between 0 and 1')
    return float(prob)

class StatisticalCalculations:
    """Core statistical calculations for financial analysis"""

    @staticmethod
    def calculate_mean(data: Union[np.ndarray, pd.Series]) -> float:
        """Calculate arithmetic mean"""
        return np.mean(data)

    @staticmethod
    def calculate_variance(data: Union[np.ndarray, pd.Series], ddof: int=1) -> float:
        """Calculate variance with degrees of freedom correction"""
        return np.var(data, ddof=ddof)

    @staticmethod
    def calculate_std(data: Union[np.ndarray, pd.Series], ddof: int=1) -> float:
        """Calculate standard deviation"""
        return np.std(data, ddof=ddof)

    @staticmethod
    def calculate_covariance(x: Union[np.ndarray, pd.Series], y: Union[np.ndarray, pd.Series], ddof: int=1) -> float:
        """Calculate covariance between two series"""
        return np.cov(x, y, ddof=ddof)[0, 1]

    @staticmethod
    def calculate_correlation(x: Union[np.ndarray, pd.Series], y: Union[np.ndarray, pd.Series]) -> float:
        """Calculate correlation coefficient"""
        return np.corrcoef(x, y)[0, 1]

    @staticmethod
    def calculate_beta(asset_returns: Union[np.ndarray, pd.Series], market_returns: Union[np.ndarray, pd.Series]) -> float:
        """Calculate beta coefficient"""
        covariance = StatisticalCalculations.calculate_covariance(asset_returns, market_returns)
        market_variance = StatisticalCalculations.calculate_variance(market_returns)
        return covariance / market_variance

    @staticmethod
    def calculate_tracking_error(portfolio_returns: Union[np.ndarray, pd.Series], benchmark_returns: Union[np.ndarray, pd.Series], annualize: bool=True) -> float:
        """Calculate tracking error"""
        excess_returns = np.array(portfolio_returns) - np.array(benchmark_returns)
        tracking_error = np.std(excess_returns, ddof=1)
        if annualize:
            tracking_error *= MathConstants.SQRT_TRADING_DAYS
        return tracking_error

    @staticmethod
    def calculate_downside_deviation(returns: Union[np.ndarray, pd.Series], target_return: float=0.0, annualize: bool=True) -> float:
        """Calculate downside deviation"""
        returns_array = np.array(returns)
        downside_returns = returns_array[returns_array < target_return]
        if len(downside_returns) == 0:
            return 0.0
        downside_dev = np.sqrt(np.mean((downside_returns - target_return) ** 2))
        if annualize:
            downside_dev *= MathConstants.SQRT_TRADING_DAYS
        return downside_dev

