class RiskCalculations:
    """Risk measurement and VaR calculations"""

    @staticmethod
    def value_at_risk_parametric(returns: Union[np.ndarray, pd.Series], confidence_level: float=0.95, holding_period: int=1) -> float:
        """Calculate parametric VaR"""
        returns_array = np.array(returns)
        mean_return = np.mean(returns_array)
        std_return = np.std(returns_array, ddof=1)
        z_score = stats.norm.ppf(1 - confidence_level)
        var = -(mean_return + z_score * std_return) * np.sqrt(holding_period)
        return var

    @staticmethod
    def value_at_risk_historical(returns: Union[np.ndarray, pd.Series], confidence_level: float=0.95, holding_period: int=1) -> float:
        """Calculate historical simulation VaR"""
        returns_array = np.array(returns)
        if holding_period > 1:
            returns_array = returns_array * np.sqrt(holding_period)
        sorted_returns = np.sort(returns_array)
        percentile = 1 - confidence_level
        var_index = int(np.ceil(len(sorted_returns) * percentile)) - 1
        var_index = max(0, min(var_index, len(sorted_returns) - 1))
        return -sorted_returns[var_index]

    @staticmethod
    def conditional_value_at_risk(returns: Union[np.ndarray, pd.Series], confidence_level: float=0.95, method: str='historical') -> float:
        """Calculate Conditional VaR (Expected Shortfall)"""
        returns_array = np.array(returns)
        if method == 'historical':
            var = RiskCalculations.value_at_risk_historical(returns_array, confidence_level)
            tail_returns = returns_array[returns_array <= -var]
            return -np.mean(tail_returns) if len(tail_returns) > 0 else var
        else:
            var = RiskCalculations.value_at_risk_parametric(returns_array, confidence_level)
            z_score = stats.norm.ppf(1 - confidence_level)
            mean_return = np.mean(returns_array)
            std_return = np.std(returns_array, ddof=1)
            cvar = -(mean_return - std_return * stats.norm.pdf(z_score) / (1 - confidence_level))
            return cvar

@staticmethod
def value_at_risk_parametric(returns: Union[np.ndarray, pd.Series], confidence_level: float=0.95, holding_period: int=1) -> float:
    """Calculate parametric VaR"""
    returns_array = np.array(returns)
    mean_return = np.mean(returns_array)
    std_return = np.std(returns_array, ddof=1)
    z_score = stats.norm.ppf(1 - confidence_level)
    var = -(mean_return + z_score * std_return) * np.sqrt(holding_period)
    return var

@staticmethod
def value_at_risk_historical(returns: Union[np.ndarray, pd.Series], confidence_level: float=0.95, holding_period: int=1) -> float:
    """Calculate historical simulation VaR"""
    returns_array = np.array(returns)
    if holding_period > 1:
        returns_array = returns_array * np.sqrt(holding_period)
    sorted_returns = np.sort(returns_array)
    percentile = 1 - confidence_level
    var_index = int(np.ceil(len(sorted_returns) * percentile)) - 1
    var_index = max(0, min(var_index, len(sorted_returns) - 1))
    return -sorted_returns[var_index]

@staticmethod
def conditional_value_at_risk(returns: Union[np.ndarray, pd.Series], confidence_level: float=0.95, method: str='historical') -> float:
    """Calculate Conditional VaR (Expected Shortfall)"""
    returns_array = np.array(returns)
    if method == 'historical':
        var = RiskCalculations.value_at_risk_historical(returns_array, confidence_level)
        tail_returns = returns_array[returns_array <= -var]
        return -np.mean(tail_returns) if len(tail_returns) > 0 else var
    else:
        var = RiskCalculations.value_at_risk_parametric(returns_array, confidence_level)
        z_score = stats.norm.ppf(1 - confidence_level)
        mean_return = np.mean(returns_array)
        std_return = np.std(returns_array, ddof=1)
        cvar = -(mean_return - std_return * stats.norm.pdf(z_score) / (1 - confidence_level))
        return cvar

class OptimizationEngine:
    """Portfolio optimization algorithms"""

    @staticmethod
    def efficient_frontier(expected_returns: np.ndarray, cov_matrix: np.ndarray, num_points: int=100, constraints: Optional[Dict]=None) -> Dict:
        """Generate efficient frontier"""
        n_assets = len(expected_returns)
        min_var_portfolio = PortfolioMath.find_minimum_variance_portfolio(cov_matrix, constraints)
        min_return = PortfolioMath.calculate_portfolio_return(min_var_portfolio['weights'], expected_returns)
        max_return = np.max(expected_returns)
        target_returns = np.linspace(min_return, max_return, num_points)
        frontier_weights = []
        frontier_returns = []
        frontier_stds = []
        frontier_sharpe = []
        for target_return in target_returns:
            try:

                def objective(weights):
                    return PortfolioMath.calculate_portfolio_variance(weights, cov_matrix)
                cons = [{'type': 'eq', 'fun': lambda w: np.sum(w) - 1.0}, {'type': 'eq', 'fun': lambda w, tr=target_return: PortfolioMath.calculate_portfolio_return(w, expected_returns) - tr}]
                if constraints:
                    if 'min_weight' in constraints:
                        cons.append({'type': 'ineq', 'fun': lambda w: w - constraints['min_weight']})
                    if 'max_weight' in constraints:
                        cons.append({'type': 'ineq', 'fun': lambda w: constraints['max_weight'] - w})
                bounds = tuple(((0, 1) for _ in range(n_assets)))
                x0 = np.ones(n_assets) / n_assets
                result = optimize.minimize(objective, x0, method='SLSQP', bounds=bounds, constraints=cons, options={'maxiter': MathConstants.MAX_ITERATIONS})
                if result.success:
                    weights = result.x
                    portfolio_return = PortfolioMath.calculate_portfolio_return(weights, expected_returns)
                    portfolio_std = PortfolioMath.calculate_portfolio_std(weights, cov_matrix)
                    sharpe = (portfolio_return - MathConstants.DEFAULT_RISK_FREE_RATE) / portfolio_std
                    frontier_weights.append(weights)
                    frontier_returns.append(portfolio_return)
                    frontier_stds.append(portfolio_std)
                    frontier_sharpe.append(sharpe)
            except:
                continue
        return {'returns': np.array(frontier_returns), 'stds': np.array(frontier_stds), 'weights': np.array(frontier_weights), 'sharpe_ratios': np.array(frontier_sharpe), 'min_var_portfolio': min_var_portfolio}

    @staticmethod
    def maximum_sharpe_portfolio(expected_returns: np.ndarray, cov_matrix: np.ndarray, risk_free_rate: float=MathConstants.DEFAULT_RISK_FREE_RATE, constraints: Optional[Dict]=None) -> Dict:
        """Find maximum Sharpe ratio portfolio"""
        n_assets = len(expected_returns)

        def objective(weights):
            portfolio_return = PortfolioMath.calculate_portfolio_return(weights, expected_returns)
            portfolio_std = PortfolioMath.calculate_portfolio_std(weights, cov_matrix)
            if portfolio_std == 0:
                return -np.inf
            sharpe = (portfolio_return - risk_free_rate) / portfolio_std
            return -sharpe
        cons = [{'type': 'eq', 'fun': lambda w: np.sum(w) - 1.0}]
        if constraints:
            if 'min_weight' in constraints:
                cons.append({'type': 'ineq', 'fun': lambda w: w - constraints['min_weight']})
            if 'max_weight' in constraints:
                cons.append({'type': 'ineq', 'fun': lambda w: constraints['max_weight'] - w})
        bounds = tuple(((0, 1) for _ in range(n_assets)))
        x0 = np.ones(n_assets) / n_assets
        result = optimize.minimize(objective, x0, method='SLSQP', bounds=bounds, constraints=cons, options={'maxiter': MathConstants.MAX_ITERATIONS})
        if not result.success:
            raise ValueError(ERROR_MESSAGES['optimization_failed'])
        optimal_weights = result.x
        portfolio_return = PortfolioMath.calculate_portfolio_return(optimal_weights, expected_returns)
        portfolio_std = PortfolioMath.calculate_portfolio_std(optimal_weights, cov_matrix)
        sharpe = (portfolio_return - risk_free_rate) / portfolio_std
        return {'weights': optimal_weights, 'expected_return': portfolio_return, 'std': portfolio_std, 'sharpe_ratio': sharpe, 'optimization_result': result}

