class DataManager:
    """Main data management interface"""

    def __init__(self, provider: Optional[DataProvider]=None, use_cache: bool=True):
        self.provider = provider or ManualDataProvider()
        self.validator = DataValidator()
        self.transformer = DataTransformer()
        self.cache = DataCache() if use_cache else None

    def get_validated_data(self, data_type: str, **kwargs) -> Tuple[pd.DataFrame, Dict]:
        """Get and validate data"""
        cache_key = f'{data_type}_{hash(str(kwargs))}'
        if self.cache:
            cached_result = self.cache.get(cache_key)
            if cached_result is not None:
                return cached_result
        if data_type == 'price':
            raw_data = self.provider.get_price_data(**kwargs)
            schema = PRICE_DATA_SCHEMA
        elif data_type == 'economic':
            raw_data = self.provider.get_economic_data(**kwargs)
            schema = None
        else:
            raise ValueError(f'Unknown data type: {data_type}')
        processed_data = {}
        validation_results = {}
        for key, df in raw_data.items():
            quality_report = self.validator.check_data_quality(df)
            if schema:
                is_valid, errors = self.validator.validate_schema(df, schema)
                validation_results[key] = {'valid': is_valid, 'errors': errors, 'quality': quality_report}
            cleaned_df = self.transformer.handle_missing_data(df)
            processed_data[key] = cleaned_df
        result = (processed_data, validation_results)
        if self.cache:
            self.cache.set(cache_key, result)
        return result

    def calculate_return_matrix(self, price_data: Dict[str, pd.DataFrame], return_type: str='simple') -> pd.DataFrame:
        """Calculate return matrix from price data"""
        returns_dict = {}
        for symbol, df in price_data.items():
            if 'close' in df.columns and 'date' in df.columns:
                df_sorted = df.sort_values('date')
                prices = df_sorted['close']
                returns = self.transformer.calculate_returns(prices, return_type)
                returns_dict[symbol] = returns
        if not returns_dict:
            raise ValueError('No valid price data found')
        return_matrix = pd.DataFrame(returns_dict)
        return return_matrix.dropna()

    def get_covariance_matrix(self, returns: pd.DataFrame, annualize: bool=True) -> np.ndarray:
        """Calculate covariance matrix from returns"""
        cov_matrix = returns.cov().values
        if annualize:
            cov_matrix *= MathConstants.TRADING_DAYS_YEAR
        return cov_matrix

    def get_correlation_matrix(self, returns: pd.DataFrame) -> np.ndarray:
        """Calculate correlation matrix from returns"""
        return returns.corr().values

def calculate_return_matrix(self, price_data: Dict[str, pd.DataFrame], return_type: str='simple') -> pd.DataFrame:
    """Calculate return matrix from price data"""
    returns_dict = {}
    for symbol, df in price_data.items():
        if 'close' in df.columns and 'date' in df.columns:
            df_sorted = df.sort_values('date')
            prices = df_sorted['close']
            returns = self.transformer.calculate_returns(prices, return_type)
            returns_dict[symbol] = returns
    if not returns_dict:
        raise ValueError('No valid price data found')
    return_matrix = pd.DataFrame(returns_dict)
    return return_matrix.dropna()

def get_covariance_matrix(self, returns: pd.DataFrame, annualize: bool=True) -> np.ndarray:
    """Calculate covariance matrix from returns"""
    cov_matrix = returns.cov().values
    if annualize:
        cov_matrix *= MathConstants.TRADING_DAYS_YEAR
    return cov_matrix

def get_correlation_matrix(self, returns: pd.DataFrame) -> np.ndarray:
    """Calculate correlation matrix from returns"""
    return returns.corr().values

class RiskGovernance:
    """Risk governance framework implementation"""

    def __init__(self):
        self.risk_policies = {}
        self.risk_limits = {}
        self.governance_structure = {}

    def define_risk_policy(self, policy_name: str, policy_details: Dict) -> None:
        """Define risk management policy"""
        required_fields = ['objective', 'scope', 'methodology', 'limits', 'reporting']
        for field in required_fields:
            if field not in policy_details:
                raise ValueError(f"Risk policy must include '{field}'")
        self.risk_policies[policy_name] = {'policy_details': policy_details, 'creation_date': pd.Timestamp.now(), 'last_review': pd.Timestamp.now(), 'status': 'active'}

    def set_risk_limits(self, limit_type: str, limits: Dict) -> None:
        """Set various types of risk limits"""
        valid_types = ['position', 'sector', 'var', 'tracking_error', 'leverage', 'concentration']
        if limit_type not in valid_types:
            raise ValueError(f'Limit type must be one of {valid_types}')
        self.risk_limits[limit_type] = limits

    def assess_governance_effectiveness(self) -> Dict:
        """Assess risk governance effectiveness"""
        return {'policies_defined': len(self.risk_policies), 'limits_established': len(self.risk_limits), 'governance_score': self._calculate_governance_score(), 'areas_for_improvement': self._identify_improvement_areas()}

    def _calculate_governance_score(self) -> float:
        """Calculate governance effectiveness score"""
        base_score = 0
        if len(self.risk_policies) >= 3:
            base_score += 30
        elif len(self.risk_policies) >= 1:
            base_score += 15
        if len(self.risk_limits) >= 4:
            base_score += 40
        elif len(self.risk_limits) >= 2:
            base_score += 20
        required_structures = ['risk_committee', 'cro', 'risk_reporting']
        structure_score = sum((20 for struct in required_structures if struct in self.governance_structure))
        base_score += structure_score
        return min(100, base_score)

    def _identify_improvement_areas(self) -> List[str]:
        """Identify areas needing improvement"""
        improvements = []
        if len(self.risk_policies) < 3:
            improvements.append('Expand risk policy coverage')
        if 'var' not in self.risk_limits:
            improvements.append('Establish VaR limits')
        if 'concentration' not in self.risk_limits:
            improvements.append('Set concentration limits')
        required_structures = ['risk_committee', 'cro', 'risk_reporting']
        missing_structures = [s for s in required_structures if s not in self.governance_structure]
        if missing_structures:
            improvements.append(f'Establish: {', '.join(missing_structures)}')
        return improvements

def define_risk_policy(self, policy_name: str, policy_details: Dict) -> None:
    """Define risk management policy"""
    required_fields = ['objective', 'scope', 'methodology', 'limits', 'reporting']
    for field in required_fields:
        if field not in policy_details:
            raise ValueError(f"Risk policy must include '{field}'")
    self.risk_policies[policy_name] = {'policy_details': policy_details, 'creation_date': pd.Timestamp.now(), 'last_review': pd.Timestamp.now(), 'status': 'active'}

def set_risk_limits(self, limit_type: str, limits: Dict) -> None:
    """Set various types of risk limits"""
    valid_types = ['position', 'sector', 'var', 'tracking_error', 'leverage', 'concentration']
    if limit_type not in valid_types:
        raise ValueError(f'Limit type must be one of {valid_types}')
    self.risk_limits[limit_type] = limits

class VaRCalculations:
    """Comprehensive Value at Risk calculations"""

    @staticmethod
    def parametric_var(returns: np.ndarray, confidence_level: float=0.95, holding_period: int=1, distribution: str='normal') -> Dict:
        """Calculate parametric VaR with multiple distributions"""
        if not validate_returns(returns):
            raise ValueError(ERROR_MESSAGES['insufficient_data'])
        returns_array = np.array(returns)
        if distribution == 'normal':
            mean_return = np.mean(returns_array)
            std_return = np.std(returns_array, ddof=1)
            z_score = stats.norm.ppf(1 - confidence_level)
            var = -(mean_return + z_score * std_return) * np.sqrt(holding_period)
        elif distribution == 't_distribution':
            params = stats.t.fit(returns_array)
            df, loc, scale = params
            t_score = stats.t.ppf(1 - confidence_level, df)
            var = -(loc + t_score * scale) * np.sqrt(holding_period)
        elif distribution == 'cornish_fisher':
            mean_return = np.mean(returns_array)
            std_return = np.std(returns_array, ddof=1)
            skewness = stats.skew(returns_array)
            kurtosis = stats.kurtosis(returns_array, fisher=False)
            z = stats.norm.ppf(1 - confidence_level)
            z_cf = z + (z ** 2 - 1) * skewness / 6 + (z ** 3 - 3 * z) * (kurtosis - 3) / 24
            var = -(mean_return + z_cf * std_return) * np.sqrt(holding_period)
        else:
            raise ValueError("Distribution must be 'normal', 't_distribution', or 'cornish_fisher'")
        return {'var': var, 'confidence_level': confidence_level, 'holding_period': holding_period, 'distribution': distribution, 'mean_return': np.mean(returns_array), 'volatility': np.std(returns_array, ddof=1), 'skewness': stats.skew(returns_array), 'kurtosis': stats.kurtosis(returns_array, fisher=False)}

    @staticmethod
    def monte_carlo_var(returns: np.ndarray, confidence_level: float=0.95, holding_period: int=1, num_simulations: int=10000, distribution_params: Optional[Dict]=None) -> Dict:
        """Calculate Monte Carlo VaR"""
        returns_array = np.array(returns)
        if distribution_params is None:
            mean_return = np.mean(returns_array)
            std_return = np.std(returns_array, ddof=1)
            distribution_params = {'mean': mean_return, 'std': std_return}
        np.random.seed(42)
        simulated_returns = np.random.normal(distribution_params['mean'], distribution_params['std'], (num_simulations, holding_period))
        if holding_period == 1:
            scenario_returns = simulated_returns.flatten()
        else:
            scenario_returns = np.prod(1 + simulated_returns, axis=1) - 1
        var = -np.percentile(scenario_returns, (1 - confidence_level) * 100)
        return {'var': var, 'confidence_level': confidence_level, 'holding_period': holding_period, 'num_simulations': num_simulations, 'simulated_returns': scenario_returns, 'mean_simulated': np.mean(scenario_returns), 'std_simulated': np.std(scenario_returns)}

    @staticmethod
    def component_var(portfolio_returns: np.ndarray, asset_returns: np.ndarray, weights: np.ndarray, confidence_level: float=0.95) -> Dict:
        """Calculate component VaR contributions"""
        portfolio_var = RiskCalculations.value_at_risk_historical(portfolio_returns, confidence_level)
        marginal_vars = []
        component_vars = []
        for i in range(len(weights)):
            epsilon = 0.001
            perturbed_weights = weights.copy()
            perturbed_weights[i] += epsilon
            perturbed_weights = perturbed_weights / np.sum(perturbed_weights)
            perturbed_portfolio_returns = np.dot(asset_returns, perturbed_weights)
            perturbed_var = RiskCalculations.value_at_risk_historical(perturbed_portfolio_returns, confidence_level)
            marginal_var = (perturbed_var - portfolio_var) / epsilon
            marginal_vars.append(marginal_var)
            component_var = marginal_var * weights[i]
            component_vars.append(component_var)
        return {'portfolio_var': portfolio_var, 'marginal_vars': np.array(marginal_vars), 'component_vars': np.array(component_vars), 'component_percentages': np.array(component_vars) / np.sum(np.abs(component_vars)) * 100, 'diversification_benefit': portfolio_var - np.sum(component_vars)}

