def _assess_risk_capacity_willingness(self, profile: InvestorProfile) -> Dict:
    """Assess risk capacity vs willingness"""
    capacity_factors = {'time_horizon': min(10, profile.time_horizon) / 10 * 30, 'liquidity': (1 - profile.liquidity_needs) * 30, 'income_stability': 20, 'wealth_level': 20}
    capacity_score = sum(capacity_factors.values())
    willingness_score = {'conservative': 25, 'moderate': 50, 'aggressive': 85}.get(profile.risk_tolerance, 50)
    return {'risk_capacity_score': capacity_score, 'risk_willingness_score': willingness_score, 'overall_risk_tolerance': min(capacity_score, willingness_score), 'capacity_willingness_gap': abs(capacity_score - willingness_score), 'constraining_factor': 'Capacity' if capacity_score < willingness_score else 'Willingness'}

class ValueAddedMeasurement:
    """Measurement of value added by active management"""

    @staticmethod
    def calculate_value_added(portfolio_returns: np.ndarray, benchmark_returns: np.ndarray, portfolio_weights: Optional[np.ndarray]=None) -> Dict:
        """Calculate value added by active management"""
        if not validate_returns(portfolio_returns) or not validate_returns(benchmark_returns):
            raise ValueError(ERROR_MESSAGES['insufficient_data'])
        active_returns = np.array(portfolio_returns) - np.array(benchmark_returns)
        mean_active_return = np.mean(active_returns)
        tracking_error = np.std(active_returns, ddof=1)
        annualized_active_return = mean_active_return * MathConstants.TRADING_DAYS_YEAR
        annualized_tracking_error = tracking_error * MathConstants.SQRT_TRADING_DAYS
        information_ratio = mean_active_return / tracking_error if tracking_error > 0 else 0
        annualized_ir = information_ratio * MathConstants.SQRT_TRADING_DAYS
        hit_rate = np.sum(active_returns > 0) / len(active_returns)
        value_decomposition = ValueAddedMeasurement._decompose_value_added(portfolio_returns, benchmark_returns, portfolio_weights)
        return {'active_return_daily': mean_active_return, 'active_return_annualized': annualized_active_return, 'tracking_error_daily': tracking_error, 'tracking_error_annualized': annualized_tracking_error, 'information_ratio_daily': information_ratio, 'information_ratio_annualized': annualized_ir, 'hit_rate': hit_rate, 'value_added_decomposition': value_decomposition, 'statistical_significance': ValueAddedMeasurement._test_statistical_significance(active_returns)}

    @staticmethod
    def _decompose_value_added(portfolio_returns: np.ndarray, benchmark_returns: np.ndarray, portfolio_weights: Optional[np.ndarray]) -> Dict:
        """Decompose value added into sources"""
        total_active_return = np.mean(portfolio_returns) - np.mean(benchmark_returns)
        estimated_allocation_effect = total_active_return * 0.3
        estimated_selection_effect = total_active_return * 0.7
        return {'total_active_return': total_active_return * MathConstants.TRADING_DAYS_YEAR, 'estimated_allocation_effect': estimated_allocation_effect * MathConstants.TRADING_DAYS_YEAR, 'estimated_selection_effect': estimated_selection_effect * MathConstants.TRADING_DAYS_YEAR, 'interaction_effect': 0.0, 'note': 'Decomposition requires detailed holdings data for precision'}

    @staticmethod
    def _test_statistical_significance(active_returns: np.ndarray) -> Dict:
        """Test statistical significance of active returns"""
        mean_active = np.mean(active_returns)
        std_active = np.std(active_returns, ddof=1)
        n_periods = len(active_returns)
        t_statistic = mean_active / (std_active / np.sqrt(n_periods)) if std_active > 0 else 0
        critical_90 = 1.645
        critical_95 = 1.96
        critical_99 = 2.576
        significance_level = 'Not significant'
        if abs(t_statistic) > critical_99:
            significance_level = '99% significant'
        elif abs(t_statistic) > critical_95:
            significance_level = '95% significant'
        elif abs(t_statistic) > critical_90:
            significance_level = '90% significant'
        return {'t_statistic': t_statistic, 'significance_level': significance_level, 'is_significant_95': abs(t_statistic) > critical_95, 'sample_size': n_periods, 'standard_error': std_active / np.sqrt(n_periods)}

@staticmethod
def calculate_value_added(portfolio_returns: np.ndarray, benchmark_returns: np.ndarray, portfolio_weights: Optional[np.ndarray]=None) -> Dict:
    """Calculate value added by active management"""
    if not validate_returns(portfolio_returns) or not validate_returns(benchmark_returns):
        raise ValueError(ERROR_MESSAGES['insufficient_data'])
    active_returns = np.array(portfolio_returns) - np.array(benchmark_returns)
    mean_active_return = np.mean(active_returns)
    tracking_error = np.std(active_returns, ddof=1)
    annualized_active_return = mean_active_return * MathConstants.TRADING_DAYS_YEAR
    annualized_tracking_error = tracking_error * MathConstants.SQRT_TRADING_DAYS
    information_ratio = mean_active_return / tracking_error if tracking_error > 0 else 0
    annualized_ir = information_ratio * MathConstants.SQRT_TRADING_DAYS
    hit_rate = np.sum(active_returns > 0) / len(active_returns)
    value_decomposition = ValueAddedMeasurement._decompose_value_added(portfolio_returns, benchmark_returns, portfolio_weights)
    return {'active_return_daily': mean_active_return, 'active_return_annualized': annualized_active_return, 'tracking_error_daily': tracking_error, 'tracking_error_annualized': annualized_tracking_error, 'information_ratio_daily': information_ratio, 'information_ratio_annualized': annualized_ir, 'hit_rate': hit_rate, 'value_added_decomposition': value_decomposition, 'statistical_significance': ValueAddedMeasurement._test_statistical_significance(active_returns)}

@staticmethod
def _decompose_value_added(portfolio_returns: np.ndarray, benchmark_returns: np.ndarray, portfolio_weights: Optional[np.ndarray]) -> Dict:
    """Decompose value added into sources"""
    total_active_return = np.mean(portfolio_returns) - np.mean(benchmark_returns)
    estimated_allocation_effect = total_active_return * 0.3
    estimated_selection_effect = total_active_return * 0.7
    return {'total_active_return': total_active_return * MathConstants.TRADING_DAYS_YEAR, 'estimated_allocation_effect': estimated_allocation_effect * MathConstants.TRADING_DAYS_YEAR, 'estimated_selection_effect': estimated_selection_effect * MathConstants.TRADING_DAYS_YEAR, 'interaction_effect': 0.0, 'note': 'Decomposition requires detailed holdings data for precision'}

@staticmethod
def _test_statistical_significance(active_returns: np.ndarray) -> Dict:
    """Test statistical significance of active returns"""
    mean_active = np.mean(active_returns)
    std_active = np.std(active_returns, ddof=1)
    n_periods = len(active_returns)
    t_statistic = mean_active / (std_active / np.sqrt(n_periods)) if std_active > 0 else 0
    critical_90 = 1.645
    critical_95 = 1.96
    critical_99 = 2.576
    significance_level = 'Not significant'
    if abs(t_statistic) > critical_99:
        significance_level = '99% significant'
    elif abs(t_statistic) > critical_95:
        significance_level = '95% significant'
    elif abs(t_statistic) > critical_90:
        significance_level = '90% significant'
    return {'t_statistic': t_statistic, 'significance_level': significance_level, 'is_significant_95': abs(t_statistic) > critical_95, 'sample_size': n_periods, 'standard_error': std_active / np.sqrt(n_periods)}

class InformationRatioAnalysis:
    """Information ratio calculation and analysis"""

    @staticmethod
    def calculate_information_ratio_ex_post(portfolio_returns: np.ndarray, benchmark_returns: np.ndarray) -> Dict:
        """Calculate ex-post (realized) information ratio"""
        active_returns = np.array(portfolio_returns) - np.array(benchmark_returns)
        mean_active_return = np.mean(active_returns)
        tracking_error = np.std(active_returns, ddof=1)
        ir_daily = mean_active_return / tracking_error if tracking_error > 0 else 0
        ir_annualized = ir_daily * MathConstants.SQRT_TRADING_DAYS
        portfolio_sharpe = PerformanceCalculations.sharpe_ratio(portfolio_returns)
        benchmark_sharpe = PerformanceCalculations.sharpe_ratio(benchmark_returns)
        return {'information_ratio_daily': ir_daily, 'information_ratio_annualized': ir_annualized, 'active_return_annualized': mean_active_return * MathConstants.TRADING_DAYS_YEAR, 'tracking_error_annualized': tracking_error * MathConstants.SQRT_TRADING_DAYS, 'portfolio_sharpe_ratio': portfolio_sharpe, 'benchmark_sharpe_ratio': benchmark_sharpe, 'sharpe_ratio_difference': portfolio_sharpe - benchmark_sharpe, 'ir_quality_assessment': InformationRatioAnalysis._assess_ir_quality(ir_annualized)}

    @staticmethod
    def calculate_information_ratio_ex_ante(expected_active_return: float, expected_tracking_error: float, forecast_horizon_months: int=12) -> Dict:
        """Calculate ex-ante (expected) information ratio"""
        time_factor = np.sqrt(forecast_horizon_months / 12)
        ex_ante_ir = expected_active_return / expected_tracking_error if expected_tracking_error > 0 else 0
        confidence_intervals = InformationRatioAnalysis._calculate_ir_confidence_intervals(ex_ante_ir, forecast_horizon_months)
        return {'ex_ante_information_ratio': ex_ante_ir, 'expected_active_return': expected_active_return, 'expected_tracking_error': expected_tracking_error, 'forecast_horizon_months': forecast_horizon_months, 'confidence_intervals': confidence_intervals, 'probability_of_positive_alpha': InformationRatioAnalysis._probability_positive_alpha(expected_active_return, expected_tracking_error)}

    @staticmethod
    def compare_ir_to_sharpe(information_ratio: float, portfolio_sharpe: float, benchmark_sharpe: float) -> Dict:
        """Compare Information Ratio to Sharpe ratios"""
        analysis = {'information_ratio': information_ratio, 'portfolio_sharpe': portfolio_sharpe, 'benchmark_sharpe': benchmark_sharpe, 'interpretation': {'ir_focus': 'Measures excess return per unit of active risk', 'sharpe_focus': 'Measures excess return per unit of total risk', 'complementary_nature': 'Both metrics provide different insights into performance'}}
        if information_ratio > 0.5:
            analysis['ir_assessment'] = 'Excellent active management'
        elif information_ratio > 0.25:
            analysis['ir_assessment'] = 'Good active management'
        elif information_ratio > 0:
            analysis['ir_assessment'] = 'Modest active management value'
        else:
            analysis['ir_assessment'] = 'Value-destroying active management'
        return analysis

    @staticmethod
    def _assess_ir_quality(ir_annualized: float) -> Dict:
        """Assess quality of information ratio"""
        if ir_annualized > 0.75:
            quality = 'Exceptional'
            percentile = 'Top 5%'
        elif ir_annualized > 0.5:
            quality = 'Excellent'
            percentile = 'Top 10%'
        elif ir_annualized > 0.25:
            quality = 'Good'
            percentile = 'Top 25%'
        elif ir_annualized > 0:
            quality = 'Below average'
            percentile = 'Below median'
        else:
            quality = 'Poor'
            percentile = 'Bottom quartile'
        return {'quality_rating': quality, 'industry_percentile': percentile, 'sustainability_concern': ir_annualized > 1.0}

    @staticmethod
    def _calculate_ir_confidence_intervals(ir: float, horizon_months: int) -> Dict:
        """Calculate confidence intervals for information ratio"""
        n_observations = horizon_months * 21
        ir_standard_error = np.sqrt((1 + ir ** 2 / 2) / n_observations)
        margin_of_error = 1.96 * ir_standard_error
        return {'95_percent_confidence_interval': {'lower_bound': ir - margin_of_error, 'upper_bound': ir + margin_of_error}, 'standard_error': ir_standard_error, 'sample_size_effect': 'Longer track records provide more reliable IR estimates'}

    @staticmethod
    def _probability_positive_alpha(expected_return: float, tracking_error: float) -> float:
        """Calculate probability of generating positive alpha"""
        if tracking_error <= 0:
            return 0.5
        from scipy import stats
        z_score = expected_return / tracking_error
        probability = stats.norm.cdf(z_score)
        return probability

