class FundamentalLawActiveManagement:
    """Fundamental Law of Active Management implementation"""

    @staticmethod
    def calculate_fundamental_law_components(portfolio_data: Dict) -> Dict:
        """Calculate components of the Fundamental Law of Active Management"""
        information_coefficient = portfolio_data.get('information_coefficient', 0.05)
        breadth = portfolio_data.get('breadth', 100)
        transfer_coefficient = portfolio_data.get('transfer_coefficient', 0.8)
        active_risk = portfolio_data.get('active_risk', 0.04)
        fundamental_law_ir = information_coefficient * np.sqrt(breadth) * transfer_coefficient
        expected_active_return = fundamental_law_ir * active_risk
        return {'information_coefficient': information_coefficient, 'breadth': breadth, 'transfer_coefficient': transfer_coefficient, 'active_risk': active_risk, 'fundamental_law_ir': fundamental_law_ir, 'expected_active_return': expected_active_return, 'component_analysis': FundamentalLawActiveManagement._analyze_components(information_coefficient, breadth, transfer_coefficient)}

    @staticmethod
    def analyze_strategy_changes(current_strategy: Dict, proposed_strategy: Dict) -> Dict:
        """Analyze strategy changes in terms of Fundamental Law"""
        current_ic = current_strategy.get('information_coefficient', 0.05)
        current_breadth = current_strategy.get('breadth', 100)
        current_tc = current_strategy.get('transfer_coefficient', 0.8)
        current_ir = current_ic * np.sqrt(current_breadth) * current_tc
        proposed_ic = proposed_strategy.get('information_coefficient', 0.05)
        proposed_breadth = proposed_strategy.get('breadth', 100)
        proposed_tc = proposed_strategy.get('transfer_coefficient', 0.8)
        proposed_ir = proposed_ic * np.sqrt(proposed_breadth) * proposed_tc
        ir_change = proposed_ir - current_ir
        ir_change_pct = ir_change / current_ir * 100 if current_ir != 0 else 0
        component_contributions = FundamentalLawActiveManagement._decompose_ir_change(current_strategy, proposed_strategy)
        return {'current_strategy_ir': current_ir, 'proposed_strategy_ir': proposed_ir, 'ir_change': ir_change, 'ir_change_percentage': ir_change_pct, 'component_contributions': component_contributions, 'recommendation': FundamentalLawActiveManagement._generate_strategy_recommendation(ir_change, component_contributions)}

    @staticmethod
    def market_timing_vs_security_selection(market_timing_data: Dict, security_selection_data: Dict) -> Dict:
        """Compare market timing vs security selection strategies"""
        mt_ic = market_timing_data.get('information_coefficient', 0.1)
        mt_breadth = market_timing_data.get('breadth', 12)
        mt_tc = market_timing_data.get('transfer_coefficient', 0.9)
        mt_ir = mt_ic * np.sqrt(mt_breadth) * mt_tc
        ss_ic = security_selection_data.get('information_coefficient', 0.03)
        ss_breadth = security_selection_data.get('breadth', 500)
        ss_tc = security_selection_data.get('transfer_coefficient', 0.7)
        ss_ir = ss_ic * np.sqrt(ss_breadth) * ss_tc
        comparison = {'market_timing': {'information_coefficient': mt_ic, 'breadth': mt_breadth, 'transfer_coefficient': mt_tc, 'information_ratio': mt_ir, 'characteristics': 'High skill, low breadth, high implementation efficiency'}, 'security_selection': {'information_coefficient': ss_ic, 'breadth': ss_breadth, 'transfer_coefficient': ss_tc, 'information_ratio': ss_ir, 'characteristics': 'Moderate skill, high breadth, good implementation'}, 'comparison_insights': {'higher_ir_strategy': 'Market Timing' if mt_ir > ss_ir else 'Security Selection', 'breadth_vs_skill_tradeoff': 'Market timing requires higher skill but offers lower breadth', 'implementation_challenges': FundamentalLawActiveManagement._compare_implementation_challenges()}}
        return comparison

    @staticmethod
    def _analyze_components(ic: float, breadth: float, tc: float) -> Dict:
        """Analyze individual components of the Fundamental Law"""
        return {'information_coefficient_analysis': {'value': ic, 'interpretation': 'High' if ic > 0.1 else 'Moderate' if ic > 0.05 else 'Low', 'improvement_potential': 'Skill development, better research, improved models', 'typical_range': '0.02 to 0.15 for most active managers'}, 'breadth_analysis': {'value': breadth, 'interpretation': 'High' if breadth > 200 else 'Moderate' if breadth > 50 else 'Low', 'improvement_potential': 'Expand universe, increase decision frequency', 'trade_offs': 'More breadth may reduce IC if skill is diluted'}, 'transfer_coefficient_analysis': {'value': tc, 'interpretation': 'High' if tc > 0.8 else 'Moderate' if tc > 0.6 else 'Low', 'improvement_potential': 'Reduce constraints, improve implementation', 'constraints_impact': 'Benchmarking, risk limits, liquidity affect TC'}}

    @staticmethod
    def _decompose_ir_change(current: Dict, proposed: Dict) -> Dict:
        """Decompose change in IR into component contributions"""
        current_ic = current.get('information_coefficient', 0.05)
        current_breadth = current.get('breadth', 100)
        current_tc = current.get('transfer_coefficient', 0.8)
        proposed_ic = proposed.get('information_coefficient', 0.05)
        proposed_breadth = proposed.get('breadth', 100)
        proposed_tc = proposed.get('transfer_coefficient', 0.8)
        ic_contribution = (proposed_ic - current_ic) * np.sqrt(current_breadth) * current_tc
        breadth_contribution = current_ic * (np.sqrt(proposed_breadth) - np.sqrt(current_breadth)) * current_tc
        tc_contribution = current_ic * np.sqrt(current_breadth) * (proposed_tc - current_tc)
        return {'ic_contribution': ic_contribution, 'breadth_contribution': breadth_contribution, 'tc_contribution': tc_contribution, 'total_change': ic_contribution + breadth_contribution + tc_contribution, 'largest_contributor': max([('IC', ic_contribution), ('Breadth', breadth_contribution), ('TC', tc_contribution)], key=lambda x: abs(x[1]))[0]}

@staticmethod
def _decompose_ir_change(current: Dict, proposed: Dict) -> Dict:
    """Decompose change in IR into component contributions"""
    current_ic = current.get('information_coefficient', 0.05)
    current_breadth = current.get('breadth', 100)
    current_tc = current.get('transfer_coefficient', 0.8)
    proposed_ic = proposed.get('information_coefficient', 0.05)
    proposed_breadth = proposed.get('breadth', 100)
    proposed_tc = proposed.get('transfer_coefficient', 0.8)
    ic_contribution = (proposed_ic - current_ic) * np.sqrt(current_breadth) * current_tc
    breadth_contribution = current_ic * (np.sqrt(proposed_breadth) - np.sqrt(current_breadth)) * current_tc
    tc_contribution = current_ic * np.sqrt(current_breadth) * (proposed_tc - current_tc)
    return {'ic_contribution': ic_contribution, 'breadth_contribution': breadth_contribution, 'tc_contribution': tc_contribution, 'total_change': ic_contribution + breadth_contribution + tc_contribution, 'largest_contributor': max([('IC', ic_contribution), ('Breadth', breadth_contribution), ('TC', tc_contribution)], key=lambda x: abs(x[1]))[0]}

class MultifactorModels:
    """Multifactor models implementation and analysis"""

    @staticmethod
    def arbitrage_pricing_theory_analysis() -> Dict:
        """Analyze Arbitrage Pricing Theory and its assumptions"""
        return {'apt_assumptions': {'factor_model': 'Returns generated by linear factor model', 'diversification': 'Unsystematic risk can be diversified away', 'no_arbitrage': 'No arbitrage opportunities exist in equilibrium', 'competitive_markets': 'Markets are competitive with rational investors'}, 'apt_equation': {'mathematical_form': 'E(Ri) = λ0 + λ1*βi1 + λ2*βi2 + ... + λk*βik', 'components': {'E(Ri)': 'Expected return on asset i', 'λ0': 'Risk-free rate or factor risk premium for λ0', 'λj': 'Risk premium for factor j', 'βij': 'Sensitivity of asset i to factor j'}}, 'relationship_to_multifactor_models': {'apt_foundation': 'APT provides theoretical foundation for multifactor models', 'practical_implementation': 'Multifactor models are practical implementations of APT', 'factor_identification': "APT doesn't specify factors; models must identify relevant factors"}, 'advantages': ['More general than CAPM', 'Allows for multiple risk factors', 'No specific utility function required', 'Fewer restrictive assumptions than CAPM'], 'limitations': ["Doesn't specify which factors to use", 'Factor risk premiums must be estimated', 'Requires large portfolios for diversification assumption', 'Testing APT is challenging empirically']}

    @staticmethod
    def identify_arbitrage_opportunity(expected_returns: np.ndarray, factor_loadings: np.ndarray, factor_risk_premiums: np.ndarray, risk_free_rate: float=0.03) -> Dict:
        """Identify arbitrage opportunities using APT"""
        apt_expected_returns = risk_free_rate + np.dot(factor_loadings, factor_risk_premiums)
        return_differences = expected_returns - apt_expected_returns
        arbitrage_opportunities = []
        for i, diff in enumerate(return_differences):
            if abs(diff) > 0.005:
                arbitrage_opportunities.append({'asset_index': i, 'expected_return': expected_returns[i], 'apt_fair_value': apt_expected_returns[i], 'difference': diff, 'direction': 'Overvalued' if diff < 0 else 'Undervalued', 'arbitrage_potential': abs(diff)})
        return {'arbitrage_opportunities': arbitrage_opportunities, 'number_of_opportunities': len(arbitrage_opportunities), 'largest_opportunity': max(arbitrage_opportunities, key=lambda x: x['arbitrage_potential']) if arbitrage_opportunities else None, 'market_efficiency_assessment': MultifactorModels._assess_market_efficiency(return_differences)}

    @staticmethod
    def calculate_expected_return_multifactor(factor_sensitivities: np.ndarray, factor_risk_premiums: np.ndarray, risk_free_rate: float=0.03) -> Dict:
        """Calculate expected return using multifactor model"""
        factor_contributions = factor_sensitivities * factor_risk_premiums
        total_risk_premium = np.sum(factor_contributions)
        expected_return = risk_free_rate + total_risk_premium
        return {'expected_return': expected_return, 'risk_free_rate': risk_free_rate, 'total_risk_premium': total_risk_premium, 'factor_contributions': {f'factor_{i + 1}': {'sensitivity': factor_sensitivities[i], 'risk_premium': factor_risk_premiums[i], 'contribution': factor_contributions[i]} for i in range(len(factor_sensitivities))}, 'decomposition_analysis': MultifactorModels._analyze_return_decomposition(factor_contributions, total_risk_premium)}

