class StrategyCombination:
    """Analysis of combining active management strategies"""

    @staticmethod
    def analyze_strategy_combination(strategy1_data: Dict, strategy2_data: Dict, correlation: float=0.3) -> Dict:
        """Analyze combination of two active management strategies"""
        s1_return = strategy1_data.get('expected_return', 0.02)
        s1_risk = strategy1_data.get('tracking_error', 0.04)
        s1_ir = s1_return / s1_risk if s1_risk > 0 else 0
        s2_return = strategy2_data.get('expected_return', 0.015)
        s2_risk = strategy2_data.get('tracking_error', 0.03)
        s2_ir = s2_return / s2_risk if s2_risk > 0 else 0
        weight1 = 0.5
        weight2 = 0.5
        combined_return = weight1 * s1_return + weight2 * s2_return
        combined_variance = (weight1 * s1_risk) ** 2 + (weight2 * s2_risk) ** 2 + 2 * weight1 * weight2 * correlation * s1_risk * s2_risk
        combined_risk = np.sqrt(combined_variance)
        combined_ir = combined_return / combined_risk if combined_risk > 0 else 0
        optimal_weights = StrategyCombination._calculate_optimal_weights(s1_return, s1_risk, s2_return, s2_risk, correlation)
        return {'individual_strategies': {'strategy1': {'return': s1_return, 'risk': s1_risk, 'ir': s1_ir}, 'strategy2': {'return': s2_return, 'risk': s2_risk, 'ir': s2_ir}}, 'equal_weight_combination': {'weights': [weight1, weight2], 'expected_return': combined_return, 'tracking_error': combined_risk, 'information_ratio': combined_ir}, 'optimal_combination': optimal_weights, 'correlation_impact': StrategyCombination._analyze_correlation_impact(s1_risk, s2_risk, correlation), 'diversification_benefit': StrategyCombination._calculate_diversification_benefit(s1_risk, s2_risk, combined_risk, weight1, weight2)}

    @staticmethod
    def _calculate_optimal_weights(return1: float, risk1: float, return2: float, risk2: float, correlation: float) -> Dict:
        """Calculate optimal weights for maximum Information Ratio"""
        cov_matrix = np.array([[risk1 ** 2, correlation * risk1 * risk2], [correlation * risk1 * risk2, risk2 ** 2]])
        returns = np.array([return1, return2])
        try:
            inv_cov = np.linalg.inv(cov_matrix)
            optimal_weights = np.dot(inv_cov, returns)
            optimal_weights = optimal_weights / np.sum(optimal_weights)
            opt_return = np.dot(optimal_weights, returns)
            opt_variance = np.dot(optimal_weights, np.dot(cov_matrix, optimal_weights))
            opt_risk = np.sqrt(opt_variance)
            opt_ir = opt_return / opt_risk if opt_risk > 0 else 0
            return {'optimal_weights': optimal_weights.tolist(), 'optimal_return': opt_return, 'optimal_risk': opt_risk, 'optimal_ir': opt_ir, 'improvement_vs_equal_weight': opt_ir - (opt_return / opt_risk if opt_risk > 0 else 0)}
        except np.linalg.LinAlgError:
            return {'optimal_weights': [0.5, 0.5], 'note': 'Singular covariance matrix - using equal weights'}

    @staticmethod
    def _analyze_correlation_impact(risk1: float, risk2: float, correlation: float) -> Dict:
        """Analyze impact of correlation on strategy combination"""
        scenarios = {}
        for corr in [-0.5, 0.0, 0.5, 1.0]:
            combined_variance = 0.25 * risk1 ** 2 + 0.25 * risk2 ** 2 + 2 * 0.5 * 0.5 * corr * risk1 * risk2
            combined_risk = np.sqrt(combined_variance)
            scenarios[f'correlation_{corr}'] = combined_risk
        return {'correlation_scenarios': scenarios, 'current_correlation': correlation, 'risk_reduction_potential': scenarios['correlation_-0.5'] - scenarios['correlation_1.0'], 'diversification_effectiveness': 'High' if correlation < 0.3 else 'Moderate' if correlation < 0.7 else 'Low'}

