def calculate_maximum_drawdown(self, price_series: pd.Series) -> float:
    """Calculate maximum drawdown"""
    cumulative = (1 + price_series.pct_change()).cumprod()
    running_max = cumulative.expanding().max()
    drawdown = (cumulative - running_max) / running_max
    return drawdown.min()

def compare_indexes(self, index_data_dict: Dict[str, pd.DataFrame]) -> Dict[str, Any]:
    """Compare multiple indexes"""
    comparison_results = {}
    for index_name, data in index_data_dict.items():
        analysis = self.comprehensive_index_analysis(data)
        comparison_results[index_name] = analysis['performance_summary']
    metrics = ['total_return', 'annualized_return', 'volatility', 'sharpe_ratio', 'max_drawdown']
    comparison_matrix = pd.DataFrame({metric: {name: results[metric] for name, results in comparison_results.items()} for metric in metrics}).T
    rankings = {}
    for metric in metrics:
        ascending = metric in ['volatility', 'max_drawdown']
        rankings[metric] = comparison_matrix.loc[metric].rank(ascending=ascending)
    return {'individual_analysis': comparison_results, 'comparison_matrix': comparison_matrix.to_dict(), 'rankings': rankings}

class SpecializedIndexes:
    """Implementation of specialized index types"""

    @staticmethod
    def create_equity_index(constituents: List[IndexConstituent], weighting_method: IndexWeightingMethod=IndexWeightingMethod.MARKET_CAP_WEIGHTED, name: str='Custom Equity Index') -> IndexConstructor:
        """Create equity index"""
        index = IndexConstructor(name, weighting_method)
        for constituent in constituents:
            index.add_constituent(constituent)
        return index

    @staticmethod
    def create_fixed_income_index(bond_data: List[Dict[str, Any]], name: str='Custom Bond Index') -> Dict[str, Any]:
        """Create fixed income index (simplified)"""
        total_market_value = sum((bond['market_value'] for bond in bond_data))
        weighted_yield = sum((bond['market_value'] / total_market_value * bond['yield'] for bond in bond_data))
        weighted_duration = sum((bond['market_value'] / total_market_value * bond['duration'] for bond in bond_data))
        weighted_credit_quality = sum((bond['market_value'] / total_market_value * bond.get('credit_score', 0) for bond in bond_data))
        return {'name': name, 'total_market_value': total_market_value, 'weighted_yield': weighted_yield, 'weighted_duration': weighted_duration, 'weighted_credit_quality': weighted_credit_quality, 'number_of_bonds': len(bond_data)}

    @staticmethod
    def create_commodity_index(commodity_data: List[Dict[str, Any]], name: str='Custom Commodity Index') -> Dict[str, Any]:
        """Create commodity index"""
        total_weight = sum((commodity['weight'] for commodity in commodity_data))
        for commodity in commodity_data:
            commodity['normalized_weight'] = commodity['weight'] / total_weight
        index_value = sum((commodity['normalized_weight'] * commodity['price_index'] for commodity in commodity_data))
        return {'name': name, 'index_value': index_value, 'constituents': commodity_data, 'sectors': list(set((c.get('sector', 'Unknown') for c in commodity_data)))}

