class WeakFormEfficiencyTester:
    """Tests for weak-form market efficiency"""

    def __init__(self, significance_level: float=0.05):
        self.significance_level = significance_level

    def runs_test(self, returns: pd.Series) -> EfficiencyTestResult:
        """Runs test for randomness in return series"""
        median_return = returns.median()
        binary_sequence = (returns > median_return).astype(int)
        runs = 1
        for i in range(1, len(binary_sequence)):
            if binary_sequence.iloc[i] != binary_sequence.iloc[i - 1]:
                runs += 1
        n1 = sum(binary_sequence)
        n2 = len(binary_sequence) - n1
        n = len(binary_sequence)
        expected_runs = 2 * n1 * n2 / n + 1
        variance_runs = 2 * n1 * n2 * (2 * n1 * n2 - n) / (n ** 2 * (n - 1))
        if variance_runs > 0:
            z_stat = (runs - expected_runs) / np.sqrt(variance_runs)
            p_value = 2 * (1 - stats.norm.cdf(abs(z_stat)))
        else:
            z_stat = 0
            p_value = 1
        is_efficient = p_value > self.significance_level
        return EfficiencyTestResult(test_name='Runs Test', efficiency_form=MarketEfficiencyForm.WEAK, test_statistic=z_stat, p_value=p_value, is_efficient=is_efficient, confidence_level=1 - self.significance_level, interpretation=f'Returns appear {('random' if is_efficient else 'non-random')} (p-value: {p_value:.4f})')

    def autocorrelation_test(self, returns: pd.Series, lags: List[int]=None) -> Dict[str, EfficiencyTestResult]:
        """Test for autocorrelation in returns at various lags"""
        if lags is None:
            lags = [1, 5, 10, 20]
        results = {}
        for lag in lags:
            if len(returns) <= lag:
                continue
            autocorr = returns.autocorr(lag=lag)
            n = len(returns)
            test_stat = n * autocorr ** 2
            p_value = 1 - stats.chi2.cdf(test_stat, df=1)
            is_efficient = p_value > self.significance_level
            results[f'lag_{lag}'] = EfficiencyTestResult(test_name=f'Autocorrelation Test (Lag {lag})', efficiency_form=MarketEfficiencyForm.WEAK, test_statistic=autocorr, p_value=p_value, is_efficient=is_efficient, confidence_level=1 - self.significance_level, interpretation=f'Lag {lag} autocorrelation: {autocorr:.4f} ({('not significant' if is_efficient else 'significant')})')
        return results

    def variance_ratio_test(self, returns: pd.Series, periods: List[int]=None) -> Dict[str, EfficiencyTestResult]:
        """Variance ratio test for random walk"""
        if periods is None:
            periods = [2, 4, 8, 16]
        results = {}
        for k in periods:
            if len(returns) < k * 10:
                continue
            var_1 = returns.var()
            k_returns = returns.rolling(k).sum().dropna()
            var_k = k_returns.var()
            variance_ratio = var_k / (k * var_1)
            n = len(returns)
            test_stat = np.sqrt(n) * (variance_ratio - 1) / np.sqrt(2 * (k - 1))
            p_value = 2 * (1 - stats.norm.cdf(abs(test_stat)))
            is_efficient = p_value > self.significance_level
            results[f'period_{k}'] = EfficiencyTestResult(test_name=f'Variance Ratio Test (Period {k})', efficiency_form=MarketEfficiencyForm.WEAK, test_statistic=variance_ratio, p_value=p_value, is_efficient=is_efficient, confidence_level=1 - self.significance_level, interpretation=f'VR({k}) = {variance_ratio:.4f} ({('consistent with' if is_efficient else 'inconsistent with')} random walk)')
        return results

