def comprehensive_efficiency_analysis(price_data: pd.DataFrame, event_dates: List[str]=None, insider_transactions: List[Dict[str, Any]]=None) -> Dict[str, Any]:
    """Perform comprehensive market efficiency analysis"""
    weak_tester = WeakFormEfficiencyTester()
    semi_strong_tester = SemiStrongFormTester()
    strong_tester = StrongFormTester()
    anomaly_detector = MarketAnomalyDetector()
    returns = price_data['Close'].pct_change().dropna()
    results = {'data_summary': {'start_date': returns.index[0].strftime('%Y-%m-%d'), 'end_date': returns.index[-1].strftime('%Y-%m-%d'), 'total_observations': len(returns), 'mean_return': returns.mean(), 'volatility': returns.std(), 'skewness': returns.skew(), 'kurtosis': returns.kurtosis()}}
    results['weak_form'] = {'runs_test': weak_tester.runs_test(returns), 'autocorrelation_tests': weak_tester.autocorrelation_test(returns), 'variance_ratio_tests': weak_tester.variance_ratio_test(returns)}
    if event_dates:
        results['semi_strong'] = {'event_study': semi_strong_tester.event_study_analysis(price_data, event_dates)}
    if insider_transactions:
        results['strong_form'] = {'insider_trading': strong_tester.insider_trading_analysis(price_data, insider_transactions)}
    results['anomalies'] = {'calendar_anomalies': anomaly_detector.detect_calendar_anomalies(price_data), 'momentum_anomaly': anomaly_detector.detect_momentum_anomaly(price_data)}
    return results

class OrderAnalyzer:
    """Analyze trading orders and execution instructions"""

    def analyze_market_order(self, order: TradingOrder, current_bid: float, current_ask: float) -> Dict[str, Any]:
        """Analyze market order characteristics"""
        if order.position_type == PositionType.LONG:
            expected_execution_price = current_ask
            price_impact = 'Buy at ask price'
        else:
            expected_execution_price = current_bid
            price_impact = 'Sell at bid price'
        bid_ask_spread = current_ask - current_bid
        spread_percentage = bid_ask_spread / ((current_bid + current_ask) / 2) * 100
        return {'order_type': order.order_type.value, 'execution_certainty': 'High', 'price_certainty': 'Low', 'expected_execution_price': expected_execution_price, 'bid_ask_spread': bid_ask_spread, 'spread_percentage': spread_percentage, 'price_impact': price_impact, 'advantages': ['Immediate execution', 'High fill probability'], 'disadvantages': ['Price uncertainty', 'Market impact cost']}

    def analyze_limit_order(self, order: TradingOrder, current_price: float) -> Dict[str, Any]:
        """Analyze limit order characteristics"""
        if not order.price:
            raise ValidationError('Limit order requires price specification')
        if order.position_type == PositionType.LONG:
            executable = order.price >= current_price
            price_improvement = current_price - order.price if executable else 0
        else:
            executable = order.price <= current_price
            price_improvement = order.price - current_price if executable else 0
        return {'order_type': order.order_type.value, 'limit_price': order.price, 'current_market_price': current_price, 'immediately_executable': executable, 'price_improvement': price_improvement, 'execution_certainty': 'Medium', 'price_certainty': 'High', 'advantages': ['Price protection', 'Potential price improvement'], 'disadvantages': ['Execution uncertainty', 'Opportunity cost if not filled']}

    def analyze_stop_order(self, order: TradingOrder, current_price: float) -> Dict[str, Any]:
        """Analyze stop order characteristics"""
        if not order.stop_price:
            raise ValidationError('Stop order requires stop price specification')
        if order.position_type == PositionType.LONG:
            activated = current_price >= order.stop_price
            order_purpose = 'Momentum/Breakout buying'
        else:
            activated = current_price <= order.stop_price
            order_purpose = 'Loss limitation/Risk management'
        return {'order_type': order.order_type.value, 'stop_price': order.stop_price, 'current_price': current_price, 'activated': activated, 'order_purpose': order_purpose, 'execution_certainty': 'Medium' if activated else 'Low', 'price_certainty': 'Low', 'advantages': ['Risk management', 'No monitoring required'], 'disadvantages': ['Price uncertainty when executed', 'Possible gap risk']}

    def compare_order_types(self, current_bid: float, current_ask: float) -> pd.DataFrame:
        """Compare characteristics of different order types"""
        order_comparison = [{'order_type': 'Market Order', 'execution_certainty': 'High', 'price_certainty': 'Low', 'typical_use': 'Immediate execution needed', 'price_paid_received': f'Ask ({current_ask}) / Bid ({current_bid})'}, {'order_type': 'Limit Order', 'execution_certainty': 'Medium', 'price_certainty': 'High', 'typical_use': 'Price protection desired', 'price_paid_received': 'Limit price or better'}, {'order_type': 'Stop Order', 'execution_certainty': 'Medium', 'price_certainty': 'Low', 'typical_use': 'Risk management/Momentum', 'price_paid_received': 'Market price when triggered'}, {'order_type': 'Stop-Limit Order', 'execution_certainty': 'Low', 'price_certainty': 'High', 'typical_use': 'Risk management with price protection', 'price_paid_received': 'Limit price or better (if filled)'}]
        return pd.DataFrame(order_comparison)

def compare_order_types(self, current_bid: float, current_ask: float) -> pd.DataFrame:
    """Compare characteristics of different order types"""
    order_comparison = [{'order_type': 'Market Order', 'execution_certainty': 'High', 'price_certainty': 'Low', 'typical_use': 'Immediate execution needed', 'price_paid_received': f'Ask ({current_ask}) / Bid ({current_bid})'}, {'order_type': 'Limit Order', 'execution_certainty': 'Medium', 'price_certainty': 'High', 'typical_use': 'Price protection desired', 'price_paid_received': 'Limit price or better'}, {'order_type': 'Stop Order', 'execution_certainty': 'Medium', 'price_certainty': 'Low', 'typical_use': 'Risk management/Momentum', 'price_paid_received': 'Market price when triggered'}, {'order_type': 'Stop-Limit Order', 'execution_certainty': 'Low', 'price_certainty': 'High', 'typical_use': 'Risk management with price protection', 'price_paid_received': 'Limit price or better (if filled)'}]
    return pd.DataFrame(order_comparison)

class MarketStructureAnalyzer(BaseMarketAnalysisModel):
    """Analyze market structure and trading mechanisms"""

    def __init__(self):
        super().__init__('Market Structure Analyzer', 'Market organization and structure analysis')

    def validate_inputs(self, **kwargs) -> bool:
        """Validate inputs for market structure analysis"""
        return True

    def analyze_market_data(self, market_data: pd.DataFrame) -> Dict[str, Any]:
        """Analyze market structure characteristics"""
        return {'market_microstructure': self.analyze_market_microstructure(market_data), 'liquidity_analysis': self.analyze_market_liquidity(market_data), 'trading_costs': self.estimate_trading_costs(market_data), 'market_efficiency_indicators': self.calculate_efficiency_indicators(market_data)}

    def analyze_market_microstructure(self, market_data: pd.DataFrame) -> Dict[str, Any]:
        """Analyze market microstructure characteristics"""
        if 'Bid' not in market_data.columns or 'Ask' not in market_data.columns:
            return {'error': 'Bid and Ask data required for microstructure analysis'}
        spreads = market_data['Ask'] - market_data['Bid']
        relative_spreads = spreads / ((market_data['Bid'] + market_data['Ask']) / 2)
        if 'Volume' in market_data.columns:
            volume_stats = {'average_volume': market_data['Volume'].mean(), 'volume_volatility': market_data['Volume'].std(), 'high_volume_days': (market_data['Volume'] > market_data['Volume'].quantile(0.9)).sum()}
        else:
            volume_stats = {'error': 'Volume data not available'}
        return {'bid_ask_spreads': {'average_spread': spreads.mean(), 'average_relative_spread': relative_spreads.mean(), 'spread_volatility': spreads.std(), 'min_spread': spreads.min(), 'max_spread': spreads.max()}, 'volume_statistics': volume_stats, 'market_depth_indicators': self.analyze_market_depth(market_data)}

    def analyze_market_depth(self, market_data: pd.DataFrame) -> Dict[str, Any]:
        """Analyze market depth characteristics"""
        if 'Bid' in market_data.columns and 'Ask' in market_data.columns:
            spreads = market_data['Ask'] - market_data['Bid']
            depth_proxy = 1 / spreads.replace(0, np.nan)
            return {'average_depth_proxy': depth_proxy.mean(), 'depth_stability': 1 / depth_proxy.std() if depth_proxy.std() > 0 else float('inf'), 'thin_market_periods': (spreads > spreads.quantile(0.9)).sum(), 'market_quality': 'High' if spreads.mean() < 0.01 else 'Medium' if spreads.mean() < 0.05 else 'Low'}
        else:
            return {'error': 'Insufficient data for depth analysis'}

    def analyze_market_liquidity(self, market_data: pd.DataFrame) -> Dict[str, Any]:
        """Analyze market liquidity characteristics"""
        liquidity_measures = {}
        if 'Bid' in market_data.columns and 'Ask' in market_data.columns:
            spreads = market_data['Ask'] - market_data['Bid']
            mid_prices = (market_data['Bid'] + market_data['Ask']) / 2
            relative_spreads = spreads / mid_prices
            liquidity_measures['tightness'] = {'average_relative_spread': relative_spreads.mean(), 'spread_consistency': 1 / relative_spreads.std() if relative_spreads.std() > 0 else float('inf')}
        if 'Volume' in market_data.columns:
            liquidity_measures['depth'] = {'average_daily_volume': market_data['Volume'].mean(), 'volume_consistency': 1 / market_data['Volume'].std() * market_data['Volume'].mean() if market_data['Volume'].std() > 0 else float('inf')}
        if 'Close' in market_data.columns:
            returns = market_data['Close'].pct_change().dropna()
            liquidity_measures['resilience'] = {'return_volatility': returns.std(), 'price_resilience': 1 / returns.std() if returns.std() > 0 else float('inf')}
        liquidity_score = self.calculate_liquidity_score(liquidity_measures)
        return {'liquidity_measures': liquidity_measures, 'overall_liquidity_score': liquidity_score, 'liquidity_rating': self.rate_liquidity(liquidity_score)}

    def calculate_liquidity_score(self, liquidity_measures: Dict[str, Any]) -> float:
        """Calculate overall liquidity score"""
        score = 0
        factors = 0
        if 'tightness' in liquidity_measures:
            spread = liquidity_measures['tightness']['average_relative_spread']
            if spread > 0:
                tightness_score = max(0, 1 - spread * 100)
                score += tightness_score
                factors += 1
        if 'depth' in liquidity_measures:
            depth_score = 0.7
            score += depth_score
            factors += 1
        if 'resilience' in liquidity_measures:
            volatility = liquidity_measures['resilience']['return_volatility']
            if volatility > 0:
                resilience_score = max(0, 1 - volatility * 10)
                score += resilience_score
                factors += 1
        return score / factors if factors > 0 else 0

    def rate_liquidity(self, liquidity_score: float) -> str:
        """Rate liquidity based on score"""
        if liquidity_score >= 0.8:
            return 'High Liquidity'
        elif liquidity_score >= 0.6:
            return 'Medium Liquidity'
        elif liquidity_score >= 0.4:
            return 'Low Liquidity'
        else:
            return 'Very Low Liquidity'

    def estimate_trading_costs(self, market_data: pd.DataFrame) -> Dict[str, Any]:
        """Estimate trading costs"""
        trading_costs = {}
        if 'Bid' in market_data.columns and 'Ask' in market_data.columns:
            spreads = market_data['Ask'] - market_data['Bid']
            mid_prices = (market_data['Bid'] + market_data['Ask']) / 2
            spread_cost = spreads / mid_prices / 2
            trading_costs['bid_ask_cost'] = {'average_spread_cost': spread_cost.mean(), 'min_spread_cost': spread_cost.min(), 'max_spread_cost': spread_cost.max()}
        if 'Volume' in market_data.columns and 'Close' in market_data.columns:
            returns = market_data['Close'].pct_change().abs()
            volume = market_data['Volume']
            impact_proxy = returns / (volume / volume.mean())
            trading_costs['market_impact'] = {'average_impact_proxy': impact_proxy.mean(), 'impact_volatility': impact_proxy.std()}
        if 'bid_ask_cost' in trading_costs:
            estimated_total_cost = trading_costs['bid_ask_cost']['average_spread_cost']
            if 'market_impact' in trading_costs:
                estimated_total_cost += trading_costs['market_impact']['average_impact_proxy'] * 0.5
            trading_costs['estimated_total_cost'] = estimated_total_cost
        return trading_costs

    def calculate_efficiency_indicators(self, market_data: pd.DataFrame) -> Dict[str, Any]:
        """Calculate market efficiency indicators"""
        if 'Close' not in market_data.columns:
            return {'error': 'Price data required for efficiency analysis'}
        returns = market_data['Close'].pct_change().dropna()
        autocorrelation = returns.autocorr(lag=1)
        squared_returns = returns ** 2
        volatility_clustering = squared_returns.autocorr(lag=1)
        if len(returns) > 20:
            returns_2day = returns.rolling(2).sum().dropna()
            variance_ratio = returns_2day.var() / 2 / returns.var()
        else:
            variance_ratio = 1
        return {'return_autocorrelation': autocorrelation, 'volatility_clustering': volatility_clustering, 'variance_ratio': variance_ratio, 'efficiency_assessment': self.assess_efficiency(autocorrelation, variance_ratio)}

    def assess_efficiency(self, autocorr: float, variance_ratio: float) -> str:
        """Assess market efficiency based on indicators"""
        if abs(autocorr) < 0.05 and abs(variance_ratio - 1) < 0.1:
            return 'Highly Efficient'
        elif abs(autocorr) < 0.1 and abs(variance_ratio - 1) < 0.2:
            return 'Moderately Efficient'
        else:
            return 'Less Efficient'

def analyze_market_microstructure(self, market_data: pd.DataFrame) -> Dict[str, Any]:
    """Analyze market microstructure characteristics"""
    if 'Bid' not in market_data.columns or 'Ask' not in market_data.columns:
        return {'error': 'Bid and Ask data required for microstructure analysis'}
    spreads = market_data['Ask'] - market_data['Bid']
    relative_spreads = spreads / ((market_data['Bid'] + market_data['Ask']) / 2)
    if 'Volume' in market_data.columns:
        volume_stats = {'average_volume': market_data['Volume'].mean(), 'volume_volatility': market_data['Volume'].std(), 'high_volume_days': (market_data['Volume'] > market_data['Volume'].quantile(0.9)).sum()}
    else:
        volume_stats = {'error': 'Volume data not available'}
    return {'bid_ask_spreads': {'average_spread': spreads.mean(), 'average_relative_spread': relative_spreads.mean(), 'spread_volatility': spreads.std(), 'min_spread': spreads.min(), 'max_spread': spreads.max()}, 'volume_statistics': volume_stats, 'market_depth_indicators': self.analyze_market_depth(market_data)}

def analyze_market_depth(self, market_data: pd.DataFrame) -> Dict[str, Any]:
    """Analyze market depth characteristics"""
    if 'Bid' in market_data.columns and 'Ask' in market_data.columns:
        spreads = market_data['Ask'] - market_data['Bid']
        depth_proxy = 1 / spreads.replace(0, np.nan)
        return {'average_depth_proxy': depth_proxy.mean(), 'depth_stability': 1 / depth_proxy.std() if depth_proxy.std() > 0 else float('inf'), 'thin_market_periods': (spreads > spreads.quantile(0.9)).sum(), 'market_quality': 'High' if spreads.mean() < 0.01 else 'Medium' if spreads.mean() < 0.05 else 'Low'}
    else:
        return {'error': 'Insufficient data for depth analysis'}

def analyze_market_liquidity(self, market_data: pd.DataFrame) -> Dict[str, Any]:
    """Analyze market liquidity characteristics"""
    liquidity_measures = {}
    if 'Bid' in market_data.columns and 'Ask' in market_data.columns:
        spreads = market_data['Ask'] - market_data['Bid']
        mid_prices = (market_data['Bid'] + market_data['Ask']) / 2
        relative_spreads = spreads / mid_prices
        liquidity_measures['tightness'] = {'average_relative_spread': relative_spreads.mean(), 'spread_consistency': 1 / relative_spreads.std() if relative_spreads.std() > 0 else float('inf')}
    if 'Volume' in market_data.columns:
        liquidity_measures['depth'] = {'average_daily_volume': market_data['Volume'].mean(), 'volume_consistency': 1 / market_data['Volume'].std() * market_data['Volume'].mean() if market_data['Volume'].std() > 0 else float('inf')}
    if 'Close' in market_data.columns:
        returns = market_data['Close'].pct_change().dropna()
        liquidity_measures['resilience'] = {'return_volatility': returns.std(), 'price_resilience': 1 / returns.std() if returns.std() > 0 else float('inf')}
    liquidity_score = self.calculate_liquidity_score(liquidity_measures)
    return {'liquidity_measures': liquidity_measures, 'overall_liquidity_score': liquidity_score, 'liquidity_rating': self.rate_liquidity(liquidity_score)}

def estimate_trading_costs(self, market_data: pd.DataFrame) -> Dict[str, Any]:
    """Estimate trading costs"""
    trading_costs = {}
    if 'Bid' in market_data.columns and 'Ask' in market_data.columns:
        spreads = market_data['Ask'] - market_data['Bid']
        mid_prices = (market_data['Bid'] + market_data['Ask']) / 2
        spread_cost = spreads / mid_prices / 2
        trading_costs['bid_ask_cost'] = {'average_spread_cost': spread_cost.mean(), 'min_spread_cost': spread_cost.min(), 'max_spread_cost': spread_cost.max()}
    if 'Volume' in market_data.columns and 'Close' in market_data.columns:
        returns = market_data['Close'].pct_change().abs()
        volume = market_data['Volume']
        impact_proxy = returns / (volume / volume.mean())
        trading_costs['market_impact'] = {'average_impact_proxy': impact_proxy.mean(), 'impact_volatility': impact_proxy.std()}
    if 'bid_ask_cost' in trading_costs:
        estimated_total_cost = trading_costs['bid_ask_cost']['average_spread_cost']
        if 'market_impact' in trading_costs:
            estimated_total_cost += trading_costs['market_impact']['average_impact_proxy'] * 0.5
        trading_costs['estimated_total_cost'] = estimated_total_cost
    return trading_costs

def calculate_efficiency_indicators(self, market_data: pd.DataFrame) -> Dict[str, Any]:
    """Calculate market efficiency indicators"""
    if 'Close' not in market_data.columns:
        return {'error': 'Price data required for efficiency analysis'}
    returns = market_data['Close'].pct_change().dropna()
    autocorrelation = returns.autocorr(lag=1)
    squared_returns = returns ** 2
    volatility_clustering = squared_returns.autocorr(lag=1)
    if len(returns) > 20:
        returns_2day = returns.rolling(2).sum().dropna()
        variance_ratio = returns_2day.var() / 2 / returns.var()
    else:
        variance_ratio = 1
    return {'return_autocorrelation': autocorrelation, 'volatility_clustering': volatility_clustering, 'variance_ratio': variance_ratio, 'efficiency_assessment': self.assess_efficiency(autocorrelation, variance_ratio)}

def assess_efficiency(self, autocorr: float, variance_ratio: float) -> str:
    """Assess market efficiency based on indicators"""
    if abs(autocorr) < 0.05 and abs(variance_ratio - 1) < 0.1:
        return 'Highly Efficient'
    elif abs(autocorr) < 0.1 and abs(variance_ratio - 1) < 0.2:
        return 'Moderately Efficient'
    else:
        return 'Less Efficient'

class PortersFiveForcesAnalyzer:
    """Porter's Five Forces analysis framework"""

    def analyze_five_forces(self, company_data: CompanyData) -> PortersFiveForcesAnalysis:
        """Perform comprehensive Porter's Five Forces analysis"""
        sector = company_data.sector
        threat_new_entrants = self.analyze_threat_of_new_entrants(sector)
        supplier_power = self.analyze_supplier_power(sector)
        buyer_power = self.analyze_buyer_power(sector)
        threat_substitutes = self.analyze_threat_of_substitutes(sector)
        competitive_rivalry = self.analyze_competitive_rivalry(sector)
        forces_scores = [threat_new_entrants['threat_level_score'], supplier_power['power_level_score'], buyer_power['power_level_score'], threat_substitutes['threat_level_score'], competitive_rivalry['intensity_score']]
        avg_score = np.mean(forces_scores)
        if avg_score <= 2:
            attractiveness = 'Highly Attractive'
        elif avg_score <= 3:
            attractiveness = 'Moderately Attractive'
        elif avg_score <= 4:
            attractiveness = 'Average Attractiveness'
        else:
            attractiveness = 'Unattractive'
        return PortersFiveForcesAnalysis(threat_of_new_entrants=threat_new_entrants, bargaining_power_suppliers=supplier_power, bargaining_power_buyers=buyer_power, threat_of_substitutes=threat_substitutes, competitive_rivalry=competitive_rivalry, overall_attractiveness=attractiveness)

    def analyze_threat_of_new_entrants(self, sector: str) -> Dict[str, Any]:
        """Analyze threat of new entrants"""
        entry_barriers = {'Information Technology': {'capital_requirements': 3, 'technology_complexity': 4, 'regulatory_requirements': 2, 'brand_loyalty': 3, 'network_effects': 4, 'access_to_distribution': 3}, 'Health Care': {'capital_requirements': 5, 'technology_complexity': 5, 'regulatory_requirements': 5, 'brand_loyalty': 4, 'network_effects': 2, 'access_to_distribution': 4}, 'Utilities': {'capital_requirements': 5, 'technology_complexity': 3, 'regulatory_requirements': 5, 'brand_loyalty': 2, 'network_effects': 5, 'access_to_distribution': 5}}
        barriers = entry_barriers.get(sector, {'capital_requirements': 3, 'technology_complexity': 3, 'regulatory_requirements': 3, 'brand_loyalty': 3, 'network_effects': 3, 'access_to_distribution': 3})
        avg_barrier_strength = np.mean(list(barriers.values()))
        threat_level_score = 6 - avg_barrier_strength
        if threat_level_score <= 2:
            threat_level = 'Low'
        elif threat_level_score <= 3:
            threat_level = 'Medium'
        else:
            threat_level = 'High'
        return {'entry_barriers': barriers, 'threat_level': threat_level, 'threat_level_score': threat_level_score, 'key_barriers': [k for k, v in barriers.items() if v >= 4], 'analysis': f'Entry barriers are {('strong' if avg_barrier_strength >= 4 else 'moderate' if avg_barrier_strength >= 3 else 'weak')}'}

    def analyze_supplier_power(self, sector: str) -> Dict[str, Any]:
        """Analyze bargaining power of suppliers"""
        supplier_power_factors = {'Information Technology': {'supplier_concentration': 3, 'switching_costs': 3, 'input_importance': 4, 'substitute_inputs': 3, 'forward_integration_threat': 2}, 'Health Care': {'supplier_concentration': 4, 'switching_costs': 4, 'input_importance': 5, 'substitute_inputs': 2, 'forward_integration_threat': 2}, 'Automotive': {'supplier_concentration': 4, 'switching_costs': 4, 'input_importance': 4, 'substitute_inputs': 3, 'forward_integration_threat': 3}}
        factors = supplier_power_factors.get(sector, {'supplier_concentration': 3, 'switching_costs': 3, 'input_importance': 3, 'substitute_inputs': 3, 'forward_integration_threat': 3})
        avg_power = np.mean(list(factors.values()))
        if avg_power >= 4:
            power_level = 'High'
        elif avg_power >= 3:
            power_level = 'Medium'
        else:
            power_level = 'Low'
        return {'power_factors': factors, 'power_level': power_level, 'power_level_score': avg_power, 'key_factors': [k for k, v in factors.items() if v >= 4], 'analysis': f'Supplier power is {power_level.lower()} due to {', '.join([k.replace('_', ' ') for k, v in factors.items() if v >= 4])}'}

    def analyze_buyer_power(self, sector: str) -> Dict[str, Any]:
        """Analyze bargaining power of buyers"""
        buyer_power_factors = {'Information Technology': {'buyer_concentration': 3, 'switching_costs': 2, 'product_importance': 4, 'substitute_products': 3, 'backward_integration_threat': 2, 'price_sensitivity': 3}, 'Health Care': {'buyer_concentration': 4, 'switching_costs': 4, 'product_importance': 5, 'substitute_products': 2, 'backward_integration_threat': 1, 'price_sensitivity': 4}, 'Retail': {'buyer_concentration': 2, 'switching_costs': 1, 'product_importance': 2, 'substitute_products': 4, 'backward_integration_threat': 2, 'price_sensitivity': 5}}
        factors = buyer_power_factors.get(sector, {'buyer_concentration': 3, 'switching_costs': 3, 'product_importance': 3, 'substitute_products': 3, 'backward_integration_threat': 3, 'price_sensitivity': 3})
        power_reducing_factors = ['switching_costs', 'product_importance']
        for factor in power_reducing_factors:
            if factor in factors:
                factors[factor] = 6 - factors[factor]
        avg_power = np.mean(list(factors.values()))
        if avg_power >= 4:
            power_level = 'High'
        elif avg_power >= 3:
            power_level = 'Medium'
        else:
            power_level = 'Low'
        return {'power_factors': buyer_power_factors.get(sector, factors), 'power_level': power_level, 'power_level_score': avg_power, 'key_factors': [k for k, v in factors.items() if v >= 4], 'analysis': f'Buyer power is {power_level.lower()}'}

    def analyze_threat_of_substitutes(self, sector: str) -> Dict[str, Any]:
        """Analyze threat of substitute products"""
        substitute_factors = {'Information Technology': {'substitute_availability': 4, 'switching_costs': 3, 'substitute_performance': 3, 'price_performance': 3}, 'Energy': {'substitute_availability': 4, 'switching_costs': 4, 'substitute_performance': 3, 'price_performance': 4}, 'Transportation': {'substitute_availability': 3, 'switching_costs': 3, 'substitute_performance': 3, 'price_performance': 3}}
        factors = substitute_factors.get(sector, {'substitute_availability': 3, 'switching_costs': 3, 'substitute_performance': 3, 'price_performance': 3})
        factors['switching_costs'] = 6 - factors['switching_costs']
        avg_threat = np.mean(list(factors.values()))
        if avg_threat >= 4:
            threat_level = 'High'
        elif avg_threat >= 3:
            threat_level = 'Medium'
        else:
            threat_level = 'Low'
        return {'substitute_factors': substitute_factors.get(sector, factors), 'threat_level': threat_level, 'threat_level_score': avg_threat, 'key_factors': [k for k, v in factors.items() if v >= 4], 'analysis': f'Substitute threat is {threat_level.lower()}'}

    def analyze_competitive_rivalry(self, sector: str) -> Dict[str, Any]:
        """Analyze intensity of competitive rivalry"""
        rivalry_factors = {'Information Technology': {'number_of_competitors': 5, 'industry_growth': 2, 'product_differentiation': 3, 'switching_costs': 2, 'exit_barriers': 3, 'fixed_costs': 3}, 'Airlines': {'number_of_competitors': 4, 'industry_growth': 3, 'product_differentiation': 2, 'switching_costs': 1, 'exit_barriers': 5, 'fixed_costs': 5}, 'Utilities': {'number_of_competitors': 2, 'industry_growth': 2, 'product_differentiation': 1, 'switching_costs': 4, 'exit_barriers': 5, 'fixed_costs': 5}}
