class SyntheticInstrumentBuilder:
    """Build synthetic instruments using replication strategies"""

    @staticmethod
    def synthetic_call(put_price: float, spot_price: float, strike_price: float, risk_free_rate: float, time_to_expiry: float, dividend_yield: float=0.0) -> SyntheticInstrument:
        """Create synthetic call using put-call parity: C = P + S - K*e^(-rT)"""
        pv_strike = strike_price * np.exp(-risk_free_rate * time_to_expiry)
        pv_spot = spot_price * np.exp(-dividend_yield * time_to_expiry)
        synthetic_call_price = put_price + pv_spot - pv_strike
        return SyntheticInstrument(target_instrument='call', synthetic_components=[{'instrument': 'put', 'position': 'long', 'price': put_price, 'quantity': 1}, {'instrument': 'stock', 'position': 'long', 'price': spot_price, 'quantity': 1}, {'instrument': 'bond', 'position': 'short', 'price': pv_strike, 'quantity': 1}], cost_comparison=synthetic_call_price, replication_accuracy=0.99)

    @staticmethod
    def synthetic_put(call_price: float, spot_price: float, strike_price: float, risk_free_rate: float, time_to_expiry: float, dividend_yield: float=0.0) -> SyntheticInstrument:
        """Create synthetic put using put-call parity: P = C + K*e^(-rT) - S"""
        pv_strike = strike_price * np.exp(-risk_free_rate * time_to_expiry)
        pv_spot = spot_price * np.exp(-dividend_yield * time_to_expiry)
        synthetic_put_price = call_price + pv_strike - pv_spot
        return SyntheticInstrument(target_instrument='put', synthetic_components=[{'instrument': 'call', 'position': 'long', 'price': call_price, 'quantity': 1}, {'instrument': 'bond', 'position': 'long', 'price': pv_strike, 'quantity': 1}, {'instrument': 'stock', 'position': 'short', 'price': spot_price, 'quantity': 1}], cost_comparison=synthetic_put_price, replication_accuracy=0.99)

    @staticmethod
    def synthetic_stock(call_price: float, put_price: float, strike_price: float, risk_free_rate: float, time_to_expiry: float, dividend_yield: float=0.0) -> SyntheticInstrument:
        """Create synthetic stock using options: S = C - P + K*e^(-rT)"""
        pv_strike = strike_price * np.exp(-risk_free_rate * time_to_expiry)
        synthetic_stock_price = call_price - put_price + pv_strike
        return SyntheticInstrument(target_instrument='stock', synthetic_components=[{'instrument': 'call', 'position': 'long', 'price': call_price, 'quantity': 1}, {'instrument': 'put', 'position': 'short', 'price': put_price, 'quantity': 1}, {'instrument': 'bond', 'position': 'long', 'price': pv_strike, 'quantity': 1}], cost_comparison=synthetic_stock_price, replication_accuracy=0.95)

    @staticmethod
    def synthetic_forward(spot_price: float, risk_free_rate: float, time_to_expiry: float, dividend_yield: float=0.0) -> SyntheticInstrument:
        """Create synthetic forward position: F = S*e^((r-q)*T)"""
        pv_dividends = spot_price * (1 - np.exp(-dividend_yield * time_to_expiry))
        borrowing_cost = (spot_price - pv_dividends) * (np.exp(risk_free_rate * time_to_expiry) - 1)
        forward_price = spot_price * np.exp((risk_free_rate - dividend_yield) * time_to_expiry)
        return SyntheticInstrument(target_instrument='forward', synthetic_components=[{'instrument': 'stock', 'position': 'long', 'price': spot_price, 'quantity': 1}, {'instrument': 'bond', 'position': 'short', 'price': spot_price - pv_dividends, 'quantity': 1}], cost_comparison=forward_price, replication_accuracy=0.99)

    @staticmethod
    def synthetic_bond(strike_price: float, call_price: float, put_price: float, spot_price: float, dividend_yield: float=0.0) -> SyntheticInstrument:
        """Create synthetic bond using put-call parity: Bond = C - P + S"""
        synthetic_bond_price = strike_price
        cost_to_replicate = call_price - put_price + spot_price * np.exp(-dividend_yield)
        return SyntheticInstrument(target_instrument='bond', synthetic_components=[{'instrument': 'call', 'position': 'long', 'price': call_price, 'quantity': 1}, {'instrument': 'put', 'position': 'short', 'price': put_price, 'quantity': 1}, {'instrument': 'stock', 'position': 'long', 'price': spot_price, 'quantity': 1}], cost_comparison=cost_to_replicate, replication_accuracy=0.98)

@staticmethod
def synthetic_call(put_price: float, spot_price: float, strike_price: float, risk_free_rate: float, time_to_expiry: float, dividend_yield: float=0.0) -> SyntheticInstrument:
    """Create synthetic call using put-call parity: C = P + S - K*e^(-rT)"""
    pv_strike = strike_price * np.exp(-risk_free_rate * time_to_expiry)
    pv_spot = spot_price * np.exp(-dividend_yield * time_to_expiry)
    synthetic_call_price = put_price + pv_spot - pv_strike
    return SyntheticInstrument(target_instrument='call', synthetic_components=[{'instrument': 'put', 'position': 'long', 'price': put_price, 'quantity': 1}, {'instrument': 'stock', 'position': 'long', 'price': spot_price, 'quantity': 1}, {'instrument': 'bond', 'position': 'short', 'price': pv_strike, 'quantity': 1}], cost_comparison=synthetic_call_price, replication_accuracy=0.99)

@staticmethod
def synthetic_put(call_price: float, spot_price: float, strike_price: float, risk_free_rate: float, time_to_expiry: float, dividend_yield: float=0.0) -> SyntheticInstrument:
    """Create synthetic put using put-call parity: P = C + K*e^(-rT) - S"""
    pv_strike = strike_price * np.exp(-risk_free_rate * time_to_expiry)
    pv_spot = spot_price * np.exp(-dividend_yield * time_to_expiry)
    synthetic_put_price = call_price + pv_strike - pv_spot
    return SyntheticInstrument(target_instrument='put', synthetic_components=[{'instrument': 'call', 'position': 'long', 'price': call_price, 'quantity': 1}, {'instrument': 'bond', 'position': 'long', 'price': pv_strike, 'quantity': 1}, {'instrument': 'stock', 'position': 'short', 'price': spot_price, 'quantity': 1}], cost_comparison=synthetic_put_price, replication_accuracy=0.99)

@staticmethod
def synthetic_stock(call_price: float, put_price: float, strike_price: float, risk_free_rate: float, time_to_expiry: float, dividend_yield: float=0.0) -> SyntheticInstrument:
    """Create synthetic stock using options: S = C - P + K*e^(-rT)"""
    pv_strike = strike_price * np.exp(-risk_free_rate * time_to_expiry)
    synthetic_stock_price = call_price - put_price + pv_strike
    return SyntheticInstrument(target_instrument='stock', synthetic_components=[{'instrument': 'call', 'position': 'long', 'price': call_price, 'quantity': 1}, {'instrument': 'put', 'position': 'short', 'price': put_price, 'quantity': 1}, {'instrument': 'bond', 'position': 'long', 'price': pv_strike, 'quantity': 1}], cost_comparison=synthetic_stock_price, replication_accuracy=0.95)

@staticmethod
def synthetic_forward(spot_price: float, risk_free_rate: float, time_to_expiry: float, dividend_yield: float=0.0) -> SyntheticInstrument:
    """Create synthetic forward position: F = S*e^((r-q)*T)"""
    pv_dividends = spot_price * (1 - np.exp(-dividend_yield * time_to_expiry))
    borrowing_cost = (spot_price - pv_dividends) * (np.exp(risk_free_rate * time_to_expiry) - 1)
    forward_price = spot_price * np.exp((risk_free_rate - dividend_yield) * time_to_expiry)
    return SyntheticInstrument(target_instrument='forward', synthetic_components=[{'instrument': 'stock', 'position': 'long', 'price': spot_price, 'quantity': 1}, {'instrument': 'bond', 'position': 'short', 'price': spot_price - pv_dividends, 'quantity': 1}], cost_comparison=forward_price, replication_accuracy=0.99)

@staticmethod
def synthetic_bond(strike_price: float, call_price: float, put_price: float, spot_price: float, dividend_yield: float=0.0) -> SyntheticInstrument:
    """Create synthetic bond using put-call parity: Bond = C - P + S"""
    synthetic_bond_price = strike_price
    cost_to_replicate = call_price - put_price + spot_price * np.exp(-dividend_yield)
    return SyntheticInstrument(target_instrument='bond', synthetic_components=[{'instrument': 'call', 'position': 'long', 'price': call_price, 'quantity': 1}, {'instrument': 'put', 'position': 'short', 'price': put_price, 'quantity': 1}, {'instrument': 'stock', 'position': 'long', 'price': spot_price, 'quantity': 1}], cost_comparison=cost_to_replicate, replication_accuracy=0.98)

class MathUtils:
    """Mathematical utility functions for derivatives pricing"""

    @staticmethod
    def normal_cdf(x: float) -> float:
        """Cumulative distribution function of standard normal"""
        return 0.5 * (1 + erf(x / np.sqrt(2)))

    @staticmethod
    def normal_pdf(x: float) -> float:
        """Probability density function of standard normal"""
        return np.exp(-0.5 * x ** 2) / np.sqrt(2 * np.pi)

    @staticmethod
    def inverse_normal_cdf(p: float) -> float:
        """Inverse cumulative distribution function (quantile)"""
        if not 0 < p < 1:
            raise ValueError('Probability must be between 0 and 1')
        return stats.norm.ppf(p)

    @staticmethod
    def bivariate_normal_cdf(x: float, y: float, rho: float) -> float:
        """Bivariate normal cumulative distribution function"""
        return stats.multivariate_normal.cdf([x, y], cov=[[1, rho], [rho, 1]])

    @staticmethod
    def black_scholes_call_delta(S: float, K: float, T: float, r: float, sigma: float, q: float=0) -> float:
        """Black-Scholes call delta (analytical)"""
        if T <= 0:
            return 1.0 if S > K else 0.0
        d1 = (np.log(S / K) + (r - q + 0.5 * sigma ** 2) * T) / (sigma * np.sqrt(T))
        return np.exp(-q * T) * MathUtils.normal_cdf(d1)

    @staticmethod
    def black_scholes_gamma(S: float, K: float, T: float, r: float, sigma: float, q: float=0) -> float:
        """Black-Scholes gamma (analytical)"""
        if T <= 0:
            return 0.0
        d1 = (np.log(S / K) + (r - q + 0.5 * sigma ** 2) * T) / (sigma * np.sqrt(T))
        return np.exp(-q * T) * MathUtils.normal_pdf(d1) / (S * sigma * np.sqrt(T))

    @staticmethod
    def compound_interest(principal: float, rate: float, time: float, frequency: int=1) -> float:
        """Calculate compound interest"""
        return principal * (1 + rate / frequency) ** (frequency * time)

    @staticmethod
    def continuous_compounding(principal: float, rate: float, time: float) -> float:
        """Calculate continuous compounding"""
        return principal * np.exp(rate * time)

    @staticmethod
    def present_value(future_value: float, rate: float, time: float) -> float:
        """Calculate present value with continuous compounding"""
        return future_value * np.exp(-rate * time)

    @staticmethod
    def annuity_pv(payment: float, rate: float, periods: int) -> float:
        """Present value of ordinary annuity"""
        if rate == 0:
            return payment * periods
        return payment * (1 - (1 + rate) ** (-periods)) / rate

    @staticmethod
    def perpetuity_pv(payment: float, rate: float) -> float:
        """Present value of perpetuity"""
        if rate <= 0:
            raise ValueError('Rate must be positive for perpetuity')
        return payment / rate

