class OptimizationSolver:
    """Numerical optimization methods for derivatives pricing"""

    @staticmethod
    def newton_raphson(func: Callable, derivative: Callable, initial_guess: float, tolerance: float=1e-08, max_iterations: int=100) -> Dict[str, Any]:
        """Newton-Raphson root finding method"""
        x = initial_guess
        for i in range(max_iterations):
            try:
                f_x = func(x)
                f_prime_x = derivative(x)
                if abs(f_prime_x) < tolerance:
                    return {'success': False, 'message': 'Derivative too small', 'iterations': i}
                x_new = x - f_x / f_prime_x
                if abs(x_new - x) < tolerance:
                    return {'success': True, 'root': x_new, 'function_value': func(x_new), 'iterations': i + 1}
                x = x_new
            except Exception as e:
                return {'success': False, 'message': str(e), 'iterations': i}
        return {'success': False, 'message': 'Max iterations reached', 'iterations': max_iterations}

    @staticmethod
    def bisection_method(func: Callable, a: float, b: float, tolerance: float=1e-08, max_iterations: int=100) -> Dict[str, Any]:
        """Bisection root finding method"""
        if func(a) * func(b) >= 0:
            return {'success': False, 'message': 'Function must have opposite signs at endpoints'}
        for i in range(max_iterations):
            c = (a + b) / 2
            f_c = func(c)
            if abs(f_c) < tolerance or (b - a) / 2 < tolerance:
                return {'success': True, 'root': c, 'function_value': f_c, 'iterations': i + 1}
            if func(a) * f_c < 0:
                b = c
            else:
                a = c
        return {'success': False, 'message': 'Max iterations reached', 'iterations': max_iterations}

    @staticmethod
    def brent_method(func: Callable, a: float, b: float, tolerance: float=1e-08) -> Dict[str, Any]:
        """Brent's method for root finding (most robust)"""
        try:
            result = optimize.brentq(func, a, b, xtol=tolerance, full_output=True)
            root, result_info = result
            return {'success': True, 'root': root, 'function_value': func(root), 'iterations': result_info.iterations, 'function_calls': result_info.function_calls}
        except Exception as e:
            return {'success': False, 'message': str(e)}

    @staticmethod
    def golden_section_search(func: Callable, a: float, b: float, tolerance: float=1e-08, maximize: bool=False) -> Dict[str, Any]:
        """Golden section search for optimization"""
        golden_ratio = (1 + np.sqrt(5)) / 2
        resphi = 2 - golden_ratio
        tol = tolerance
        x1 = a + resphi * (b - a)
        x2 = b - resphi * (b - a)
        f1 = func(x1)
        f2 = func(x2)
        if maximize:
            f1, f2 = (-f1, -f2)
        iterations = 0
        while abs(b - a) > tol:
            iterations += 1
            if f1 < f2:
                b = x2
                x2 = x1
                f2 = f1
                x1 = a + resphi * (b - a)
                f1 = func(x1)
                if maximize:
                    f1 = -f1
            else:
                a = x1
                x1 = x2
                f1 = f2
                x2 = b - resphi * (b - a)
                f2 = func(x2)
                if maximize:
                    f2 = -f2
        optimal_x = (a + b) / 2
        optimal_value = func(optimal_x)
        return {'success': True, 'optimal_x': optimal_x, 'optimal_value': optimal_value if not maximize else -optimal_value, 'iterations': iterations}

@staticmethod
def newton_raphson(func: Callable, derivative: Callable, initial_guess: float, tolerance: float=1e-08, max_iterations: int=100) -> Dict[str, Any]:
    """Newton-Raphson root finding method"""
    x = initial_guess
    for i in range(max_iterations):
        try:
            f_x = func(x)
            f_prime_x = derivative(x)
            if abs(f_prime_x) < tolerance:
                return {'success': False, 'message': 'Derivative too small', 'iterations': i}
            x_new = x - f_x / f_prime_x
            if abs(x_new - x) < tolerance:
                return {'success': True, 'root': x_new, 'function_value': func(x_new), 'iterations': i + 1}
            x = x_new
        except Exception as e:
            return {'success': False, 'message': str(e), 'iterations': i}
    return {'success': False, 'message': 'Max iterations reached', 'iterations': max_iterations}

