class ManualDataProvider(MarketDataProvider):
    """Manual data input provider for custom scenarios"""

    def __init__(self):
        super().__init__(DataProvider.MANUAL)
        self.data_cache = {}
        self.connection_status = True

    def connect(self, **kwargs) -> bool:
        self.connection_status = True
        return True

    def disconnect(self) -> bool:
        self.connection_status = False
        return True

    def set_spot_price(self, symbol: str, price: float):
        """Manually set spot price"""
        ModelValidator.validate_positive(price, f'spot price for {symbol}')
        self.data_cache[f'spot_{symbol}'] = price
        self.last_update = datetime.now()

    def set_risk_free_rate(self, rate: float, currency: str='USD', maturity: float=0.25):
        """Manually set risk-free rate"""
        ModelValidator.validate_rate(rate, f'risk-free rate for {currency}')
        self.data_cache[f'rf_{currency}_{maturity}'] = rate
        self.last_update = datetime.now()

    def set_dividend_yield(self, symbol: str, yield_rate: float):
        """Manually set dividend yield"""
        ModelValidator.validate_non_negative(yield_rate, f'dividend yield for {symbol}')
        self.data_cache[f'div_{symbol}'] = yield_rate
        self.last_update = datetime.now()

    def set_volatility(self, symbol: str, volatility: float, maturity: float=None, strike: float=None):
        """Manually set volatility"""
        ModelValidator.validate_volatility(volatility)
        key = f'vol_{symbol}'
        if maturity is not None:
            key += f'_{maturity}'
        if strike is not None:
            key += f'_{strike}'
        self.data_cache[key] = volatility
        self.last_update = datetime.now()

    def get_spot_price(self, symbol: str) -> float:
        key = f'spot_{symbol}'
        if key not in self.data_cache:
            raise ValueError(f'No spot price data for symbol: {symbol}')
        return self.data_cache[key]

    def get_risk_free_rate(self, currency: str='USD', maturity: float=0.25) -> float:
        key = f'rf_{currency}_{maturity}'
        if key not in self.data_cache:
            default_key = f'rf_{currency}_0.25'
            if default_key in self.data_cache:
                return self.data_cache[default_key]
            return 0.02
        return self.data_cache[key]

    def get_dividend_yield(self, symbol: str) -> float:
        key = f'div_{symbol}'
        return self.data_cache.get(key, 0.0)

    def get_volatility(self, symbol: str, maturity: float, strike: float=None) -> float:
        key = f'vol_{symbol}_{maturity}'
        if strike is not None:
            key += f'_{strike}'
        if key in self.data_cache:
            return self.data_cache[key]
        key_no_strike = f'vol_{symbol}_{maturity}'
        if key_no_strike in self.data_cache:
            return self.data_cache[key_no_strike]
        generic_key = f'vol_{symbol}'
        if generic_key in self.data_cache:
            return self.data_cache[generic_key]
        return 0.2

    def get_yield_curve(self, currency: str, curve_type: str='government') -> CurveData:
        """Get yield curve (simplified for manual input)"""
        curve = CurveData(curve_date=datetime.now(), curve_type=curve_type, currency=currency, day_count=DayCountConvention.ACT_365)
        default_rates = [(0.25, 0.02), (0.5, 0.022), (1.0, 0.025), (2.0, 0.028), (5.0, 0.032), (10.0, 0.035), (30.0, 0.038)]
        for maturity, rate in default_rates:
            rf_rate = self.get_risk_free_rate(currency, maturity)
            curve.add_point(maturity, rf_rate)
        return curve

def get_spot_price(self, symbol: str) -> float:
    key = f'spot_{symbol}'
    if key not in self.data_cache:
        raise ValueError(f'No spot price data for symbol: {symbol}')
    return self.data_cache[key]

class MarketDataManager:
    """Central manager for market data from multiple providers"""

    def __init__(self, primary_provider: MarketDataProvider=None):
        self.providers = {}
        self.primary_provider = primary_provider or ManualDataProvider()
        self.cache = DataCache()
        self.register_provider('manual', ManualDataProvider())
        self.register_provider('yahoo', YahooFinanceProvider())

    def register_provider(self, name: str, provider: MarketDataProvider):
        """Register a market data provider"""
        self.providers[name] = provider

    def set_primary_provider(self, provider_name: str):
        """Set primary data provider"""
        if provider_name not in self.providers:
            raise ValueError(f'Provider {provider_name} not registered')
        self.primary_provider = self.providers[provider_name]

    def get_market_snapshot(self, symbol: str, currency: str='USD') -> MarketSnapshot:
        """Get complete market snapshot for symbol"""
        cache_key = f'snapshot_{symbol}_{currency}'
        cached_data = self.cache.get(cache_key)
        if cached_data:
            return cached_data
        try:
            snapshot = MarketSnapshot(timestamp=datetime.now(), spot_price=self.primary_provider.get_spot_price(symbol), risk_free_rate=self.primary_provider.get_risk_free_rate(currency), dividend_yield=self.primary_provider.get_dividend_yield(symbol))
            self.cache.set(cache_key, snapshot)
            return snapshot
        except Exception as e:
            logger.error(f'Failed to get market snapshot: {e}')
            raise

    def get_spot_price(self, symbol: str, provider: str=None) -> float:
        """Get spot price with fallback providers"""
        provider_obj = self.providers.get(provider, self.primary_provider)
        try:
            return provider_obj.get_spot_price(symbol)
        except Exception as e:
            logger.warning(f'Primary provider failed for {symbol}: {e}')
            for name, fallback_provider in self.providers.items():
                if fallback_provider != provider_obj:
                    try:
                        return fallback_provider.get_spot_price(symbol)
                    except:
                        continue
            raise ValueError(f'No provider could fetch spot price for {symbol}')

def set_primary_provider(self, provider_name: str):
    """Set primary data provider"""
    if provider_name not in self.providers:
        raise ValueError(f'Provider {provider_name} not registered')
    self.primary_provider = self.providers[provider_name]

@dataclass
class MarketData:
    """Market data container for derivative pricing"""
    spot_price: float
    risk_free_rate: float
    dividend_yield: float = 0.0
    volatility: float = 0.0
    time_to_expiry: float = 0.0
    strike_price: Optional[float] = None
    forward_price: Optional[float] = None

    def __post_init__(self):
        """Validate market data inputs"""
        if self.spot_price <= 0:
            raise ValueError('Spot price must be positive')
        if self.volatility < 0:
            raise ValueError('Volatility cannot be negative')
        if self.time_to_expiry < 0:
            raise ValueError('Time to expiry cannot be negative')

def __post_init__(self):
    """Validate market data inputs"""
    if self.spot_price <= 0:
        raise ValueError('Spot price must be positive')
    if self.volatility < 0:
        raise ValueError('Volatility cannot be negative')
    if self.time_to_expiry < 0:
        raise ValueError('Time to expiry cannot be negative')

class ModelValidator:
    """Validation utilities for derivative models"""

    @staticmethod
    def validate_probability(prob: float) -> bool:
        """Validate probability is between 0 and 1"""
        return 0 <= prob <= 1

    @staticmethod
    def validate_positive(value: float, name: str) -> bool:
        """Validate value is positive"""
        if value <= 0:
            raise ValidationError(f'{name} must be positive, got {value}')
        return True

    @staticmethod
    def validate_non_negative(value: float, name: str) -> bool:
        """Validate value is non-negative"""
        if value < 0:
            raise ValidationError(f'{name} cannot be negative, got {value}')
        return True

    @staticmethod
    def validate_rate(rate: float, name: str) -> bool:
        """Validate interest rate (can be negative in modern markets)"""
        if abs(rate) > 1.0:
            logger.warning(f'{name} is unusually high: {rate * 100:.2f}%')
        return True

    @staticmethod
    def validate_volatility(vol: float) -> bool:
        """Validate volatility parameter"""
        if vol < 0:
            raise ValidationError(f'Volatility cannot be negative, got {vol}')
        if vol > 5.0:
            logger.warning(f'Volatility is extremely high: {vol * 100:.2f}%')
        return True

@staticmethod
def validate_rate(rate: float, name: str) -> bool:
    """Validate interest rate (can be negative in modern markets)"""
    if abs(rate) > 1.0:
        logger.warning(f'{name} is unusually high: {rate * 100:.2f}%')
    return True

def risk_free_rate_converter(rate: float, from_compounding: str='continuous', to_compounding: str='continuous', frequency: int=1) -> float:
    """
    Convert between different interest rate compounding conventions

    Args:
        rate: Input interest rate
        from_compounding: Source compounding ('continuous', 'annual', 'discrete')
        to_compounding: Target compounding ('continuous', 'annual', 'discrete')
        frequency: Compounding frequency for discrete rates

    Returns:
        Converted interest rate
    """
    if from_compounding == 'continuous':
        continuous_rate = rate
    elif from_compounding == 'annual':
        continuous_rate = np.log(1 + rate)
    elif from_compounding == 'discrete':
        continuous_rate = frequency * np.log(1 + rate / frequency)
    else:
        raise ValueError(f'Unknown compounding type: {from_compounding}')
    if to_compounding == 'continuous':
        return continuous_rate
    elif to_compounding == 'annual':
        return np.exp(continuous_rate) - 1
    elif to_compounding == 'discrete':
        return frequency * (np.exp(continuous_rate / frequency) - 1)
    else:
        raise ValueError(f'Unknown compounding type: {to_compounding}')

class RiskAnalyzer:
    """Advanced risk analysis for derivatives portfolios"""

    def __init__(self, confidence_levels: List[float]=None):
        self.confidence_levels = confidence_levels or [0.95, 0.99]
        self.simulation_results = []

    def calculate_var(self, returns: np.ndarray, confidence_level: float=0.95) -> float:
        """Calculate Value at Risk"""
        if len(returns) == 0:
            return 0.0
        return np.percentile(returns, (1 - confidence_level) * 100)

    def calculate_cvar(self, returns: np.ndarray, confidence_level: float=0.95) -> float:
        """Calculate Conditional Value at Risk (Expected Shortfall)"""
        if len(returns) == 0:
            return 0.0
        var_threshold = self.calculate_var(returns, confidence_level)
        tail_losses = returns[returns <= var_threshold]
        return np.mean(tail_losses) if len(tail_losses) > 0 else var_threshold

    def calculate_maximum_drawdown(self, portfolio_values: np.ndarray) -> float:
        """Calculate maximum drawdown"""
        if len(portfolio_values) < 2:
            return 0.0
        running_max = np.maximum.accumulate(portfolio_values)
        drawdowns = (portfolio_values - running_max) / running_max
        return np.min(drawdowns)

    def calculate_portfolio_risk_metrics(self, portfolio: DerivativesPortfolio, historical_returns: np.ndarray=None, benchmark_returns: np.ndarray=None, risk_free_rate: float=0.02) -> RiskMetrics:
        """Calculate comprehensive risk metrics"""
        if historical_returns is None:
            historical_returns = np.random.normal(0.001, 0.02, 252)
        portfolio_value = sum((pos.current_value for pos in portfolio.positions))
        volatility = np.std(historical_returns) * np.sqrt(252)
        var_95 = self.calculate_var(historical_returns, 0.95)
        var_99 = self.calculate_var(historical_returns, 0.99)
        cvar_95 = self.calculate_cvar(historical_returns, 0.95)
        cvar_99 = self.calculate_cvar(historical_returns, 0.99)
        portfolio_values = portfolio_value * (1 + np.cumsum(historical_returns))
        max_drawdown = self.calculate_maximum_drawdown(portfolio_values)
        excess_returns = historical_returns - risk_free_rate / 252
        sharpe_ratio = np.mean(excess_returns) / np.std(historical_returns) * np.sqrt(252) if np.std(historical_returns) > 0 else 0
        downside_returns = historical_returns[historical_returns < 0]
        downside_deviation = np.std(downside_returns) if len(downside_returns) > 0 else np.std(historical_returns)
        sortino_ratio = np.mean(excess_returns) / downside_deviation * np.sqrt(252) if downside_deviation > 0 else 0
        calmar_ratio = np.mean(excess_returns) * 252 / abs(max_drawdown) if max_drawdown != 0 else 0
        beta = 0.0
        if benchmark_returns is not None and len(benchmark_returns) == len(historical_returns):
            covariance = np.cov(historical_returns, benchmark_returns)[0, 1]
            benchmark_variance = np.var(benchmark_returns)
            beta = covariance / benchmark_variance if benchmark_variance > 0 else 0
        return RiskMetrics(portfolio_value=portfolio_value, var_95=var_95 * portfolio_value, var_99=var_99 * portfolio_value, cvar_95=cvar_95 * portfolio_value, cvar_99=cvar_99 * portfolio_value, volatility=volatility, maximum_drawdown=max_drawdown, sharpe_ratio=sharpe_ratio, sortino_ratio=sortino_ratio, calmar_ratio=calmar_ratio, beta=beta)

def calculate_cvar(self, returns: np.ndarray, confidence_level: float=0.95) -> float:
    """Calculate Conditional Value at Risk (Expected Shortfall)"""
    if len(returns) == 0:
        return 0.0
    var_threshold = self.calculate_var(returns, confidence_level)
    tail_losses = returns[returns <= var_threshold]
    return np.mean(tail_losses) if len(tail_losses) > 0 else var_threshold

def calculate_portfolio_risk_metrics(self, portfolio: DerivativesPortfolio, historical_returns: np.ndarray=None, benchmark_returns: np.ndarray=None, risk_free_rate: float=0.02) -> RiskMetrics:
    """Calculate comprehensive risk metrics"""
    if historical_returns is None:
        historical_returns = np.random.normal(0.001, 0.02, 252)
    portfolio_value = sum((pos.current_value for pos in portfolio.positions))
    volatility = np.std(historical_returns) * np.sqrt(252)
    var_95 = self.calculate_var(historical_returns, 0.95)
    var_99 = self.calculate_var(historical_returns, 0.99)
    cvar_95 = self.calculate_cvar(historical_returns, 0.95)
    cvar_99 = self.calculate_cvar(historical_returns, 0.99)
    portfolio_values = portfolio_value * (1 + np.cumsum(historical_returns))
    max_drawdown = self.calculate_maximum_drawdown(portfolio_values)
    excess_returns = historical_returns - risk_free_rate / 252
    sharpe_ratio = np.mean(excess_returns) / np.std(historical_returns) * np.sqrt(252) if np.std(historical_returns) > 0 else 0
    downside_returns = historical_returns[historical_returns < 0]
    downside_deviation = np.std(downside_returns) if len(downside_returns) > 0 else np.std(historical_returns)
    sortino_ratio = np.mean(excess_returns) / downside_deviation * np.sqrt(252) if downside_deviation > 0 else 0
    calmar_ratio = np.mean(excess_returns) * 252 / abs(max_drawdown) if max_drawdown != 0 else 0
    beta = 0.0
    if benchmark_returns is not None and len(benchmark_returns) == len(historical_returns):
        covariance = np.cov(historical_returns, benchmark_returns)[0, 1]
        benchmark_variance = np.var(benchmark_returns)
        beta = covariance / benchmark_variance if benchmark_variance > 0 else 0
    return RiskMetrics(portfolio_value=portfolio_value, var_95=var_95 * portfolio_value, var_99=var_99 * portfolio_value, cvar_95=cvar_95 * portfolio_value, cvar_99=cvar_99 * portfolio_value, volatility=volatility, maximum_drawdown=max_drawdown, sharpe_ratio=sharpe_ratio, sortino_ratio=sortino_ratio, calmar_ratio=calmar_ratio, beta=beta)

class ScenarioAnalyzer:
    """Scenario analysis and stress testing"""

    def __init__(self):
        self.scenarios = {}

    def add_scenario(self, name: str, market_shocks: Dict[str, float]):
        """Add predefined scenario"""
        self.scenarios[name] = market_shocks

    def stress_test(self, portfolio: DerivativesPortfolio, base_market_data: MarketData, stress_scenarios: Dict[str, Dict[str, float]]=None) -> List[ScenarioResult]:
        """Perform stress testing on portfolio"""
        if stress_scenarios is None:
            stress_scenarios = self._get_default_stress_scenarios()
        base_value = portfolio.update_positions(base_market_data)
        results = []
        for scenario_name, shocks in stress_scenarios.items():
            try:
                stressed_market_data = self._apply_market_shocks(base_market_data, shocks)
                stressed_value = portfolio.update_positions(stressed_market_data)
                pnl_change = stressed_value - base_value
                percentage_change = pnl_change / base_value * 100 if base_value != 0 else 0
                result = ScenarioResult(scenario_name=scenario_name, scenario_type=ScenarioType.STRESS_TEST, base_portfolio_value=base_value, scenario_portfolio_value=stressed_value, pnl_change=pnl_change, percentage_change=percentage_change, scenario_parameters=shocks)
                results.append(result)
            except Exception as e:
                logger.error(f'Error in stress test scenario {scenario_name}: {e}')
        return results

    def monte_carlo_simulation(self, portfolio: DerivativesPortfolio, base_market_data: MarketData, num_simulations: int=10000, time_horizon: int=30) -> List[ScenarioResult]:
        """Monte Carlo simulation for portfolio"""
        base_value = portfolio.update_positions(base_market_data)
        results = []
        dt = 1 / 252
        drift = 0.0001
        volatility = 0.02
        for i in range(num_simulations):
            try:
                random_shocks = np.random.normal(0, 1, time_horizon)
                final_spot_multiplier = np.exp(np.sum((drift - 0.5 * volatility ** 2) * dt + volatility * np.sqrt(dt) * random_shocks))
                simulated_market_data = MarketData(spot_price=base_market_data.spot_price * final_spot_multiplier, risk_free_rate=base_market_data.risk_free_rate, dividend_yield=base_market_data.dividend_yield, volatility=base_market_data.volatility, time_to_expiry=max(0, base_market_data.time_to_expiry - time_horizon / 252))
                simulated_value = portfolio.update_positions(simulated_market_data)
                pnl_change = simulated_value - base_value
                percentage_change = pnl_change / base_value * 100 if base_value != 0 else 0
                result = ScenarioResult(scenario_name=f'MC_Simulation_{i + 1}', scenario_type=ScenarioType.MONTE_CARLO, base_portfolio_value=base_value, scenario_portfolio_value=simulated_value, pnl_change=pnl_change, percentage_change=percentage_change, probability=1 / num_simulations, scenario_parameters={'final_spot_multiplier': final_spot_multiplier, 'time_horizon_days': time_horizon})
                results.append(result)
            except Exception as e:
                logger.warning(f'Error in MC simulation {i + 1}: {e}')
        return results

    def sensitivity_analysis(self, portfolio: DerivativesPortfolio, base_market_data: MarketData, parameters: List[str]=None, shock_sizes: Dict[str, float]=None) -> List[SensitivityResult]:
        """Perform sensitivity analysis on key parameters"""
        if parameters is None:
            parameters = ['spot_price', 'volatility', 'risk_free_rate', 'time_to_expiry']
        if shock_sizes is None:
            shock_sizes = {'spot_price': 0.01, 'volatility': 0.01, 'risk_free_rate': 0.0025, 'time_to_expiry': -1 / 365}
        base_value = portfolio.update_positions(base_market_data)
        results = []
        for param in parameters:
            if param not in shock_sizes:
                continue
            try:
                shocked_data = self._shock_parameter(base_market_data, param, shock_sizes[param])
                shocked_value = portfolio.update_positions(shocked_data)
                pnl_change = shocked_value - base_value
                base_param_value = getattr(base_market_data, param)
                sensitivity = pnl_change / shock_sizes[param] if shock_sizes[param] != 0 else 0
                if base_param_value != 0 and base_value != 0:
                    elasticity = pnl_change / base_value / (shock_sizes[param] / base_param_value)
                else:
                    elasticity = 0
                result = SensitivityResult(parameter_name=param, base_value=base_param_value, shock_size=shock_sizes[param], portfolio_value_change=pnl_change, sensitivity=sensitivity, elasticity=elasticity)
                results.append(result)
            except Exception as e:
                logger.error(f'Error in sensitivity analysis for {param}: {e}')
        return results

    def _get_default_stress_scenarios(self) -> Dict[str, Dict[str, float]]:
        """Get default stress test scenarios"""
        return {'Market_Crash': {'spot_price': -0.2, 'volatility': 0.15, 'risk_free_rate': -0.01}, 'Vol_Spike': {'volatility': 0.2, 'spot_price': -0.05}, 'Interest_Rate_Shock': {'risk_free_rate': 0.02, 'spot_price': -0.1}, 'Time_Decay': {'time_to_expiry': -0.1, 'volatility': -0.05}, 'Bull_Market': {'spot_price': 0.15, 'volatility': -0.05}}

    def _apply_market_shocks(self, base_data: MarketData, shocks: Dict[str, float]) -> MarketData:
        """Apply market shocks to create stressed market data"""
        return MarketData(spot_price=base_data.spot_price * (1 + shocks.get('spot_price', 0)), risk_free_rate=base_data.risk_free_rate + shocks.get('risk_free_rate', 0), dividend_yield=base_data.dividend_yield + shocks.get('dividend_yield', 0), volatility=max(0.001, base_data.volatility + shocks.get('volatility', 0)), time_to_expiry=max(0, base_data.time_to_expiry + shocks.get('time_to_expiry', 0)))

    def _shock_parameter(self, base_data: MarketData, parameter: str, shock: float) -> MarketData:
        """Apply shock to specific parameter"""
        data_dict = {'spot_price': base_data.spot_price, 'risk_free_rate': base_data.risk_free_rate, 'dividend_yield': base_data.dividend_yield, 'volatility': base_data.volatility, 'time_to_expiry': base_data.time_to_expiry}
        if parameter in data_dict:
            if parameter == 'spot_price':
                data_dict[parameter] *= 1 + shock
            else:
                data_dict[parameter] += shock
        return MarketData(**data_dict)

def monte_carlo_simulation(self, portfolio: DerivativesPortfolio, base_market_data: MarketData, num_simulations: int=10000, time_horizon: int=30) -> List[ScenarioResult]:
    """Monte Carlo simulation for portfolio"""
    base_value = portfolio.update_positions(base_market_data)
    results = []
    dt = 1 / 252
    drift = 0.0001
    volatility = 0.02
    for i in range(num_simulations):
        try:
            random_shocks = np.random.normal(0, 1, time_horizon)
            final_spot_multiplier = np.exp(np.sum((drift - 0.5 * volatility ** 2) * dt + volatility * np.sqrt(dt) * random_shocks))
            simulated_market_data = MarketData(spot_price=base_market_data.spot_price * final_spot_multiplier, risk_free_rate=base_market_data.risk_free_rate, dividend_yield=base_market_data.dividend_yield, volatility=base_market_data.volatility, time_to_expiry=max(0, base_market_data.time_to_expiry - time_horizon / 252))
            simulated_value = portfolio.update_positions(simulated_market_data)
            pnl_change = simulated_value - base_value
            percentage_change = pnl_change / base_value * 100 if base_value != 0 else 0
            result = ScenarioResult(scenario_name=f'MC_Simulation_{i + 1}', scenario_type=ScenarioType.MONTE_CARLO, base_portfolio_value=base_value, scenario_portfolio_value=simulated_value, pnl_change=pnl_change, percentage_change=percentage_change, probability=1 / num_simulations, scenario_parameters={'final_spot_multiplier': final_spot_multiplier, 'time_horizon_days': time_horizon})
            results.append(result)
        except Exception as e:
            logger.warning(f'Error in MC simulation {i + 1}: {e}')
    return results

class PortfolioOptimizer:
    """Portfolio optimization for derivatives"""

    def __init__(self, objective: str='sharpe_ratio'):
        self.objective = objective

    def optimize_weights(self, expected_returns: np.ndarray, covariance_matrix: np.ndarray, constraints: Dict=None) -> Dict[str, Any]:
        """Optimize portfolio weights"""
        n_assets = len(expected_returns)
        if constraints is None:
            constraints = {'max_weight': 0.4, 'min_weight': -0.2, 'target_return': None}

        def objective_function(weights):
            portfolio_return = np.dot(weights, expected_returns)
            portfolio_variance = np.dot(weights.T, np.dot(covariance_matrix, weights))
            portfolio_std = np.sqrt(portfolio_variance)
            if self.objective == 'sharpe_ratio':
                return -portfolio_return / portfolio_std if portfolio_std > 0 else 0
            elif self.objective == 'min_variance':
                return portfolio_variance
            elif self.objective == 'max_return':
                return -portfolio_return
            else:
                return portfolio_variance
        constraint_list = [{'type': 'eq', 'fun': lambda w: np.sum(w) - 1}]
        if constraints.get('target_return'):
            constraint_list.append({'type': 'eq', 'fun': lambda w: np.dot(w, expected_returns) - constraints['target_return']})
        bounds = [(constraints.get('min_weight', -1), constraints.get('max_weight', 1)) for _ in range(n_assets)]
        initial_weights = np.array([1 / n_assets] * n_assets)
        try:
            result = minimize(objective_function, initial_weights, method='SLSQP', bounds=bounds, constraints=constraint_list)
            if result.success:
                optimal_weights = result.x
                optimal_return = np.dot(optimal_weights, expected_returns)
                optimal_variance = np.dot(optimal_weights.T, np.dot(covariance_matrix, optimal_weights))
                optimal_std = np.sqrt(optimal_variance)
                sharpe_ratio = optimal_return / optimal_std if optimal_std > 0 else 0
                return {'success': True, 'optimal_weights': optimal_weights, 'expected_return': optimal_return, 'volatility': optimal_std, 'sharpe_ratio': sharpe_ratio, 'optimization_result': result}
            else:
                return {'success': False, 'message': result.message}
        except Exception as e:
            logger.error(f'Portfolio optimization failed: {e}')
            return {'success': False, 'message': str(e)}

def optimize_weights(self, expected_returns: np.ndarray, covariance_matrix: np.ndarray, constraints: Dict=None) -> Dict[str, Any]:
    """Optimize portfolio weights"""
    n_assets = len(expected_returns)
    if constraints is None:
        constraints = {'max_weight': 0.4, 'min_weight': -0.2, 'target_return': None}

    def objective_function(weights):
        portfolio_return = np.dot(weights, expected_returns)
        portfolio_variance = np.dot(weights.T, np.dot(covariance_matrix, weights))
        portfolio_std = np.sqrt(portfolio_variance)
        if self.objective == 'sharpe_ratio':
            return -portfolio_return / portfolio_std if portfolio_std > 0 else 0
        elif self.objective == 'min_variance':
            return portfolio_variance
        elif self.objective == 'max_return':
            return -portfolio_return
        else:
            return portfolio_variance
    constraint_list = [{'type': 'eq', 'fun': lambda w: np.sum(w) - 1}]
    if constraints.get('target_return'):
        constraint_list.append({'type': 'eq', 'fun': lambda w: np.dot(w, expected_returns) - constraints['target_return']})
    bounds = [(constraints.get('min_weight', -1), constraints.get('max_weight', 1)) for _ in range(n_assets)]
    initial_weights = np.array([1 / n_assets] * n_assets)
    try:
        result = minimize(objective_function, initial_weights, method='SLSQP', bounds=bounds, constraints=constraint_list)
        if result.success:
            optimal_weights = result.x
            optimal_return = np.dot(optimal_weights, expected_returns)
            optimal_variance = np.dot(optimal_weights.T, np.dot(covariance_matrix, optimal_weights))
            optimal_std = np.sqrt(optimal_variance)
            sharpe_ratio = optimal_return / optimal_std if optimal_std > 0 else 0
            return {'success': True, 'optimal_weights': optimal_weights, 'expected_return': optimal_return, 'volatility': optimal_std, 'sharpe_ratio': sharpe_ratio, 'optimization_result': result}
        else:
            return {'success': False, 'message': result.message}
    except Exception as e:
        logger.error(f'Portfolio optimization failed: {e}')
        return {'success': False, 'message': str(e)}

def objective_function(weights):
    portfolio_return = np.dot(weights, expected_returns)
    portfolio_variance = np.dot(weights.T, np.dot(covariance_matrix, weights))
    portfolio_std = np.sqrt(portfolio_variance)
    if self.objective == 'sharpe_ratio':
        return -portfolio_return / portfolio_std if portfolio_std > 0 else 0
    elif self.objective == 'min_variance':
        return portfolio_variance
    elif self.objective == 'max_return':
        return -portfolio_return
    else:
        return portfolio_variance

def standardize_data_format(data, name='data'):
    """Convert any data format to a standardized DataFrame with proper index"""
    if data is None:
        return None
    if isinstance(data, pd.DataFrame):
        return data
    elif isinstance(data, pd.Series):
        df = pd.DataFrame({name: data})
        return df
    else:
        print(f'Unsupported data type: {type(data)}')
        return None

def get_base_stock_data():
    """Get the original OHLCV stock data"""
    for node_id, data in node_outputs.items():
        if isinstance(data, pd.DataFrame) and all((col in data.columns for col in ['Open', 'High', 'Low', 'Close', 'Volume'])):
            return data
    return None

def execute_moving_average_node(node_id, input_data, window):
    print(f'Executing MA node {node_id} with window {window}')
    if input_data is not None and (not input_data.empty):
        if 'Close' in input_data.columns:
            ma = input_data['Close'].rolling(window=window).mean()
            ma.name = f'MA{window}'
            ma_df = pd.DataFrame({f'MA{window}': ma})
            node_outputs[node_id] = ma_df
            dpg.set_value(f'{node_id}_status', f'✓ MA{window} calculated')
            print(f'MA calculated successfully for node {node_id}')
        else:
            dpg.set_value(f'{node_id}_status', '✗ No Close price data')
            print(f'No Close price data for MA node {node_id}')
    else:
        dpg.set_value(f'{node_id}_status', '✗ No input data')
        print(f'No input data for MA node {node_id}')

def execute_rsi_node(node_id, input_data, period=14):
    print(f'Executing RSI node {node_id} with period {period}')
    if input_data is not None and (not input_data.empty):
        if 'Close' in input_data.columns:
            close_prices = input_data['Close']
            delta = close_prices.diff()
            gain = delta.where(delta > 0, 0).rolling(window=period).mean()
            loss = (-delta.where(delta < 0, 0)).rolling(window=period).mean()
            rs = gain / loss
            rsi = 100 - 100 / (1 + rs)
            rsi_df = pd.DataFrame({f'RSI{period}': rsi})
            node_outputs[node_id] = rsi_df
            dpg.set_value(f'{node_id}_status', f'✓ RSI{period} calculated')
            print(f'RSI calculated successfully for node {node_id}')
        else:
            dpg.set_value(f'{node_id}_status', '✗ No Close price data')
            print(f'No Close price data for RSI node {node_id}')
    else:
        dpg.set_value(f'{node_id}_status', '✗ No input data')
        print(f'No input data for RSI node {node_id}')

def execute_bollinger_bands_node(node_id, input_data, window=20, std_dev=2):
    print(f'Executing Bollinger Bands node {node_id} with window {window}, std_dev {std_dev}')
    if input_data is not None and (not input_data.empty):
        if 'Close' in input_data.columns:
            close_prices = input_data['Close']
            sma = close_prices.rolling(window=window).mean()
            std = close_prices.rolling(window=window).std()
            upper_band = sma + std * std_dev
            lower_band = sma - std * std_dev
            bb_df = pd.DataFrame({'BB_Upper': upper_band, 'BB_Middle': sma, 'BB_Lower': lower_band})
            node_outputs[node_id] = bb_df
            dpg.set_value(f'{node_id}_status', f'✓ BB({window},{std_dev}) calculated')
            print(f'Bollinger Bands calculated successfully for node {node_id}')
        else:
            dpg.set_value(f'{node_id}_status', '✗ No Close price data')
    else:
        dpg.set_value(f'{node_id}_status', '✗ No input data')

def execute_advanced_signal_node(node_id, indicator1_data, indicator2_data, condition, entry_rule, exit_rule, risk_reward_ratio=2.0, stop_loss_pct=2.0):
    print(f'Executing Advanced Signal node {node_id}')
    base_data = get_base_stock_data()
    if base_data is None:
        dpg.set_value(f'{node_id}_status', '✗ No base stock data found')
        return
    if indicator1_data is None or indicator2_data is None:
        dpg.set_value(f'{node_id}_status', '✗ Need both indicators')
        return
    try:
        ind1_df = standardize_data_format(indicator1_data, 'ind1')
        ind2_df = standardize_data_format(indicator2_data, 'ind2')
        if ind1_df is None or ind2_df is None:
            dpg.set_value(f'{node_id}_status', '✗ Invalid indicator data')
            return
        ind1_col = ind1_df.columns[0]
        ind2_col = ind2_df.columns[0]
        combined_data = pd.concat([base_data['Open'], base_data['High'], base_data['Low'], base_data['Close'], ind1_df[ind1_col], ind2_df[ind2_col]], axis=1).dropna()
        combined_data.columns = ['Open', 'High', 'Low', 'Close', 'Indicator1', 'Indicator2']
        if combined_data.empty:
            dpg.set_value(f'{node_id}_status', '✗ No overlapping data')
            return
        print(f'Signal generation using {ind1_col} vs {ind2_col}, condition: {condition}')
        print(f'Data shape: {combined_data.shape}, Date range: {combined_data.index[0]} to {combined_data.index[-1]}')
        signals = combined_data.copy()
        signals['signal'] = 0
        signals['position'] = 0
        signals['entry_price'] = 0.0
        signals['stop_loss'] = 0.0
        signals['take_profit'] = 0.0
        signals['exit_reason'] = ''
        entry_signals = pd.Series(False, index=signals.index)
        if condition == 'Crossover':
            if entry_rule == 'Buy on Signal':
                entry_signals = (signals['Indicator1'] > signals['Indicator2']) & (signals['Indicator1'].shift(1) <= signals['Indicator2'].shift(1))
                print(f'Crossover logic: Fast MA > Slow MA with previous Fast MA <= previous Slow MA')
            elif entry_rule == 'Sell on Signal':
                entry_signals = (signals['Indicator1'] < signals['Indicator2']) & (signals['Indicator1'].shift(1) >= signals['Indicator2'].shift(1))
        elif condition == 'Greater Than':
            if entry_rule == 'Buy on Signal':
                entry_signals = (signals['Indicator1'] > signals['Indicator2']) & (signals['Indicator1'].shift(1) <= signals['Indicator2'].shift(1))
            else:
                entry_signals = (signals['Indicator1'] < signals['Indicator2']) & (signals['Indicator1'].shift(1) >= signals['Indicator2'].shift(1))
        elif condition == 'RSI Levels':
            if entry_rule == 'Buy on Signal':
                entry_signals = (signals['Indicator1'] > 30) & (signals['Indicator1'].shift(1) <= 30)
            else:
                entry_signals = (signals['Indicator1'] < 70) & (signals['Indicator1'].shift(1) >= 70)
        elif condition == 'Bollinger Breakout':
            if entry_rule == 'Buy on Signal':
                entry_signals = signals['Close'] > signals['Indicator2']
            else:
                entry_signals = signals['Close'] < signals['Indicator2']
        potential_entries = entry_signals.sum()
        print(f'Found {potential_entries} potential entry signals')
        in_position = False
        entry_price = 0.0
        stop_loss_price = 0.0
        take_profit_price = 0.0
        position_type = 0
        trade_count = 0
        signal_array = signals['signal'].values
        position_array = signals['position'].values
        entry_price_array = signals['entry_price'].values
        stop_loss_array = signals['stop_loss'].values
        take_profit_array = signals['take_profit'].values
        exit_reason_array = signals['exit_reason'].values.astype(object)
        for i in range(1, len(signals)):
            current_idx = signals.index[i]
            current_price = signals.iloc[i]['Close']
            current_high = signals.iloc[i]['High']
            current_low = signals.iloc[i]['Low']
            if not in_position and entry_signals.iloc[i]:
                entry_price = current_price
                position_type = 1 if entry_rule == 'Buy on Signal' else -1
                trade_count += 1
                if position_type == 1:
                    stop_loss_price = entry_price * (1 - stop_loss_pct / 100)
                    take_profit_price = entry_price * (1 + stop_loss_pct * risk_reward_ratio / 100)
                else:
                    stop_loss_price = entry_price * (1 + stop_loss_pct / 100)
                    take_profit_price = entry_price * (1 - stop_loss_pct * risk_reward_ratio / 100)
                signal_array[i] = position_type
                entry_price_array[i] = entry_price
                stop_loss_array[i] = stop_loss_price
                take_profit_array[i] = take_profit_price
                in_position = True
                print(f'ENTRY #{trade_count}: {entry_rule} at ${entry_price:.2f} on {current_idx.date()}')
                print(f'  SL: ${stop_loss_price:.2f} (-{stop_loss_pct}%), TP: ${take_profit_price:.2f} (+{stop_loss_pct * risk_reward_ratio}%)')
            elif in_position:
                should_exit = False
                exit_reason = ''
                exit_price = current_price
                if position_type == 1:
                    if current_low <= stop_loss_price:
                        should_exit = True
                        exit_reason = 'Stop Loss'
                        exit_price = stop_loss_price
                    elif current_high >= take_profit_price:
                        should_exit = True
                        exit_reason = 'Take Profit'
                        exit_price = take_profit_price
                elif position_type == -1:
                    if current_high >= stop_loss_price:
                        should_exit = True
                        exit_reason = 'Stop Loss'
                        exit_price = stop_loss_price
                    elif current_low <= take_profit_price:
                        should_exit = True
                        exit_reason = 'Take Profit'
                        exit_price = take_profit_price
                if not should_exit and exit_rule == 'Opposite Signal':
                    if condition == 'Crossover':
                        if position_type == 1:
                            if signals.iloc[i]['Indicator1'] < signals.iloc[i]['Indicator2'] and signals.iloc[i - 1]['Indicator1'] >= signals.iloc[i - 1]['Indicator2']:
                                should_exit = True
                                exit_reason = 'Opposite Signal'
                        elif signals.iloc[i]['Indicator1'] > signals.iloc[i]['Indicator2'] and signals.iloc[i - 1]['Indicator1'] <= signals.iloc[i - 1]['Indicator2']:
                            should_exit = True
                            exit_reason = 'Opposite Signal'
                if should_exit:
                    signal_array[i] = -position_type
                    exit_reason_array[i] = exit_reason
                    in_position = False
                    pnl = (exit_price - entry_price) * position_type
                    pnl_pct = pnl / entry_price * 100
                    print(f'EXIT #{trade_count}: {exit_reason} at ${exit_price:.2f} on {current_idx.date()}')
                    print(f'  P&L: ${pnl:.2f} ({pnl_pct:+.2f}%)')
                    position_type = 0
        if in_position:
            final_idx = signals.index[-1]
            final_price = signals.iloc[-1]['Close']
            signal_array[-1] = -position_type
            exit_reason_array[-1] = 'End of Data'
            pnl = (final_price - entry_price) * position_type
            pnl_pct = pnl / entry_price * 100
            print(f'FINAL EXIT #{trade_count}: End of data at ${final_price:.2f}')
            print(f'  P&L: ${pnl:.2f} ({pnl_pct:+.2f}%)')
        signals.loc[:, 'signal'] = signal_array
        signals.loc[:, 'entry_price'] = entry_price_array
        signals.loc[:, 'stop_loss'] = stop_loss_array
        signals.loc[:, 'take_profit'] = take_profit_array
        signals.loc[:, 'exit_reason'] = exit_reason_array
        current_pos = 0
        for i in range(len(signals)):
            if signal_array[i] != 0:
                if current_pos == 0:
                    current_pos = signal_array[i]
                else:
                    current_pos = 0
            position_array[i] = current_pos
        signals.loc[:, 'position'] = position_array
        signals['position_change'] = signals['position'].diff().fillna(0)
        signals['strategy'] = f'{ind1_col}_{condition}_{ind2_col}'
        signals['entry_rule'] = entry_rule
        signals['exit_rule'] = exit_rule
        signals['risk_reward'] = risk_reward_ratio
        signals['stop_loss_pct'] = stop_loss_pct
        buy_signals_generated = (signals['signal'] == 1).sum()
        sell_signals_generated = (signals['signal'] == -1).sum()
        print(f'DEBUG: Generated {buy_signals_generated} buy signals and {sell_signals_generated} sell signals')
        signal_rows = signals[signals['signal'] != 0][['Close', 'signal', 'entry_price', 'stop_loss', 'take_profit', 'exit_reason']].head(10)
        print(f'DEBUG: First 10 signal rows:')
        print(signal_rows)
        node_outputs[node_id] = signals
        entries = len(signals[signals['signal'] > 0])
        exits = len(signals[signals['signal'] < 0])
        actual_trades = min(entries, exits)
        dpg.set_value(f'{node_id}_status', f'✓ {actual_trades} complete trades generated')
        print(f'Signal generation complete: {actual_trades} trades from {entries} entries and {exits} exits')
    except Exception as e:
        dpg.set_value(f'{node_id}_status', f'✗ Error: {str(e)[:30]}')
        print(f'Error in advanced signal generation for node {node_id}: {e}')
        import traceback
        traceback.print_exc()

def execute_professional_backtest_node(node_id, signals_data, initial_capital=10000, commission=0.001):
    print(f'Executing Professional Backtest node {node_id}')
    if signals_data is None or not isinstance(signals_data, pd.DataFrame):
        dpg.set_value(f'{node_id}_status', '✗ Need valid signals data')
        return
    required_cols = ['Close', 'signal']
    if not all((col in signals_data.columns for col in required_cols)):
        missing = [col for col in required_cols if col not in signals_data.columns]
        dpg.set_value(f'{node_id}_status', f'✗ Missing: {missing}')
        return
    try:
        signals = signals_data.copy()
        signal_trades = signals[signals['signal'] != 0]
        buy_signals = signals[signals['signal'] == 1]
        sell_signals = signals[signals['signal'] == -1]
        print(f'Signal Analysis:')
        print(f'  Total signals: {len(signal_trades)}')
        print(f'  Buy signals (1): {len(buy_signals)}')
        print(f'  Sell signals (-1): {len(sell_signals)}')
        print(f'  Signal range: {signals['signal'].min()} to {signals['signal'].max()}')
        unique_signals = signals['signal'].unique()
        print(f'  Unique signal values: {unique_signals}')
        if signal_trades.empty:
            dpg.set_value(f'{node_id}_status', '✗ No trades found in signals')
            print('No trades found in signal data')
            return
        print(f'Found {len(signal_trades)} signal entries in data')
        portfolio = pd.DataFrame(index=signals.index)
        portfolio['price'] = signals['Close']
        portfolio['signal'] = signals['signal']
        portfolio['shares'] = 0.0
        portfolio['cash'] = float(initial_capital)
        portfolio['commission'] = 0.0
        portfolio['trade_type'] = ''
        portfolio['trade_value'] = 0.0
        portfolio['realized_pnl'] = 0.0
        shares_held = 0.0
        cash = float(initial_capital)
        total_commission = 0.0
        entry_price = 0.0
        trades = []
        total_trades = 0
        print(f'Starting backtest with ${initial_capital:,.2f} initial capital')
        for i, (date, row) in enumerate(portfolio.iterrows()):
            current_price = row['price']
            signal = row['signal']
            if i == 0:
                portfolio.loc[date, 'shares'] = shares_held
                portfolio.loc[date, 'cash'] = cash
                portfolio.loc[date, 'trade_type'] = 'START'
                continue
            commission_cost = 0.0
            trade_value = 0.0
            realized_pnl = 0.0
            trade_type = 'HOLD'
            if signal != 0:
                print(f'Processing signal {signal} on {date.date()} at price ${current_price:.2f}')
            if signal == 1 or signal == 1.0:
                print(f'  -> BUY signal detected')
                if shares_held == 0:
                    available_cash = cash * 0.95
                    effective_price = current_price * (1 + commission)
                    shares_to_buy = available_cash / effective_price
                    trade_value = shares_to_buy * current_price
                    commission_cost = trade_value * commission
                    total_cost = trade_value + commission_cost
                    print(f'  Available cash: ${available_cash:.2f}')
                    print(f'  Trade value: ${trade_value:.2f}')
                    print(f'  Commission: ${commission_cost:.2f}')
                    print(f'  Total cost: ${total_cost:.2f}')
                    if available_cash >= total_cost:
                        shares_held = shares_to_buy
                        cash -= total_cost
                        entry_price = current_price
                        trade_type = 'BUY'
                        total_commission += commission_cost
                        total_trades += 1
                        trades.append({'date': date, 'type': 'BUY', 'shares': shares_to_buy, 'price': current_price, 'value': trade_value, 'commission': commission_cost})
                        print(f'  EXECUTED BUY #{total_trades}: {shares_to_buy:.2f} shares at ${current_price:.2f} = ${trade_value:.2f}')
                        print(f'  Cash remaining: ${cash:.2f}')
                    else:
                        print(f'  INSUFFICIENT CASH: Need ${total_cost:.2f}, have ${available_cash:.2f}')
                else:
                    print(f'  ALREADY HOLDING: {shares_held:.2f} shares')
            elif signal == -1 or signal == -1.0:
                print(f'  -> SELL signal detected')
                if shares_held > 0:
                    trade_value = shares_held * current_price
                    commission_cost = trade_value * commission
                    proceeds = trade_value - commission_cost
                    cost_basis = shares_held * entry_price
                    realized_pnl = trade_value - cost_basis - commission_cost
                    cash += proceeds
                    trade_type = 'SELL'
                    total_commission += commission_cost
                    trades.append({'date': date, 'type': 'SELL', 'shares': shares_held, 'price': current_price, 'value': trade_value, 'commission': commission_cost, 'pnl': realized_pnl, 'entry_price': entry_price})
                    print(f'  EXECUTED SELL: {shares_held:.2f} shares at ${current_price:.2f} = ${trade_value:.2f}, P&L: ${realized_pnl:.2f}')
                    shares_held = 0.0
                    entry_price = 0.0
                else:
                    print(f'  NO SHARES TO SELL')
            portfolio.loc[date, 'shares'] = shares_held
            portfolio.loc[date, 'cash'] = cash
            portfolio.loc[date, 'commission'] = commission_cost
            portfolio.loc[date, 'trade_type'] = trade_type
            portfolio.loc[date, 'trade_value'] = trade_value
            portfolio.loc[date, 'realized_pnl'] = realized_pnl
        if shares_held > 0:
            final_date = portfolio.index[-1]
            final_price = portfolio.loc[final_date, 'price']
            final_value = shares_held * final_price
            final_commission = final_value * commission
            final_proceeds = final_value - final_commission
            cost_basis = shares_held * entry_price
            final_pnl = final_value - cost_basis - final_commission
            cash += final_proceeds
            total_commission += final_commission
            trades.append({'date': final_date, 'type': 'FINAL_SELL', 'shares': shares_held, 'price': final_price, 'value': final_value, 'commission': final_commission, 'pnl': final_pnl, 'entry_price': entry_price})
            portfolio.loc[final_date, 'shares'] = 0.0
            portfolio.loc[final_date, 'cash'] = cash
            portfolio.loc[final_date, 'commission'] = final_commission
            portfolio.loc[final_date, 'trade_type'] = 'FINAL_SELL'
            portfolio.loc[final_date, 'trade_value'] = final_value
            portfolio.loc[final_date, 'realized_pnl'] = final_pnl
            print(f'FINAL SELL: {shares_held:.2f} shares at ${final_price:.2f} = ${final_value:.2f}, P&L: ${final_pnl:.2f}')
        portfolio['stock_value'] = portfolio['shares'] * portfolio['price']
        portfolio['total_value'] = portfolio['cash'] + portfolio['stock_value']
        portfolio['returns'] = portfolio['total_value'].pct_change()
        portfolio['cumulative_returns'] = (portfolio['total_value'] / initial_capital - 1) * 100
        final_value = portfolio['total_value'].iloc[-1]
        total_return = (final_value - initial_capital) / initial_capital * 100
        buy_trades = [t for t in trades if t['type'] in ['BUY']]
        sell_trades = [t for t in trades if t['type'] in ['SELL', 'FINAL_SELL']]
        actual_trade_count = len(buy_trades)
        winning_trades = len([t for t in sell_trades if t.get('pnl', 0) > 0])
        losing_trades = len([t for t in sell_trades if t.get('pnl', 0) < 0])
        win_rate = winning_trades / len(sell_trades) * 100 if sell_trades else 0
        returns_series = portfolio['returns'].dropna()
        if len(returns_series) > 0:
            avg_return = returns_series.mean()
            volatility = returns_series.std()
            sharpe_ratio = avg_return / volatility * np.sqrt(252) if volatility != 0 else 0
            running_max = portfolio['total_value'].expanding().max()
            drawdown = (portfolio['total_value'] - running_max) / running_max
            max_drawdown = drawdown.min() * 100
            profitable_trades = [t['pnl'] for t in sell_trades if t.get('pnl', 0) > 0]
            losing_trades_pnl = [t['pnl'] for t in sell_trades if t.get('pnl', 0) < 0]
            avg_win = np.mean(profitable_trades) if profitable_trades else 0
            avg_loss = np.mean(losing_trades_pnl) if losing_trades_pnl else 0
            profit_factor = abs(avg_win / avg_loss) if avg_loss != 0 else float('inf')
        else:
            sharpe_ratio = 0
            max_drawdown = 0
            avg_win = 0
            avg_loss = 0
            profit_factor = 0
        node_outputs[node_id] = portfolio
        dpg.set_value(f'{node_id}_status', f'✓ Return: {total_return:.2f}%')
        results_text = f'PERFORMANCE METRICS:\nTotal Return: {total_return:.2f}%\nFinal Value: ${final_value:,.2f}\nMax Drawdown: {max_drawdown:.2f}%\nSharpe Ratio: {sharpe_ratio:.2f}\n\nTRADING STATISTICS:\nTotal Trades: {actual_trade_count}\nWinning Trades: {winning_trades}\nLosing Trades: {losing_trades}\nWin Rate: {win_rate:.1f}%\nAvg Win: ${avg_win:.2f}\nAvg Loss: ${avg_loss:.2f}\nProfit Factor: {profit_factor:.2f}\n\nCOSTS:\nTotal Commission: ${total_commission:.2f}\nCommission %: {total_commission / initial_capital * 100:.3f}%\n\nSTRATEGY: {(signals_data.get('strategy', ['N/A']).iloc[0] if 'strategy' in signals_data.columns else 'N/A')}'
        dpg.set_value(f'{node_id}_results_text', results_text)
        print(f'Professional backtest completed for node {node_id}: {total_return:.2f}% return, {actual_trade_count} trades')
        print(f'Trade Summary: {winning_trades} wins, {losing_trades} losses, {win_rate:.1f}% win rate')
    except Exception as e:
        dpg.set_value(f'{node_id}_status', f'✗ Error: {str(e)[:30]}')
        print(f'Error in professional backtest for node {node_id}: {e}')
        import traceback
        traceback.print_exc()

def find_stock_data():
    """Find the original stock data DataFrame from any stock data node"""
    for node_id, data in node_outputs.items():
        if isinstance(data, pd.DataFrame) and all((col in data.columns for col in ['Open', 'High', 'Low', 'Close', 'Volume'])):
            return data
    return None

class TechnicalIndicatorProcessor:
    """Advanced technical indicator calculations"""

    @staticmethod
    def calculate_sma(data: pd.DataFrame, period: int) -> pd.Series:
        """Calculate Simple Moving Average"""
        return data['Close'].rolling(window=period).mean()

    @staticmethod
    def calculate_ema(data: pd.DataFrame, period: int) -> pd.Series:
        """Calculate Exponential Moving Average"""
        return data['Close'].ewm(span=period, adjust=False).mean()

    @staticmethod
    def calculate_bollinger_bands(data: pd.DataFrame, period: int=20, std_dev: float=2) -> pd.DataFrame:
        """Calculate Bollinger Bands"""
        sma = data['Close'].rolling(window=period).mean()
        std = data['Close'].rolling(window=period).std()
        return pd.DataFrame({'BB_Upper': sma + std * std_dev, 'BB_Middle': sma, 'BB_Lower': sma - std * std_dev, 'BB_Width': sma + std * std_dev - (sma - std * std_dev), 'BB_Percent': (data['Close'] - (sma - std * std_dev)) / (sma + std * std_dev - (sma - std * std_dev))})

    @staticmethod
    def calculate_macd(data: pd.DataFrame, fast: int=12, slow: int=26, signal: int=9) -> pd.DataFrame:
        """Calculate MACD"""
        ema_fast = data['Close'].ewm(span=fast, adjust=False).mean()
        ema_slow = data['Close'].ewm(span=slow, adjust=False).mean()
        macd_line = ema_fast - ema_slow
        signal_line = macd_line.ewm(span=signal, adjust=False).mean()
        histogram = macd_line - signal_line
        return pd.DataFrame({'MACD': macd_line, 'MACD_Signal': signal_line, 'MACD_Histogram': histogram})

    @staticmethod
    def calculate_rsi(data: pd.DataFrame, period: int=14) -> pd.Series:
        """Calculate RSI with enhanced features"""
        close_delta = data['Close'].diff()
        gain = close_delta.where(close_delta > 0, 0).rolling(window=period).mean()
        loss = (-close_delta.where(close_delta < 0, 0)).rolling(window=period).mean()
        rs = gain / loss
        rsi = 100 - 100 / (1 + rs)
        return rsi

    @staticmethod
    def calculate_stochastic(data: pd.DataFrame, k_period: int=14, d_period: int=3) -> pd.DataFrame:
        """Calculate Stochastic Oscillator"""
        low_min = data['Low'].rolling(window=k_period).min()
        high_max = data['High'].rolling(window=k_period).max()
        k_percent = 100 * ((data['Close'] - low_min) / (high_max - low_min))
        d_percent = k_percent.rolling(window=d_period).mean()
        return pd.DataFrame({'Stoch_K': k_percent, 'Stoch_D': d_percent})

    @staticmethod
    def calculate_atr(data: pd.DataFrame, period: int=14) -> pd.Series:
        """Calculate Average True Range"""
        high_low = data['High'] - data['Low']
        high_close = np.abs(data['High'] - data['Close'].shift())
        low_close = np.abs(data['Low'] - data['Close'].shift())
        true_range = pd.concat([high_low, high_close, low_close], axis=1).max(axis=1)
        atr = true_range.rolling(window=period).mean()
        return atr

    @staticmethod
    def calculate_ichimoku(data: pd.DataFrame) -> pd.DataFrame:
        """Calculate Ichimoku Cloud"""
        nine_period_high = data['High'].rolling(window=9).max()
        nine_period_low = data['Low'].rolling(window=9).min()
        tenkan_sen = (nine_period_high + nine_period_low) / 2
        period26_high = data['High'].rolling(window=26).max()
        period26_low = data['Low'].rolling(window=26).min()
        kijun_sen = (period26_high + period26_low) / 2
        senkou_span_a = ((tenkan_sen + kijun_sen) / 2).shift(26)
        period52_high = data['High'].rolling(window=52).max()
        period52_low = data['Low'].rolling(window=52).min()
        senkou_span_b = ((period52_high + period52_low) / 2).shift(26)
        chikou_span = data['Close'].shift(-26)
        return pd.DataFrame({'Tenkan_sen': tenkan_sen, 'Kijun_sen': kijun_sen, 'Senkou_Span_A': senkou_span_a, 'Senkou_Span_B': senkou_span_b, 'Chikou_Span': chikou_span})

