def analyze_growth_environment_performance(financial_line_items: list) -> float:
    """Performance in rising growth environment"""
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 3:
        growth_periods = sum((1 for i in range(len(revenues) - 1) if revenues[i] > revenues[i + 1]))
        return growth_periods / (len(revenues) - 1)
    return 0.5

def analyze_recession_resilience(financial_line_items: list) -> float:
    """Resilience in falling growth environment"""
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if earnings:
        negative_years = sum((1 for e in earnings if e < 0))
        return 1 - negative_years / len(earnings)
    return 0.5

def calculate_mean_reversion_signals(metrics: list, financial_line_items: list) -> float:
    """Calculate mean reversion signals"""
    if not metrics:
        return 0.5
    pe_ratios = [m.price_to_earnings for m in metrics if m.price_to_earnings and m.price_to_earnings > 0]
    if len(pe_ratios) >= 4:
        current_pe = pe_ratios[0]
        historical_mean = sum(pe_ratios[1:]) / len(pe_ratios[1:])
        deviation = abs(current_pe - historical_mean) / historical_mean
        if current_pe < historical_mean * 0.8:
            return min(deviation, 1.0)
        elif current_pe > historical_mean * 1.2:
            return -min(deviation, 1.0)
    return 0.0

def calculate_momentum_signals(metrics: list, financial_line_items: list) -> float:
    """Calculate momentum signals"""
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 4:
        recent_growth = revenues[0] / revenues[1] - 1
        historical_growth = (revenues[1] / revenues[-1]) ** (1 / (len(revenues) - 2)) - 1
        momentum_strength = (recent_growth - historical_growth) / abs(historical_growth) if historical_growth != 0 else 0
        return max(min(momentum_strength, 1.0), -1.0)
    return 0.0

def calculate_statistical_significance(signals: dict) -> float:
    """Calculate overall statistical significance"""
    signal_values = [v for v in signals.values() if isinstance(v, (int, float))]
    if not signal_values:
        return 0.5
    signal_consistency = 1 - (max(signal_values) - min(signal_values)) / 2
    signal_strength = sum((abs(v) for v in signal_values)) / len(signal_values)
    return signal_consistency * 0.6 + signal_strength * 0.4

def calculate_maximum_drawdown_risk(financial_line_items: list) -> float:
    """Calculate maximum drawdown risk"""
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if earnings:
        peak = max(earnings)
        trough = min(earnings)
        if peak > 0:
            return abs(trough - peak) / peak
    return 0.5

def detect_regime_changes(financial_line_items: list) -> float:
    """Detect regime changes in business fundamentals"""
    margins = []
    for item in financial_line_items:
        if item.net_income and item.revenue and (item.revenue > 0):
            margins.append(item.net_income / item.revenue)
    if len(margins) >= 4:
        recent_avg = sum(margins[:2]) / 2
        historical_avg = sum(margins[2:]) / len(margins[2:])
        if abs(recent_avg - historical_avg) > 0.05:
            return 0.8
    return 0.2

def calculate_autocorrelation(data: list, lag: int) -> float:
    """Calculate autocorrelation with given lag"""
    if len(data) <= lag:
        return 0
    mean_val = sum(data) / len(data)
    numerator = sum(((data[i] - mean_val) * (data[i + lag] - mean_val) for i in range(len(data) - lag)))
    denominator = sum(((x - mean_val) ** 2 for x in data))
    return numerator / denominator if denominator != 0 else 0

def calculate_coefficient_of_variation(data: list) -> float:
    """Calculate coefficient of variation"""
    if not data:
        return 1.0
    mean_val = sum(data) / len(data)
    if mean_val == 0:
        return 1.0
    variance = sum(((x - mean_val) ** 2 for x in data)) / len(data)
    std_dev = math.sqrt(variance)
    return std_dev / abs(mean_val)

def analyze_feature_interactions(features: dict) -> float:
    """Analyze feature interactions"""
    if not features:
        return 0
    interaction_score = 0
    feature_values = [v for v in features.values() if isinstance(v, (int, float))]
    if feature_values:
        mean_feature = sum(feature_values) / len(feature_values)
        interaction_score = min(mean_feature * len(feature_values) / 5, 2.0)
    return interaction_score

def calculate_coefficient_of_variation(data: list) -> float:
    """Calculate coefficient of variation"""
    if not data:
        return 1.0
    mean_val = sum(data) / len(data)
    if mean_val == 0:
        return 1.0
    variance = sum(((x - mean_val) ** 2 for x in data)) / len(data)
    std_dev = math.sqrt(variance)
    return std_dev / abs(mean_val)

def calculate_trend_strength(data: list) -> float:
    """Calculate trend strength"""
    if len(data) < 3:
        return 0
    n = len(data)
    x_mean = (n - 1) / 2
    y_mean = sum(data) / n
    numerator = sum(((i - x_mean) * (data[i] - y_mean) for i in range(n)))
    denominator = sum(((i - x_mean) ** 2 for i in range(n)))
    if denominator == 0:
        return 0
    slope = numerator / denominator
    return min(abs(slope) / (y_mean if y_mean != 0 else 1), 1.0)

def detect_seasonality(data: list) -> float:
    """Detect seasonality in data"""
    if len(data) < 8:
        return 0
    q1_avg = sum((data[i] for i in range(0, len(data), 4))) / ((len(data) + 3) // 4)
    q2_avg = sum((data[i] for i in range(1, len(data), 4))) / ((len(data) + 2) // 4)
    if q1_avg > 0:
        return min(abs(q2_avg - q1_avg) / q1_avg, 1.0)
    return 0

def calculate_mean_reversion_score(metrics: list) -> float:
    """Calculate mean reversion signal"""
    if len(metrics) < 4:
        return 0.0
    pe_ratios = [m.price_to_earnings for m in metrics if m.price_to_earnings and m.price_to_earnings > 0]
    if len(pe_ratios) >= 4:
        current_pe = pe_ratios[0]
        historical_mean = sum(pe_ratios[1:]) / len(pe_ratios[1:])
        if historical_mean > 0:
            deviation = (current_pe - historical_mean) / historical_mean
            return -deviation
    return 0.0

def analyze_volatility_patterns(financial_line_items: list) -> float:
    """Analyze earnings volatility"""
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if len(earnings) >= 4:
        mean_earnings = sum(earnings) / len(earnings)
        if mean_earnings != 0:
            variance = sum(((e - mean_earnings) ** 2 for e in earnings)) / len(earnings)
            cv = variance ** 0.5 / abs(mean_earnings)
            return min(cv, 1.0)
    return 0.5

def analyze_recession_performance(financial_line_items: list) -> float:
    """Analyze performance during economic downturns"""
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if earnings:
        negative_years = sum((1 for e in earnings if e < 0))
        return 1 - negative_years / len(earnings)
    return 0.5

def estimate_trading_volatility(financial_line_items: list) -> float:
    """Estimate trading volatility"""
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if revenues:
        mean_rev = sum(revenues) / len(revenues)
        if mean_rev > 0:
            variance = sum(((r - mean_rev) ** 2 for r in revenues)) / len(revenues)
            return variance ** 0.5 / mean_rev
    return 0.25

def analyze_capital_allocation_inefficiencies(financial_line_items: list) -> float:
    """Analyze capital allocation inefficiencies"""
    fcf_vals = [item.free_cash_flow for item in financial_line_items if item.free_cash_flow]
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if fcf_vals and earnings and (len(fcf_vals) == len(earnings)):
        total_fcf = sum(fcf_vals)
        total_earnings = sum(earnings)
        if total_earnings > 0:
            cash_conversion = total_fcf / total_earnings
            if cash_conversion < 0.6:
                return 0.8
            elif cash_conversion < 0.8:
                return 0.5
    return 0.3

def assess_management_performance(metrics: list, financial_line_items: list) -> float:
    """Assess management performance"""
    if not metrics:
        return 0.5
    roe_vals = [m.return_on_equity for m in metrics if m.return_on_equity]
    if len(roe_vals) >= 3:
        recent_roe = sum(roe_vals[:2]) / 2
        historical_roe = sum(roe_vals[2:]) / len(roe_vals[2:])
        if recent_roe > historical_roe * 1.2:
            return 0.8
        elif recent_roe < historical_roe * 0.8:
            return 0.3
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if len(revenues) >= 4:
        growth_years = sum((1 for i in range(len(revenues) - 1) if revenues[i] >= revenues[i + 1]))
        consistency = growth_years / (len(revenues) - 1)
        return consistency
    return 0.5

def analyze_board_independence_proxy(financial_line_items: list) -> float:
    """Analyze board independence (proxy through governance metrics)"""
    earnings = [item.net_income for item in financial_line_items if item.net_income]
    if earnings:
        positive_years = sum((1 for e in earnings if e > 0))
        return positive_years / len(earnings)
    return 0.6

def identify_esg_improvement_opportunities(financial_line_items: list) -> float:
    """Identify ESG improvement opportunities"""
    rd_vals = [item.research_and_development for item in financial_line_items if item.research_and_development]
    revenues = [item.revenue for item in financial_line_items if item.revenue]
    if rd_vals and revenues:
        rd_intensity = sum(rd_vals) / sum(revenues[:len(rd_vals)])
        if rd_intensity < 0.02:
            return 0.6
    return 0.4

